bool runtimeSessionGeometryAvailable(const RuntimeProductionHostState& state) noexcept { return state.geometry && state.geometry->available(); }

bool containsAsciiCaseInsensitive(
    const std::string& value,
    const std::string& needle) {
    if (needle.empty() || value.size() < needle.size()) {
        return false;
    }

    return std::search(
            value.begin(),
            value.end(),
            needle.begin(),
            needle.end(),
            [](char left, char right) {
                return std::tolower(static_cast<unsigned char>(left))
                    == std::tolower(static_cast<unsigned char>(right));
            }
        )
        != value.end();
}

int runtimeSectionEntryCount(
    const IniFile& ini,
    const std::string& sectionName) {
    const IniFile::Section* section = ini.getSection(sectionName);
    return section == nullptr ? 0 : static_cast<int>(section->size());
}

std::vector<std::string> runtimeIndexedIds(
    const IniFile& ini,
    const std::string& sectionName) {
    std::vector<std::string> ids;
    const IniFile::Section* section = ini.getSection(sectionName);
    if (section == nullptr) {
        return ids;
    }

    struct IndexedValue {
        bool numeric = false;
        int index = 0;
        std::size_t order = 0;
        std::string value;
    };
    std::vector<IndexedValue> values;
    values.reserve(section->size());
    for (std::size_t order = 0; order < section->size(); ++order) {
        const auto& [indexText, value] = (*section)[order];
        IndexedValue indexed;
        indexed.numeric = parseRuntimeInt(indexText, indexed.index);
        indexed.order = order;
        indexed.value = trimAsciiLocal(value);
        values.push_back(std::move(indexed));
    }
    std::stable_sort(
        values.begin(),
        values.end(),
        [](const IndexedValue& left, const IndexedValue& right) {
            if (left.numeric != right.numeric) {
                return left.numeric;
            }
            if (left.numeric && left.index != right.index) {
                return left.index < right.index;
            }
            return left.order < right.order;
        }
    );

    ids.reserve(values.size());
    for (const IndexedValue& indexed : values) {
        const std::string& id = indexed.value;
        if (!id.empty()) {
            ids.push_back(id);
        }
    }
    return ids;
}

std::string runtimeWaypointKeyFromName(const std::string& value) {
    const std::string trimmed = trimAsciiLocal(value);
    if (trimmed.empty()) {
        return "";
    }

    int numeric = 0;
    if (parseRuntimeInt(trimmed, numeric)) {
        return std::to_string(numeric);
    }

    int waypoint = 0;
    for (char character : toUpperAsciiLocal(trimmed)) {
        if (character < 'A' || character > 'Z') {
            return trimmed;
        }
        waypoint = (waypoint * 26) + (character - 'A' + 1);
    }
    return waypoint <= 0 ? trimmed : std::to_string(waypoint - 1);
}

std::vector<std::string> unitPaletteCandidatesForRuntimeTheater(
    const std::string& theater) {
    const std::string lower = toLowerAsciiLocal(theater);
    if (lower == "temperate") {
        return {"cachemd_unittem.pal", "cache_unittem.pal", "unittem.pal"};
    }
    if (lower == "snow") {
        return {"cachemd_unitsno.pal", "cache_unitsno.pal", "unitsno.pal"};
    }
    if (lower == "urban") {
        return {"cachemd_uniturb.pal", "cache_uniturb.pal", "uniturb.pal"};
    }
    if (lower == "newurban") {
        return {"cachemd_unitubn.pal", "cache_unitubn.pal", "unitubn.pal"};
    }
    if (lower == "desert") {
        return {"cachemd_unitdes.pal", "cache_unitdes.pal", "unitdes.pal"};
    }
    if (lower == "lunar") {
        return {"cachemd_unitlun.pal", "cache_unitlun.pal", "unitlun.pal"};
    }
    return {};
}

std::string formatMaybe(const std::string& value) {
    return value.empty() ? "-" : value;
}

bool isExistingDirectory(const std::string& path) {
    if (path.empty()) {
        return false;
    }

    std::error_code errorCode;
    return std::filesystem::exists(path, errorCode)
        && std::filesystem::is_directory(path, errorCode);
}

bool isExistingRegularFile(const std::string& path) {
    if (path.empty()) {
        return false;
    }

    std::error_code errorCode;
    return std::filesystem::exists(path, errorCode)
        && std::filesystem::is_regular_file(path, errorCode);
}

