bool runtimeIsNavalWarMode(const RuntimeGameSessionState& state) {
    return runtimeSkirmishModeMatches(state, "NAVALWAR", "MPNAVALMD.INI");
}

bool runtimeIsMegawealthMode(const RuntimeGameSessionState& state) {
    return runtimeSkirmishModeMatches(state, "MEGAWEALTH", "MPMWMD.INI");
}

bool runtimeIsLandRushMode(const RuntimeGameSessionState& state) {
    return runtimeSkirmishModeMatches(state, "DUEL", "MPDUELMD.INI");
}

bool runtimeIsUnholyAllianceMode(const RuntimeGameSessionState& state) {
    if (toUpperAsciiLocal(trimAsciiLocal(state.config.gameMode))
        == "UNHOLYALLIANCE") {
        return true;
    }
    const auto isUnholyRules = [](const std::string& path) {
        return toUpperAsciiLocal(std::filesystem::path(path).filename().string())
            == "MPUNHOLYMD.INI";
    };
    // Catalogs are created before the resolved mode rules path is populated.
    return isUnholyRules(state.config.gameModeRulesOverride)
        || isUnholyRules(state.skirmishModeRulesPath);
}

