std::string runtimeCanonicalHumanHouseOwner(const std::string& owner) {
    return toLowerAsciiLocal(trimAsciiLocal(owner));
}

RuntimeHumanHouseAuthority* findRuntimeHumanHouseAuthority(
    RuntimeGameSessionState& state,
    const std::string& owner) {
    const std::string wanted = runtimeCanonicalHumanHouseOwner(owner);
    const auto found = std::find_if(
        state.humanHouseAuthorities.begin(),
        state.humanHouseAuthorities.end(),
        [&wanted](const RuntimeHumanHouseAuthority& authority) {
            return authority.canonicalOwner == wanted;
        }
    );
    return found == state.humanHouseAuthorities.end() ? nullptr : &*found;
}

const RuntimeHumanHouseAuthority* findRuntimeHumanHouseAuthority(
    const RuntimeGameSessionState& state,
    const std::string& owner) {
    const std::string wanted = runtimeCanonicalHumanHouseOwner(owner);
    const auto found = std::find_if(
        state.humanHouseAuthorities.begin(),
        state.humanHouseAuthorities.end(),
        [&wanted](const RuntimeHumanHouseAuthority& authority) {
            return authority.canonicalOwner == wanted;
        }
    );
    return found == state.humanHouseAuthorities.end() ? nullptr : &*found;
}

bool runtimeNoCooldownForOwner(const RuntimeGameSessionState& state, const std::string& owner) {
    if (!state.config.noCooldown || state.config.multiplayerActive || state.campaignMode
        || toLowerAsciiLocal(state.config.gameMode) == "campaignmission") return false;
    if (!state.humanHouseAuthorities.empty()) {
        const auto* authority = findRuntimeHumanHouseAuthority(state, owner);
        return authority && authority->localFacade;
    }
    return !owner.empty() && runtimeCanonicalHumanHouseOwner(owner)
        == runtimeCanonicalHumanHouseOwner(state.economy.owner);
}

std::string runtimeCountryForOwner(
    const RuntimeGameSessionState& state,
    const std::string& owner) {
    std::string ownerKey = toLowerAsciiLocal(trimAsciiLocal(owner));
    if (state.campaignMode) {
        const auto alias =
            state.triggers.campaignCanonicalHouseByAlias.find(ownerKey);
        if (alias != state.triggers.campaignCanonicalHouseByAlias.end()) {
            ownerKey = toLowerAsciiLocal(trimAsciiLocal(alias->second));
        }
        const auto country =
            state.triggers.campaignCountryByHouse.find(ownerKey);
        if (country != state.triggers.campaignCountryByHouse.end()) {
            return country->second;
        }
    }
    const auto found = state.skirmishCountryByOwner.find(ownerKey);
    return found == state.skirmishCountryByOwner.end()
        ? trimAsciiLocal(owner)
        : found->second;
}

bool runtimeOwnersAreAllied(
    const RuntimeGameSessionState& state,
    const std::string& leftOwner,
    const std::string& rightOwner) {
    std::string leftKey = toLowerAsciiLocal(trimAsciiLocal(leftOwner));
    std::string rightKey = toLowerAsciiLocal(trimAsciiLocal(rightOwner));
    if (state.campaignMode) {
        const auto leftAlias =
            state.triggers.campaignCanonicalHouseByAlias.find(leftKey);
        if (leftAlias != state.triggers.campaignCanonicalHouseByAlias.end()) {
            leftKey = toLowerAsciiLocal(trimAsciiLocal(leftAlias->second));
        }
        const auto rightAlias =
            state.triggers.campaignCanonicalHouseByAlias.find(rightKey);
        if (rightAlias != state.triggers.campaignCanonicalHouseByAlias.end()) {
            rightKey = toLowerAsciiLocal(trimAsciiLocal(rightAlias->second));
        }
    }
    if (leftKey.empty() || rightKey.empty()) {
        return false;
    }
    if (leftKey == rightKey) {
        return true;
    }

    if (state.campaignMode) {
        const std::string pair = leftKey < rightKey
            ? leftKey + "|" + rightKey
            : rightKey + "|" + leftKey;
        if (state.triggers.campaignAlliedPairs.find(pair)
            != state.triggers.campaignAlliedPairs.end()) {
            return true;
        }
    }

    const std::string mode =
        toUpperAsciiLocal(trimAsciiLocal(state.config.gameMode));

    if (mode == "COOPERATIVE" && state.cooperativeSession.active()) {
        const std::optional<int> leftSlot =
            runtimeCooperativeSlotForOwner(state, leftOwner);
        const std::optional<int> rightSlot =
            runtimeCooperativeSlotForOwner(state, rightOwner);
        // Once either side is a cooperative A-D participant, the fixed
        // session matrix is authoritative. This also relates an authored
        // <Player @ X>/447X alias to its bound runtime player owner.
        if (leftSlot.has_value() || rightSlot.has_value()) {
            return leftSlot.has_value()
                && rightSlot.has_value()
                && state.cooperativeSession.slotsAreAllied(
                    *leftSlot,
                    *rightSlot
                );
        }
    }

    if ((state.skirmishModeRulesLoaded
            && !state.skirmishModeAlliesAllowed)
        || (!state.skirmishModeRulesLoaded && mode == "FREEFORALL")) {
        return false;
    }

    const auto leftTeam = state.skirmishTeamByOwner.find(leftKey);
    const auto rightTeam = state.skirmishTeamByOwner.find(rightKey);
    const bool startingAllies = leftTeam != state.skirmishTeamByOwner.end()
        && rightTeam != state.skirmishTeamByOwner.end()
        && !leftTeam->second.empty()
        && leftTeam->second == rightTeam->second;
    const auto leftOffer = state.playerCommands.alliances.find({leftKey, rightKey});
    const auto rightOffer = state.playerCommands.alliances.find({rightKey, leftKey});
    return (leftOffer == state.playerCommands.alliances.end() ? startingAllies : leftOffer->second)
        && (rightOffer == state.playerCommands.alliances.end() ? startingAllies : rightOffer->second);
}

bool runtimeObserverOwner(const RuntimeGameSessionState& state, const std::string& owner) {
    if (state.campaignMode || state.config.multiplayerActive) return false;
    const auto country = state.skirmishCountryByOwner.find(toLowerAsciiLocal(trimAsciiLocal(owner)));
    return country != state.skirmishCountryByOwner.end()
        ? runtimeObserverCountry(country->second) : runtimeObserverCountry(owner);
}

bool updateRuntimeVisionState(RuntimeProductionHostState& state) {
    RuntimeSessionVisionPhaseOperations operations(state);
    RuntimeVisionPhaseContext context = runtimeVisionPhaseContext(state);
    return updateRuntimeVisionState(context, operations);
}

bool runtimeObjectHiddenFromOwnerByStealth(
    const RuntimeGameSessionState& state,
    const std::string& observerOwner,
    const WorldObjectInstance& object) {
    if (state.specialMechanismsInitialized) {
        if (state.specialMechanisms.isChronoInTransit(object.instanceId)
            || state.specialMechanisms.isCarrierChildDocked(
                object.instanceId
            )) {
            return true;
        }
        if (state.specialMechanisms.isCamouflaged(object.instanceId)
            && observerOwner != object.owner
            && !runtimeOwnersAreAllied(state, observerOwner, object.owner)) {
            return true;
        }
    }
    if (object.cloaked
        && observerOwner != object.owner
        && !runtimeOwnersAreAllied(state, observerOwner, object.owner)) {
        return true;
    }
    return false;
}

bool runtimeObjectVisibleToOwner(
    const RuntimeGameSessionState& state,
    const std::string& observerOwner,
    const WorldObjectInstance& object) {
    if (runtimeInvisibleMapBuilding(state.rulesLoaded ? &state.rules : nullptr, object)) return false;
    if (state.rulesLoaded && object.kind == WorldObjectKind::Structure) {
        const auto* building = state.rules.findBuildingType(object.type);
        if (building && toLowerAsciiLocal(building->image) == "null") return false;
    }
    if (runtimeObserverOwner(state, observerOwner)) return object.alive;
    if (runtimeObjectHiddenFromOwnerByStealth(
            state,
            observerOwner,
            object
        )) {
        return false;
    }
    return !state.visionEnabled
        || !state.vision.hasObserver(observerOwner)
        || state.vision.isObjectVisibleTo(observerOwner, object);
}

RuntimeSnapshotCell toRuntimeSnapshotCell(const RuntimeCellPoint& cell) {
    return {cell.x, cell.y};
}

std::uint64_t runtimeObjectIdSetHash(
    const std::unordered_set<int>* objectIds) {
    std::uint64_t hash = 1469598103934665603ull;
    if (objectIds == nullptr || objectIds->empty()) {
        runtimeStableHashMix(hash, 0);
        return hash;
    }

    std::vector<int> sortedIds(objectIds->begin(), objectIds->end());
    std::sort(sortedIds.begin(), sortedIds.end());
    runtimeStableHashMix(hash, static_cast<long long>(sortedIds.size()));
    for (int objectId : sortedIds) {
        runtimeStableHashMix(hash, objectId);
    }
    return hash;
}

RuntimeLightingConfig runtimeLightingConfigForState(
    const RuntimeGameSessionState& state) {
    RuntimeLightingConfig config;
    config.fixedTickHz = std::max(1, state.config.fixedTickHz);
    if (state.rulesLoaded) {
        const SpecialMechanismRules& special =
            state.rules.getSpecialMechanismRules();
        config.ambientChangeRate = special.ambientChangeRate;
        config.ambientChangeStep = special.ambientChangeStep;
    }
    return config;
}

void ensureRuntimeLightingInitialized(RuntimeGameSessionState& state) {
    if (state.lightingInitialized) {
        return;
    }
    state.lighting.reset(
        state.mapFacts.lighting,
        runtimeLightingConfigForState(state)
    );
    (void)state.lighting.tick(std::max(0, state.tick));
    state.lightingInitialized = true;
}

void ensureRuntimeParticlesInitialized(RuntimeGameSessionState& state) {
    if (state.particlesInitialized) {
        return;
    }
    state.particles.reset(std::max(1, state.config.fixedTickHz));
    if (!state.particles.alignEmptyStateTick(std::max(0, state.tick))) {
        throw std::logic_error("could not align empty particle authority");
    }
    state.particlesInitialized = true;
    state.particleRenderSnapshots.clear();
    state.particleBeamRenderSnapshots.clear();
    state.particleLocalLightRenderSnapshots.clear();
}

std::vector<std::string> splitRuntimeWhitespaceTokens(const std::string& value) {
    std::vector<std::string> tokens;
    std::stringstream input(stripRuntimeSoundComment(value));
    std::string token;
    while (input >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

std::uint16_t runtimeReadLe16(const unsigned char* bytes) {
    return static_cast<std::uint16_t>(
        static_cast<std::uint16_t>(bytes[0])
        | (static_cast<std::uint16_t>(bytes[1]) << 8)
    );
}

std::uint32_t runtimeReadLe32(const unsigned char* bytes) {
    return static_cast<std::uint32_t>(bytes[0])
        | (static_cast<std::uint32_t>(bytes[1]) << 8)
        | (static_cast<std::uint32_t>(bytes[2]) << 16)
        | (static_cast<std::uint32_t>(bytes[3]) << 24);
}

int runtimeWavDurationTicks(
    const std::string& wavPath,
    int fixedTickHz) {
    std::ifstream input(wavPath, std::ios::binary);
    if (!input) {
        return std::max(1, fixedTickHz);
    }

    unsigned char header[12]{};
    input.read(reinterpret_cast<char*>(header), sizeof(header));
    if (input.gcount() != static_cast<std::streamsize>(sizeof(header))
        || std::memcmp(header, "RIFF", 4) != 0
        || std::memcmp(header + 8, "WAVE", 4) != 0) {
        return std::max(1, fixedTickHz);
    }

    input.seekg(0, std::ios::end);
    const std::streamoff fileEnd = input.tellg();
    if (fileEnd < static_cast<std::streamoff>(sizeof(header))) {
        return std::max(1, fixedTickHz);
    }
    const std::uint64_t declaredRiffEnd =
        8ULL + static_cast<std::uint64_t>(runtimeReadLe32(header + 4));
    const std::uint64_t scanEnd = std::min(
        static_cast<std::uint64_t>(fileEnd),
        declaredRiffEnd
    );
    if (scanEnd < sizeof(header)) {
        return std::max(1, fixedTickHz);
    }
    input.seekg(static_cast<std::streamoff>(sizeof(header)), std::ios::beg);

    std::uint16_t formatTag = 0;
    std::uint32_t averageBytesPerSecond = 0;
    std::uint16_t blockAlign = 0;
    std::uint16_t samplesPerBlock = 0;
    std::uint32_t factFrames = 0;
    std::uint16_t channels = 0;
    std::uint32_t sampleRate = 0;
    std::uint16_t bitsPerSample = 0;
    std::uint32_t dataBytes = 0;
    while (input) {
        unsigned char chunkHeader[8]{};
        input.read(reinterpret_cast<char*>(chunkHeader), sizeof(chunkHeader));
        if (input.gcount() != static_cast<std::streamsize>(sizeof(chunkHeader))) {
            break;
        }

        const std::uint32_t chunkSize = runtimeReadLe32(chunkHeader + 4);
        const std::streamoff chunkDataOffsetValue = input.tellg();
        if (chunkDataOffsetValue < 0) {
            break;
        }
        const std::uint64_t chunkDataOffset =
            static_cast<std::uint64_t>(chunkDataOffsetValue);
        const std::uint64_t paddedChunkSize =
            static_cast<std::uint64_t>(chunkSize)
            + static_cast<std::uint64_t>(chunkSize & 1U);
        if (chunkDataOffset > scanEnd
            || paddedChunkSize > scanEnd - chunkDataOffset) {
            break;
        }
        const std::uint64_t nextChunkOffset =
            chunkDataOffset + paddedChunkSize;
        if (std::memcmp(chunkHeader, "fmt ", 4) == 0) {
            if (chunkSize >= 16U) {
                unsigned char fmt[16]{};
                input.read(reinterpret_cast<char*>(fmt), sizeof(fmt));
                if (input.gcount()
                    != static_cast<std::streamsize>(sizeof(fmt))) {
                    break;
                }
                formatTag = runtimeReadLe16(fmt);
                averageBytesPerSecond = runtimeReadLe32(fmt + 8);
                blockAlign = runtimeReadLe16(fmt + 12);
                channels = runtimeReadLe16(fmt + 2);
                sampleRate = runtimeReadLe32(fmt + 4);
                bitsPerSample = runtimeReadLe16(fmt + 14);
                if (formatTag == 0x11 && chunkSize >= 20U) {
                    unsigned char extra[4]{};
                    input.read(reinterpret_cast<char*>(extra), sizeof(extra));
                    if (input.gcount() == sizeof(extra) && runtimeReadLe16(extra) >= 2U) {
                        samplesPerBlock = runtimeReadLe16(extra + 2);
                    }
                }
            }
        } else if (std::memcmp(chunkHeader, "fact", 4) == 0 && chunkSize >= 4U) {
            unsigned char fact[4]{};
            input.read(reinterpret_cast<char*>(fact), sizeof(fact));
            if (input.gcount() == sizeof(fact)) factFrames = runtimeReadLe32(fact);
        } else if (std::memcmp(chunkHeader, "data", 4) == 0) {
            dataBytes = chunkSize;
        }
        input.seekg(
            static_cast<std::streamoff>(nextChunkOffset),
            std::ios::beg
        );
    }

    if (!sampleRate || !channels || !dataBytes) return std::max(1, fixedTickHz);
    double seconds = 0.0;
    if (formatTag != 1 && factFrames > 0) {
        // Original MIX EVA WAVs are Microsoft IMA ADPCM. FACT excludes the
        // padded tail of the last block, so encoded bit depth is not a PCM rate.
        seconds = static_cast<double>(factFrames) / sampleRate;
    } else if (formatTag == 0x11 && blockAlign >= 4U * channels && samplesPerBlock > 0) {
        std::uint64_t frames = static_cast<std::uint64_t>(dataBytes / blockAlign) * samplesPerBlock;
        const auto remainder = dataBytes % blockAlign;
        if (remainder >= 4U * channels) frames += 1U + (remainder - 4U * channels) * 2U / channels;
        seconds = static_cast<double>(frames) / sampleRate;
    } else if (averageBytesPerSecond > 0) {
        seconds = static_cast<double>(dataBytes) / averageBytesPerSecond;
    } else if (formatTag == 1 && bitsPerSample > 0) {
        const auto rate = static_cast<std::uint64_t>(sampleRate) * channels * bitsPerSample / 8U;
        if (rate > 0) seconds = static_cast<double>(dataBytes) / rate;
    }
    if (!(seconds > 0.0)) return std::max(1, fixedTickHz);
    const double ticks = std::ceil(seconds * std::max(1, fixedTickHz));
    return static_cast<int>(std::clamp(ticks, 1.0, static_cast<double>((std::numeric_limits<int>::max)())));
}

void emitRuntimeLowPowerWarning(
    RuntimeProductionHostState& state,
    bool includePowerOffCue) {
    const int cooldownTicks =
        std::max(1, state.config.fixedTickHz * 3);
    if (state.tick - state.runtimeLastLowPowerSoundTick < cooldownTicks) {
        return;
    }
    if (includePowerOffCue) {
        emitRuntimeSound(state, runtimeSoundIntentPowerOff);
    }
    emitRuntimeSound(state, runtimeSoundIntentLowPower);
    state.runtimeLastLowPowerSoundTick = state.tick;
}

RuntimeInputPixelRect runtimeMapPixelViewport(const RuntimeInputPixelRect& clientRect) {
    const auto viewport = runtimeInputPixelMapViewport(
        {clientRect.left, clientRect.top, clientRect.right, clientRect.bottom},
        runtimeSidebarWidth);
    return {viewport.left, viewport.top, viewport.right, viewport.bottom};
}

RuntimeProjectedPoint runtimeProjectCellXY(
    double x,
    double y,
    double level,
    const RuntimeMapCamera& camera) {
    return {
        static_cast<int>(std::llround(((x - y) * camera.tileWidth) / 2.0)),
        static_cast<int>(
            std::llround(
                ((x + y) * camera.tileHeight) / 2.0
                    - ((level * camera.tileHeight) / 2.0)
            )
        )
    };
}

double runtimeObjectRenderX(const WorldObjectInstance& object) {
    return object.hasRenderPosition ? object.renderX : static_cast<double>(object.x);
}

double runtimeObjectRenderY(const WorldObjectInstance& object) {
    return object.hasRenderPosition ? object.renderY : static_cast<double>(object.y);
}

double runtimeObjectRenderLevel(const WorldObjectInstance& object) {
    return object.renderMoveActive
            || worldObjectHasStoppedGroundPose(object)
            || (object.airborne && object.hasRenderPosition)
            || (object.factoryExitHostId >= 0 && object.hasRenderPosition)
        ? object.renderLevel
        : static_cast<double>(object.level);
}

RuntimeInputPixelPoint runtimeScreenPixelPoint(
    const RuntimeProjectedPoint& point,
    const RuntimeInputPixelRect& viewport,
    const RuntimeMapCamera& camera) {
    return {
        viewport.left + point.x - camera.worldOffsetX,
        viewport.top + point.y - camera.worldOffsetY
    };
}

double runtimeDrawLevelForObject(const WorldObjectInstance& object) {
    return runtimeObjectRenderLevel(object);
}

int runtimeCellKey(int x, int y) {
    if (x < 0 || y < 0) {
        return -1;
    }
    return (y * 1000) + x;
}

bool parseRuntimePositiveIntToken(
    const std::string& value,
    std::size_t begin,
    std::size_t end,
    int& parsed) {
    if (begin >= end || end > value.size()) {
        return false;
    }

    int result = 0;
    for (std::size_t index = begin; index < end; ++index) {
        const char ch = value[index];
        if (!std::isdigit(static_cast<unsigned char>(ch))) {
            return false;
        }
        result = (result * 10) + (ch - '0');
        if (result > 16) {
            return false;
        }
    }

    if (result <= 0) {
        return false;
    }

    parsed = result;
    return true;
}

RuntimeStructureFootprint parseRuntimeFoundationSize(
    const std::string& foundation) {
    std::string compact;
    compact.reserve(foundation.size());
    for (const char ch : foundation) {
        if (ch != ' ' && ch != '\t' && ch != '\r' && ch != '\n') {
            compact.push_back(ch);
        }
    }

    compact = toLowerAsciiLocal(std::move(compact));
    const std::size_t separator = compact.find('x');
    if (separator == std::string::npos) {
        return {};
    }

    int width = 1;
    int height = 1;
    if (!parseRuntimePositiveIntToken(compact, 0, separator, width)
        || !parseRuntimePositiveIntToken(
            compact,
            separator + 1,
            compact.size(),
            height
        )) {
        return {};
    }

    return {width, height, true};
}

RuntimeCellPoint runtimeCellPointForObject(const WorldObjectInstance& object) {
    return {object.x, object.y};
}

double runtimeCellDistance(
    const RuntimeCellPoint& left,
    const RuntimeCellPoint& right) {
    const double dx = static_cast<double>(left.x - right.x);
    const double dy = static_cast<double>(left.y - right.y);
    return std::sqrt((dx * dx) + (dy * dy));
}

std::array<RuntimeCellPoint, 8> runtimeNeighborsOf(
    const RuntimeCellPoint& point) {
    return {{
        {point.x + 1, point.y},
        {point.x - 1, point.y},
        {point.x, point.y + 1},
        {point.x, point.y - 1},
        {point.x + 1, point.y + 1},
        {point.x - 1, point.y - 1},
        {point.x + 1, point.y - 1},
        {point.x - 1, point.y + 1}
    }};
}

RuntimeCellPoint runtimePlacementTopLeftForAnchor(
    const RuntimeCellPoint& anchorCell,
    const RuntimeStructureFootprint& footprint) {
    const RuntimeCellPoint offset =
        runtimePlacementFoundationCenterOffset(footprint);
    return {
        anchorCell.x - offset.x,
        anchorCell.y - offset.y
    };
}

RuntimeCellPoint runtimePlacementFoundationCenterOffset(
    const RuntimeStructureFootprint& footprint) {
    const int width = std::max(1, footprint.width);
    const int height = std::max(1, footprint.height);
    // RA2-style foundation centers are the tile-space anchor inside the
    // footprint, not the mathematical midpoint. Even-sized foundations anchor
    // on the upper-left center tile, matching placement preview behavior in the
    // Java reference and preventing a one-cell drift for 2x2/4x4 buildings.
    return {
        (width - 1) / 2,
        (height - 1) / 2
    };
}

bool runtimeObjectMayUseStructureDriveRows(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& mover) {
    return mover.alive
        && mover.kind == WorldObjectKind::Unit
        && runtimeObjectMovementMode(state, mover) != PathMovementMode::Air;
}

int runtimeStructureBlockedDriveRowCount(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& structure) {
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, structure);
    const int width = std::max(1, footprint.width);
    const BuildingType* building = structure.kind == WorldObjectKind::Structure
        ? state.rules.findBuildingType(structure.type)
        : nullptr;
    if (building == nullptr || building->numberImpassableRows <= 0) {
        // Westwood documents zero/omitted as the normal fully impassable
        // foundation. Positive values count blocked columns from game west.
        return width;
    }
    return std::clamp(building->numberImpassableRows, 0, width);
}

bool runtimeStructureCellInsideFoundation(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& structure,
    const RuntimeCellPoint& cell) {
    if (runtimeInvisibleMapBuilding(&state.rules, structure)) return false;
    if (structure.kind != WorldObjectKind::Structure) {
        return false;
    }
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, structure);
    const int width = std::max(1, footprint.width);
    const int height = std::max(1, footprint.height);
    return cell.x >= structure.x
        && cell.x < structure.x + width
        && cell.y >= structure.y
        && cell.y < structure.y + height;
}

bool runtimeStructureCellIsVehicleDriveRow(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& structure,
    const RuntimeCellPoint& cell,
    const WorldObjectInstance& mover) {
    if (structure.kind != WorldObjectKind::Structure
        || !runtimeObjectMayUseStructureDriveRows(state, mover)
        || !runtimeStructureCellInsideFoundation(state, structure, cell)) {
        return false;
    }
    const BuildingType* building = state.rules.findBuildingType(structure.type);
    if (building == nullptr || building->numberImpassableRows <= 0) {
        return false;
    }
    const int blockedRows = runtimeStructureBlockedDriveRowCount(
        state,
        structure
    );
    return cell.x - structure.x >= blockedRows;
}

bool runtimeC4CellOutsideFoundation(
    const RuntimeGameSessionState& state,
    const RuntimeCellPoint& cell,
    const WorldObjectInstance& target) {
    return !runtimeStructureCellInsideFoundation(state, target, cell);
}

bool runtimeC4BodyOutsideFoundation(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& source,
    const WorldObjectInstance& target) {
    const auto offset = worldObjectSubCellOffset(source);
    const double x = runtimeObjectRenderX(source) + offset.x;
    const double y = runtimeObjectRenderY(source) + offset.y;
    if (!std::isfinite(x) || !std::isfinite(y)) return false;
    if (runtimeStructureFootprintCellsForObject(state, target).empty()) return true;
    const auto footprint = runtimeStructureFootprintForObject(state, target);
    return x <= target.x - .5 + 1e-9
        || x >= target.x + std::max(1, footprint.width) - .5 - 1e-9
        || y <= target.y - .5 + 1e-9
        || y >= target.y + std::max(1, footprint.height) - .5 - 1e-9;
}

void activateRuntimeWorldObject(
    RuntimeGameSessionState& state,
    WorldObjectInstance& object) {
    // In-place activation preserves vector identity and size. Revoke cached
    // empty cells before any subsequent passenger or special-action query.
    invalidateRuntimeTickOccupancyCache(state);
    object.alive = true;
}

const UnitType* findRuntimeUnitType(
    const RulesDatabase& rules,
    const WorldObjectInstance& object) {
    if (object.kind == WorldObjectKind::Infantry) {
        return rules.findUnitType("InfantryType", object.type);
    }

    if (object.kind == WorldObjectKind::Unit) {
        if (object.authoredAircraft) {
            return rules.findUnitType("AircraftType", object.type);
        }
        if (const UnitType* vehicle =
                rules.findUnitType("UnitType", object.type)) {
            return vehicle;
        }
        return rules.findUnitType("AircraftType", object.type);
    }

    return nullptr;
}

const UnitType* runtimeAmmoRulesForObject(
    const RulesDatabase& rules,
    const WorldObjectInstance& object) {
    if (object.kind == WorldObjectKind::Infantry) {
        return rules.findUnitType("InfantryType", object.type);
    }
    if (object.kind != WorldObjectKind::Unit) {
        return nullptr;
    }

    // Match GameWorld hydration: [Units] is vehicle-first, while an object
    // authored in [Aircraft] retains its AircraftTypes identity.
    if (object.authoredAircraft) {
        return rules.findUnitType("AircraftType", object.type);
    }
    if (const UnitType* vehicle =
            rules.findUnitType("UnitType", object.type)) {
        return vehicle;
    }
    return rules.findUnitType("AircraftType", object.type);
}

void initializeRuntimeObjectAmmo(
    WorldObjectInstance& object,
    const UnitType* unit,
    bool refillToCapacity) {
    if (unit == nullptr || unit->ammo < 0) {
        object.currentAmmo = -1;
        return;
    }
    const int initial = refillToCapacity || unit->initialAmmo < 0
        ? unit->ammo
        : unit->initialAmmo;
    object.currentAmmo = std::clamp(initial, 0, unit->ammo);
}

bool runtimeUnitUsesAutomaticJumpjetLanding(const UnitType& unit) {
    return runtimeUnitUsesJumpjetMovement(unit) && !unit.balloonHover
        && !(unit.isSimpleDeployer && unit.deployToLand);
}

int runtimeUnitFlightLevelOffset(const UnitType& unit) {
    if (unit.jumpJetHeight > 0) {
        constexpr double leptonsPerLevel = 256.0;
        return std::max(
            1,
            static_cast<int>(std::lround(
                static_cast<double>(unit.jumpJetHeight) / leptonsPerLevel
            ))
        );
    }
    return 4;
}

void applyRuntimeInitialObjectFlightState(
    const RulesDatabase& rules,
    WorldObjectInstance& object,
    bool startOnGround) {
    const UnitType* unit = findRuntimeUnitType(rules, object);
    if (unit == nullptr
        || !object.alive
        || object.airborne
        || (!object.authoredAircraft && unit->airportBound)
        || !runtimeUnitUsesAirMovement(*unit)) {
        return;
    }

    object.airborne = true;
    object.flightLevel = object.level
        + (startOnGround && runtimeUnitUsesJumpjetMovement(*unit) ? 0 : runtimeUnitFlightLevelOffset(*unit));
    object.level = object.flightLevel;
    object.onBridge = false;
    object.subCell = -1;
    if (object.hasRenderPosition) {
        object.renderLevel = static_cast<double>(object.level);
        object.renderOnBridge = false;
    }
}

void hydrateRuntimeObjectFlightState(
    GameWorld& world,
    const RulesDatabase& rules) {
    for (WorldObjectInstance& object : world.accessObjects()) {
        applyRuntimeInitialObjectFlightState(rules, object);
    }
}

bool runtimeInitialObjectSubmergedState(
    const RulesDatabase& rules,
    const WorldObjectInstance& object) {
    const UnitType* unit = findRuntimeUnitType(rules, object);
    return unit != nullptr && unit->underwater;
}

bool runtimeLoadedObjectSubmergedState(
    const std::vector<std::string>& tokens,
    const RulesDatabase& rules,
    const WorldObjectInstance& object) {
    // Saves written before the per-instance field existed contain 29 object
    // tokens. Preserve their authored UnitType initial state, while newer
    // saves restore the live surfaced/submerged state exactly.
    return tokens.size() >= 30
        ? parseRuntimeBool(tokens[29])
        : runtimeInitialObjectSubmergedState(rules, object);
}

void hydrateRuntimeObjectSubmergedState(
    GameWorld& world,
    const RulesDatabase& rules) {
    for (WorldObjectInstance& object : world.accessObjects()) {
        object.submerged = runtimeInitialObjectSubmergedState(rules, object);
    }
}

const BuildingType* findRuntimeBuildingType(
    const RulesDatabase& rules,
    const WorldObjectInstance& object) {
    if (object.kind != WorldObjectKind::Structure) {
        return nullptr;
    }

    return rules.findBuildingType(object.type);
}

const BuildingType* findRuntimeBuildingTypeById(
    const RulesDatabase& rules,
    const std::string& id) {
    return rules.findBuildingType(id);
}

int runtimeCloakDelayTicks(const RuntimeGameSessionState& state) {
    const double minutes = std::max(
        0.0,
        state.rules.getSpecialMechanismRules().cloakDelayMinutes
    );
    return std::max(
        0,
        static_cast<int>(std::floor(
            60.0
            * minutes
            * static_cast<double>(std::max(1, state.config.fixedTickHz))
        ))
    );
}

int runtimeObjectCloakTransitionTicks(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    int cloakingSpeed = 7;
    if (const UnitType* unit = findRuntimeUnitType(state.rules, object)) {
        cloakingSpeed = unit->cloakingSpeed;
    } else if (const BuildingType* building =
            findRuntimeBuildingType(state.rules, object)) {
        cloakingSpeed = building->cloakingSpeed;
    }

    const long long stages = std::max(
        1,
        state.rules.getSpecialMechanismRules().cloakingStages
    );
    const long long frames = stages * std::clamp(cloakingSpeed, 1, 10);
    const long long fixedTickHz = std::max(1, state.config.fixedTickHz);
    const long long animationTicks =
        (frames * fixedTickHz + 14LL) / 15LL;
    return static_cast<int>(std::min<long long>(
        std::numeric_limits<int>::max(),
        static_cast<long long>(runtimeCloakDelayTicks(state))
            + animationTicks
    ));
}

bool runtimeObjectCanCloak(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    if (runtimeAttachFlag(object, state.rules, &AttachEffectRule::forceDecloak)) return false;
    if (object.alive && runtimeAttachFlag(object, state.rules, &AttachEffectRule::cloakable)) return true;
    if (!state.rulesLoaded || !object.alive) {
        return false;
    }
    if (const UnitType* unit = findRuntimeUnitType(state.rules, object)) {
        return object.crateCloakable
            || unit->cloakable
            || runtimeVeterancyHasAbility(
                state,
                object,
                VeteranAbility::Cloak
            );
    }
    if (const BuildingType* building =
            findRuntimeBuildingType(state.rules, object)) {
        return object.crateCloakable
            || building->cloakable
            || runtimeVeterancyHasAbility(
                state,
                object,
                VeteranAbility::Cloak
            );
    }
    return false;
}

int runtimeObjectSensorsSight(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    if (!state.rulesLoaded || !object.alive) {
        return 0;
    }
    bool enabled = runtimeVeterancyHasAbility(
        state,
        object,
        VeteranAbility::Sensors
    );
    int sight = 0;
    if (const UnitType* unit = findRuntimeUnitType(state.rules, object)) {
        enabled = enabled || unit->sensors || unit->sensorArray;
        sight = unit->sensorsSight;
    } else if (const BuildingType* building =
            findRuntimeBuildingType(state.rules, object)) {
        enabled = enabled || building->sensors || building->sensorArray;
        sight = building->sensorsSight;
    }
    return enabled ? std::max(0, sight) : 0;
}

void initializeRuntimeObjectCloakState(
    const RuntimeGameSessionState& state,
    WorldObjectInstance& object) {
    object.cloaked = false;
    object.cloakCooldownTicks = runtimeObjectCanCloak(state, object)
        ? runtimeObjectCloakTransitionTicks(state, object)
        : 0;
    const UnitType* unit = findRuntimeUnitType(state.rules, object);
    object.submergeCooldownTicks =
        unit != nullptr && unit->underwater && !object.submerged
            ? runtimeObjectCloakTransitionTicks(state, object)
            : 0;
}

const UnitType* findRuntimeUnitTypeById(
    const RulesDatabase& rules,
    const std::string& id) {
    if (const UnitType* infantry = rules.findUnitType("InfantryType", id)) {
        return infantry;
    }
    if (const UnitType* vehicle = rules.findUnitType("UnitType", id)) {
        return vehicle;
    }
    return rules.findUnitType("AircraftType", id);
}

RuntimeBuildKind runtimeBuildKindForUnitTypeId(
    const RulesDatabase& rules,
    const std::string& id) {
    for (const UnitType& unit : rules.getInfantryTypes()) {
        if (unit.id == id) {
            return RuntimeBuildKind::Infantry;
        }
    }
    return RuntimeBuildKind::Unit;
}

int runtimeLegacyBuildTimeTicks(int cost, bool wall) {
    if (wall) {
        return 1;
    }
    return std::max(12, (std::max(0, cost) + 49) / 50);
}

double runtimeAuthoredBuildTimeMultiplier(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item) {
    if (item.kind == RuntimeBuildKind::Building
        || item.kind == RuntimeBuildKind::Defense) {
        const BuildingType* building = findRuntimeBuildingTypeById(
            state.rules,
            item.typeId
        );
        return building == nullptr ? 1.0 : building->buildTimeMultiplier;
    }
    const UnitType* unit = findRuntimeUnitTypeById(state.rules, item.typeId);
    return unit == nullptr ? 1.0 : unit->buildTimeMultiplier;
}

double runtimeBuildTimeMultiplier(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item) {
    return runtimeAuthoredBuildTimeMultiplier(state, item);
}

int runtimeBaseBuildTimeTicks(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item) {
    const RuntimeProductionTimingResult timing = runtimeProductionTimingForItem(
        state,
        item,
        1,
        0.0,
        0.0
    );
    return timing.valid ? timing.base.fixedTicks : 1;
}

RuntimeScriptType parseRuntimeScriptType(
    const IniFile& ini,
    const std::string& id) {
    RuntimeScriptType script;
    script.id = id;
    script.name = ini.getValue(id, "Name", id);

    std::vector<std::pair<int, RuntimeScriptStep>> indexedSteps;
    if (const IniFile::Section* section = ini.getSection(id)) {
        for (const auto& [key, value] : *section) {
            int stepIndex = 0;
            if (!parseRuntimeInt(key, stepIndex)) {
                continue;
            }

            const std::vector<std::string> tokens = splitRuntimeTokenList(value);
            if (tokens.empty()) {
                continue;
            }

            RuntimeScriptStep step;
            step.action = parseRuntimeIntOrDefault(tokens[0], -1);
            if (tokens.size() > 1) {
                step.argument = parseRuntimeIntOrDefault(tokens[1], 0);
            }
            indexedSteps.emplace_back(stepIndex, step);
        }
    }

    std::stable_sort(
        indexedSteps.begin(),
        indexedSteps.end(),
        [](const auto& left, const auto& right) {
            return left.first < right.first;
        }
    );
    script.steps.reserve(indexedSteps.size());
    for (const auto& [index, step] : indexedSteps) {
        (void)index;
        script.steps.push_back(step);
    }

    return script;
}

RuntimeTaskForce parseRuntimeTaskForce(
    const IniFile& ini,
    const std::string& id) {
    RuntimeTaskForce taskForce;
    taskForce.id = id;
    taskForce.name = ini.getValue(id, "Name", id);
    taskForce.group = parseRuntimeIntOrDefault(ini.getValue(id, "Group", "-1"), -1);

    std::vector<std::pair<int, RuntimeTaskForceMember>> indexedMembers;
    if (const IniFile::Section* section = ini.getSection(id)) {
        for (const auto& [key, value] : *section) {
            int memberIndex = 0;
            if (!parseRuntimeInt(key, memberIndex)) {
                continue;
            }

            const std::vector<std::string> tokens = splitRuntimeTokenList(value);
            if (tokens.size() < 2) {
                continue;
            }

            RuntimeTaskForceMember member;
            member.count = parseRuntimeIntOrDefault(tokens[0], 0);
            member.unitId = tokens[1];
            if (member.count > 0 && !member.unitId.empty()) {
                indexedMembers.emplace_back(memberIndex, member);
            }
        }
    }


    std::stable_sort(
        indexedMembers.begin(),
        indexedMembers.end(),
        [](const auto& left, const auto& right) {
            return left.first < right.first;
        }
    );
    taskForce.members.reserve(indexedMembers.size());
    for (const auto& [index, member] : indexedMembers) {
        (void)index;
        taskForce.members.push_back(member);
    }

    return taskForce;
}

RuntimeTeamType parseRuntimeTeamType(
    const IniFile& ini,
    const std::string& id) {
    RuntimeTeamType team;
    team.id = id;
    team.name = ini.getValue(id, "Name", id);
    team.house = ini.getValue(id, "House", "");
    team.waypointId =
        runtimeWaypointKeyFromName(ini.getValue(id, "Waypoint", ""));
    team.scriptId = ini.getValue(id, "Script", "");
    team.taskForceId = ini.getValue(id, "TaskForce", "");
    team.priority = parseRuntimeIntOrDefault(
        ini.getValue(id, "Priority", "7"),
        7
    );
    team.max = parseRuntimeIntOrDefault(ini.getValue(id, "Max", "-1"), -1);
    team.group = parseRuntimeIntOrDefault(ini.getValue(id, "Group", "-1"), -1);
    team.autocreate = parseRuntimeBool(ini.getValue(id, "Autocreate", "no"));
    team.prebuild = parseRuntimeBool(ini.getValue(id, "Prebuild", "no"));
    team.reinforce = parseRuntimeBool(ini.getValue(id, "Reinforce", "no"));
    team.full = parseRuntimeBool(ini.getValue(id, "Full", "no"));
    team.aggressive = parseRuntimeBool(ini.getValue(id, "Aggressive", "no"));
    team.isBaseDefense = parseRuntimeBool(ini.getValue(id, "IsBaseDefense", "no"));
    team.recruitable = parseRuntimeBool(ini.getValue(id, "AreTeamMembersRecruitable", "yes"));
    team.recruiter = parseRuntimeBool(ini.getValue(id, "Recruiter", "no"));
    team.looseRecruit = parseRuntimeBool(ini.getValue(id, "LooseRecruit", "no"));
    team.avoidThreats = parseRuntimeBool(ini.getValue(id, "AvoidThreats", "no"));
    team.suicide = parseRuntimeBool(ini.getValue(id, "Suicide", "no"));
    team.guardSlower = parseRuntimeBool(ini.getValue(id, "GuardSlower", "no"));
    team.onlyTargetHouseEnemy = parseRuntimeBool(ini.getValue(id, "OnlyTargetHouseEnemy", "no"));
    team.transportsReturnOnUnload = parseRuntimeBool(ini.getValue(id, "TransportsReturnOnUnload", "no"));
    team.veteranLevel = std::clamp(parseRuntimeIntOrDefault(ini.getValue(id, "VeteranLevel", "1"), 1), 1, 3);
    team.mindControlDecision = parseRuntimeIntOrDefault(ini.getValue(id, "MindControlDecision", "0"), 0);
    return team;
}

int runtimeHexNibble(char value) {
    if (value >= '0' && value <= '9') {
        return value - '0';
    }
    if (value >= 'a' && value <= 'f') {
        return value - 'a' + 10;
    }
    if (value >= 'A' && value <= 'F') {
        return value - 'A' + 10;
    }
    return -1;
}

void spendRuntimeComputerStoredOre(RuntimeGameSessionState& state,
    const std::string& owner, int amount) {
    const auto found = state.computerMiningByOwner.find(
        runtimeRepairDepotCanonicalOwnerId(state, owner));
    if (found == state.computerMiningByOwner.end()) return;
    auto& mining = found->second;
    const int previous = mining.storedResourceValue;
    const int remaining = previous - std::min(previous, std::max(0, amount));
    if (previous <= 0) return;
    mining.storedResourceUnits = runtimeScaleResourceValue(
        mining.storedResourceUnits, remaining, previous);
    mining.storedResourceGemUnits = std::min(mining.storedResourceUnits,
        runtimeScaleResourceValue(mining.storedResourceGemUnits, remaining, previous));
    mining.storedResourceValue = remaining;
}

bool runtimeHasOwnedBuilding(
    const RuntimeGameSessionState& state,
    const std::string& id) {
    if (RuntimeSidebarOwnedQueryDiagnostics::Phase::observes(&state)) {
        RuntimeSidebarOwnedQueryDiagnostics::Query queryTrace(&state, state.tick,
            RuntimeSidebarOwnedQueryDiagnostics::Kind::PrerequisiteBuilding);
        const std::string wanted = toUpperAsciiLocal(id);
        for (const WorldObjectInstance& object : state.world.getObjects()) {
            queryTrace.visitRow();
            if (!object.alive
                || object.owner != state.economy.owner
                || object.kind != WorldObjectKind::Structure) {
                continue;
            }
            if (toUpperAsciiLocal(object.type) == wanted) {
                return true;
            }
        }
        return false;
    }
    const std::string wanted = toUpperAsciiLocal(id);
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive
            || object.owner != state.economy.owner
            || object.kind != WorldObjectKind::Structure) {
            continue;
        }
        if (toUpperAsciiLocal(object.type) == wanted) {
            return true;
        }
    }
    return false;
}

bool runtimeOwnerListAllowsHouse(
    const std::string& ownerList,
    const std::string& house) {
    if (ownerList.empty() || house.empty()) {
        return true;
    }

    const std::string wanted = toUpperAsciiLocal(house);
    const bool allied =
        wanted == "AMERICANS"
        || wanted == "BRITISH"
        || wanted == "FRENCH"
        || wanted == "GERMANS"
        || wanted == "KOREANS"
        || wanted == "ALLIANCE";
    const bool soviet =
        wanted == "RUSSIANS"
        || wanted == "CONFEDERATION"
        || wanted == "AFRICANS"
        || wanted == "ARABS"
        || wanted == "SOVIET";
    const bool yuri =
        wanted == "YURI"
        || wanted == "YURICOUNTRY";

    for (const std::string& token : splitRuntimeTokenList(ownerList)) {
        const std::string owner = toUpperAsciiLocal(token);
        if (owner == wanted
            || owner == "ALL"
            || (allied
                && (owner == "ALLIES"
                    || owner == "ALLIED"
                    || owner == "ALLIANCE"))
            || (soviet
                && (owner == "SOVIET"
                    || owner == "SOVIETS"))
            || (yuri
                && (owner == "YURI"
                    || owner == "YURICOUNTRY"))) {
            return true;
        }
    }

    return false;
}

std::string runtimeModeEffectiveOwnerList(
    const RuntimeGameSessionState& state,
    const std::string& typeId,
    const std::string& baseOwnerList) {
    if (!state.skirmishModeRulesLoaded) {
        return baseOwnerList;
    }
    const IniFile::Section* section = runtimeIniSectionNoCase(
        state.skirmishModeRules,
        typeId
    );
    const std::optional<std::string> owner =
        runtimeIniSectionOptionalValueNoCase(section, "Owner");
    return owner.has_value() ? *owner : baseOwnerList;
}

bool runtimeOwnerListsOverlap(
    const RuntimeGameSessionState& state,
    const std::string& leftOwnerList,
    const std::string& rightOwnerList) {
    if (trimAsciiLocal(leftOwnerList).empty()
        || trimAsciiLocal(rightOwnerList).empty()) {
        return true;
    }

    std::vector<std::string> candidateHouses = state.rules.getCountries();
    static constexpr std::array<const char*, 15> stockHouses{{
        "Americans", "Alliance", "French", "Germans", "British",
        "Koreans", "Russians", "Confederation", "Africans", "Arabs",
        "YuriCountry", "Allies", "Soviet", "Yuri", "All"
    }};
    for (const char* house : stockHouses) {
        candidateHouses.emplace_back(house);
    }
    for (const std::string& token : splitRuntimeTokenList(leftOwnerList)) {
        candidateHouses.push_back(token);
    }
    for (const std::string& token : splitRuntimeTokenList(rightOwnerList)) {
        candidateHouses.push_back(token);
    }

    return std::any_of(
        candidateHouses.begin(),
        candidateHouses.end(),
        [&](const std::string& house) {
            return runtimeOwnerListAllowsHouse(leftOwnerList, house)
                && runtimeOwnerListAllowsHouse(rightOwnerList, house);
        }
    );
}

int runtimeOwnerListPlanningSide(const std::string& ownerList) {
    const bool allied = runtimeOwnerListAllowsHouse(ownerList, "Americans");
    const bool soviet = runtimeOwnerListAllowsHouse(ownerList, "Russians");
    const bool yuri = runtimeOwnerListAllowsHouse(ownerList, "YuriCountry");
    const int matchingSides = static_cast<int>(allied)
        + static_cast<int>(soviet)
        + static_cast<int>(yuri);
    if (matchingSides != 1) {
        return -1;
    }
    return allied ? 0 : soviet ? 1 : 2;
}

bool runtimeOwnerHasConstructionYard(
    const RuntimeGameSessionState& state,
    const std::string& owner) {
    const std::string wantedOwner = runtimeRepairDepotCanonicalOwnerId(state, owner);
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive || object.kind != WorldObjectKind::Structure
            || runtimeRepairDepotCanonicalOwnerId(state, object.owner) != wantedOwner) {
            continue;
        }
        const BuildingType* building = findRuntimeBuildingTypeById(state.rules, object.type);
        if (building != nullptr && building->constructionYard) {
            return true;
        }
    }
    return false;
}

bool runtimePrerequisiteTokenMet(
    const RuntimeGameSessionState& state,
    const std::string& token) {
    const std::string normalized = toUpperAsciiLocal(trimAsciiLocal(token));
    if (normalized.empty()
        || normalized == "NONE"
        || normalized == "<NONE>") {
        return true;
    }

    if (normalized == "PROC"
        && runtimeOwnerHasAlternateRefineryPrerequisite(state, state.economy.owner)) {
        return true;
    }

    for (const PrerequisiteAlias& alias :
            state.rules.getPrerequisiteAliases()) {
        if (toUpperAsciiLocal(alias.name) != normalized) {
            continue;
        }
        for (const std::string& buildingId :
                splitRuntimeTokenList(alias.value)) {
            if (runtimeHasOwnedBuilding(state, buildingId)) {
                return true;
            }
        }
        return false;
    }

    if (normalized == "CONSTRUCTION YARD") {
        return runtimeOwnerHasConstructionYard(state, state.economy.owner);
    }
    // The American airforce HQ supplies the Allied airfield technology used
    // by explicit GAAIRC prerequisites in the Unholy Alliance override.
    if (normalized == "GAAIRC" && runtimeIsUnholyAllianceMode(state)
        && runtimeHasOwnedBuilding(state, "AMRADR")) {
        return true;
    }
    if (normalized == "POWER") {
        return state.economy.powerProduced > 0;
    }
    if (normalized == "PROC") {
        return runtimeHasOwnedRefinery(state);
    }
    if (normalized == "BARRACKS") {
        return runtimeHasOwnedFactory(state, "InfantryType");
    }
    if (normalized == "FACTORY") {
        return runtimeHasOwnedFactory(state, "UnitType");
    }
    if (normalized == "RADAR") {
        return runtimeHasOwnedRadar(state);
    }
    if (normalized == "TECH") {
        return runtimeHasOwnedBuilding(state, "GATECH")
            || runtimeHasOwnedBuilding(state, "NATECH")
            || runtimeHasOwnedBuilding(state, "YATECH");
    }

    return runtimeHasOwnedBuilding(state, normalized);
}

bool runtimePrerequisitesMet(
    const RuntimeGameSessionState& state,
    const std::string& prerequisites,
    std::string* missingToken) {
    for (const std::string& token : splitRuntimeTokenList(prerequisites)) {
        if (!runtimePrerequisiteTokenMet(state, token)) {
            if (missingToken != nullptr) {
                *missingToken = token;
            }
            return false;
        }
    }
    return true;
}

bool runtimePrerequisiteOverrideMet(
    const RuntimeGameSessionState& state,
    const std::string& prerequisiteOverride) {
    for (const std::string& token :
            splitRuntimeTokenList(prerequisiteOverride)) {
        if (runtimePrerequisiteTokenMet(state, token)) {
            return true;
        }
    }
    return false;
}

int runtimeLiveOwnedTypeCount(
    const RuntimeGameSessionState& state,
    const std::string& owner,
    const std::string& typeId) {
    if (RuntimeSidebarOwnedQueryDiagnostics::Phase::observes(&state)) {
        RuntimeSidebarOwnedQueryDiagnostics::Query queryTrace(&state, state.tick,
            RuntimeSidebarOwnedQueryDiagnostics::Kind::LiveOwned);
        const std::string ownerKey = runtimeBuildLimitKey(owner);
        const std::string typeKey = runtimeBuildLimitKey(typeId);
        return static_cast<int>(std::count_if(
            state.world.getObjects().begin(),
            state.world.getObjects().end(),
            [&](const WorldObjectInstance& object) {
                queryTrace.visitRow();
                return object.alive
                    && runtimeBuildLimitKey(object.owner) == ownerKey
                    && runtimeBuildLimitKey(object.type) == typeKey;
            }
        ));
    }
    const std::string ownerKey = runtimeBuildLimitKey(owner);
    const std::string typeKey = runtimeBuildLimitKey(typeId);
    return static_cast<int>(std::count_if(
        state.world.getObjects().begin(),
        state.world.getObjects().end(),
        [&](const WorldObjectInstance& object) {
            return object.alive
                && runtimeBuildLimitKey(object.owner) == ownerKey
                && runtimeBuildLimitKey(object.type) == typeKey;
        }
    ));
}

int runtimePendingBuildTypeCount(
    const RuntimeGameSessionState& state,
    const std::string& owner,
    const std::string& typeId) {
    if (runtimeBuildLimitKey(owner)
        != runtimeBuildLimitKey(state.economy.owner)) {
        return 0;
    }

    const std::string typeKey = runtimeBuildLimitKey(typeId);
    int count = 0;
    for (const RuntimeProductionLane lane : runtimeProductionLanes) {
        const RuntimeProductionLaneState& laneState =
            state.economy.localProductionLanes.lanes[
                runtimeProductionLaneIndex(lane)
            ];
        count += static_cast<int>(std::count_if(
            laneState.queued.begin(),
            laneState.queued.end(),
            [&](const RuntimeProductionLaneOrder& order) {
                return runtimeBuildLimitKey(order.itemKey) == typeKey;
            }
        ));
        if (laneState.active.has_value()
            && runtimeBuildLimitKey(laneState.active->itemKey) == typeKey) {
            ++count;
        }
        if (laneState.ready.has_value()
            && runtimeBuildLimitKey(laneState.ready->itemKey) == typeKey) {
            ++count;
        }
    }
    return count;
}

int runtimeLimitedBuildHistoryCount(
    const RuntimeGameSessionState& state,
    const std::string& owner,
    const std::string& typeId) {
    const auto ownerIt = state.economy.limitedBuildHistoryByOwner.find(
        runtimeBuildLimitKey(owner)
    );
    if (ownerIt == state.economy.limitedBuildHistoryByOwner.end()) {
        return 0;
    }
    const auto typeIt = ownerIt->second.find(runtimeBuildLimitKey(typeId));
    return typeIt == ownerIt->second.end() ? 0 : typeIt->second;
}

void recordRuntimeCompletedBuild(
    RuntimeGameSessionState& state,
    const std::string& owner,
    const RuntimeBuildCatalogItem& item,
    int count) {
    recordRuntimeMatchBuild(state, owner, count);
    if (!item.buildLimit.has_value()
        || *item.buildLimit >= 0
        || count <= 0) {
        return;
    }
    int& history = state.economy.limitedBuildHistoryByOwner[
        runtimeBuildLimitKey(owner)
    ][runtimeBuildLimitKey(item.typeId)];
    history = std::min(
        std::numeric_limits<int>::max(),
        history > std::numeric_limits<int>::max() - count
            ? std::numeric_limits<int>::max()
            : history + count
    );
}

void initializeRuntimeLimitedBuildHistory(RuntimeGameSessionState& state) {
    state.economy.limitedBuildHistoryByOwner.clear();
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive
            || trimAsciiLocal(object.owner).empty()
            || trimAsciiLocal(object.type).empty()) {
            continue;
        }
        ++state.economy.limitedBuildHistoryByOwner[
            runtimeBuildLimitKey(object.owner)
        ][runtimeBuildLimitKey(object.type)];
    }
}

RuntimeSpecialBuildingContext makeRuntimeSpecialBuildingContext(
    const RuntimeGameSessionState& state) {
    RuntimeSpecialBuildingContext context;
    context.rules = state.rulesLoaded ? &state.rules : nullptr;
    context.objects = &state.world.getObjects();
    context.canonicalOwnerId = [&state](const std::string& owner) {
        return runtimeRepairDepotCanonicalOwnerId(state, owner);
    };
    context.ownerIsNeutral = [](const std::string& owner) {
        return runtimeOwnerIsNeutralForAutoTarget(owner);
    };
    context.fixedTickHz = std::max(1, state.config.fixedTickHz);
    return context;
}

RuntimeSpecialBuildingUnlockKind runtimeSpecialUnlockKind(
    const RuntimeBuildCatalogItem& item) {
    if (item.kind == RuntimeBuildKind::Infantry) {
        return RuntimeSpecialBuildingUnlockKind::Infantry;
    }
    if (item.kind == RuntimeBuildKind::Unit) {
        return RuntimeSpecialBuildingUnlockKind::Unit;
    }
    return RuntimeSpecialBuildingUnlockKind::Building;
}

int runtimeUnlockedBuildOptionCount(const RuntimeGameSessionState& state) {
    int count = 0;
    for (const RuntimeBuildCatalogItem& item : state.economy.catalog) {
        if (runtimeBuildItemUnlockedForSidebar(state, item)) {
            ++count;
        }
    }
    return count;
}

std::vector<double> parseRuntimeVerses(const std::string& verses) {
    std::vector<double> values;
    std::stringstream input(verses);
    std::string token;

    while (std::getline(input, token, ',')) {
        token = trimAsciiLocal(token);
        if (!token.empty() && token.back() == '%') {
            token.pop_back();
        }

        try {
            values.push_back(std::stod(token) / 100.0);
        } catch (...) {
            values.push_back(1.0);
        }
    }

    return values;
}

int runtimeArmorIndex(const std::string& armor) {
    static const std::vector<std::string> armorOrder = {
        "none",
        "flak",
        "plate",
        "light",
        "medium",
        "heavy",
        "wood",
        "steel",
        "concrete",
        "special_1",
        "special_2"
    };

    const std::string lower = toLowerAsciiLocal(armor);
    const auto it = std::find(armorOrder.begin(), armorOrder.end(), lower);
    return it == armorOrder.end()
        ? -1
        : static_cast<int>(std::distance(armorOrder.begin(), it));
}

std::string runtimeTargetArmor(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    if (const UnitType* unit = findRuntimeUnitType(state.rules, object)) {
        return unit->armor;
    }

    if (const BuildingType* building = findRuntimeBuildingType(state.rules, object)) {
        return building->armor;
    }

    return "";
}

std::string runtimeTargetEffectiveArmor(const RuntimeGameSessionState& state,
    const WorldObjectInstance& object, const WarheadType* warhead) {
    if (const auto* shield = runtimeActiveShield(object, state.rules, warhead); shield && !shield->inheritArmor)
        return shield->armor;
    return runtimeTargetArmor(state, object);
}

std::string runtimeMissionName(RuntimeMissionIntent intent) {
    switch (intent) {
    case RuntimeMissionIntent::Idle:
        return "Guard";
    case RuntimeMissionIntent::Moving:
        return "Move";
    case RuntimeMissionIntent::Attacking:
        return "Attack";
    case RuntimeMissionIntent::Deploying:
        return "Deploying";
    case RuntimeMissionIntent::Deployed:
        return "DeployedIdle";
    case RuntimeMissionIntent::Undeploying:
        return "Undeploying";
    case RuntimeMissionIntent::Entering:
        return "Enter";
    case RuntimeMissionIntent::Occupying:
        return "Occupying";
    case RuntimeMissionIntent::Repairing:
        return "Repairing";
    case RuntimeMissionIntent::Loading:
        return "Load";
    case RuntimeMissionIntent::Unloading:
        return "Unload";
    }

    return "Guard";
}

void recordRuntimeReplayEvent(
    RuntimeProductionHostState& state,
    RuntimeReplayEventSnapshot event) {
    event.sequence = state.nextReplayEventSequence++;
    event.tick = state.tick;
    state.recentReplayEvents.push_back(std::move(event));
    constexpr std::size_t maxRecentReplayEvents = 128;
    while (state.recentReplayEvents.size() > maxRecentReplayEvents) {
        state.recentReplayEvents.pop_front();
    }
    state.snapshotCache.replayEventSnapshotsDirty = true;
}

void ensureRuntimeSpecialMechanismsInitialized(RuntimeGameSessionState& state) {
    if (state.specialMechanismsInitialized || !state.rulesLoaded) {
        return;
    }
    state.specialMechanisms.reset(
        state.rules.getSpecialMechanismRules()
    );
    state.specialMechanismsInitialized = true;
}

int runtimeAiSuperDefenseProbabilityIndex(const std::string& difficulty) {
    const std::string key = toUpperAsciiLocal(trimAsciiLocal(difficulty));
    if (key == "HARD" || key == "BRUTAL") {
        return 0;
    }
    if (key == "EASY") {
        return 2;
    }
    return 1;
}

RuntimeLightingMode runtimeEffectiveLightingModeForTokens(
    const std::map<std::uint64_t, RuntimeActiveLightingToken>& activeTokens) {
    if (activeTokens.empty()) {
        return RuntimeLightingMode::Base;
    }
    const auto selected = std::max_element(
        activeTokens.begin(),
        activeTokens.end(),
        [](const auto& left, const auto& right) {
            return std::tie(left.second.startedTick, left.second.token)
                < std::tie(right.second.startedTick, right.second.token);
        }
    );
    return selected->second.mode;
}

int runtimeBombSightForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    if (object.kind == WorldObjectKind::Structure) {
        const BuildingType* building = findRuntimeBuildingTypeById(
            state.rules,
            object.type
        );
        return building == nullptr ? 0 : std::max(0, building->bombSight);
    }
    const UnitType* unit = findRuntimeUnitType(state.rules, object);
    return unit == nullptr ? 0 : std::max(0, unit->bombSight);
}

bool runtimeTimedBombDetectedForOwner(
    const RuntimeGameSessionState& state,
    int targetObjectId,
    const std::string& observerOwner) {
    if (!state.specialMechanismsInitialized) {
        return false;
    }
    const auto bomb = state.specialMechanisms.timedBombs().find(
        targetObjectId
    );
    if (bomb == state.specialMechanisms.timedBombs().end()) {
        return false;
    }
    // C4 already has an explicit public countdown. BombSight is the stock
    // automatic detector for concealed Ivan bombs.
    if (bomb->second.kind != TimedBombKind::Ivan
        || trimAsciiLocal(observerOwner).empty()) {
        return true;
    }
    if (runtimeOwnersAreAllied(
            state,
            observerOwner,
            bomb->second.owner
        )) {
        return true;
    }
    const WorldObjectInstance* target = findObjectById(
        state,
        targetObjectId
    );
    if (target == nullptr || !target->alive || target->health <= 0) {
        return false;
    }
    for (const WorldObjectInstance& detector : state.world.getObjects()) {
        const int bombSight = runtimeBombSightForObject(state, detector);
        if (!detector.alive || detector.health <= 0 || bombSight <= 0
            || !runtimeOwnersAreAllied(
                state,
                observerOwner,
                detector.owner
            )
            || !runtimeObjectHasBombDisarmWeapon(state, detector)) {
            continue;
        }
        if (runtimeCellDistanceToObjectFootprint(
                state,
                runtimeCellPointForObject(detector),
                *target
            ) <= static_cast<double>(bombSight) + 0.001) {
            return true;
        }
    }
    return false;
}

int runtimeCamouflageFakeBlinkTicks(const RuntimeGameSessionState& state, int originalFrames) {
    return static_cast<int>(std::clamp<std::int64_t>(
        (static_cast<std::int64_t>(std::max(0, originalFrames)) * std::max(1, state.config.fixedTickHz) + 14) / 15,
        0, std::numeric_limits<int>::max()));
}

void refreshRuntimeSpecialMechanismRenderSnapshots(RuntimeProductionHostState& state) {
    ensureRuntimeSpecialMechanismsInitialized(state);
    if (!state.specialMechanismsInitialized) {
        state.specialMechanismRenderSnapshots.clear();
    } else {
        state.specialMechanismRenderSnapshots =
            state.specialMechanisms.renderSnapshots(state.tick, state.config.fixedTickHz);
        for (auto& snapshot : state.specialMechanismRenderSnapshots) {
            if (snapshot.kind != "camouflage") continue;
            const auto found = state.specialMechanisms.camouflageStates().find(snapshot.objectId);
            if (found != state.specialMechanisms.camouflageStates().end())
                snapshot.progress = found->second.lastActivityTick;
        }
        resolveRuntimeTemporalBeamEndpoints(state);
        resolveRuntimeSpawnedMissileRenderSnapshots(state);
        state.specialMechanismRenderSnapshots.erase(
            std::remove_if(
                state.specialMechanismRenderSnapshots.begin(),
                state.specialMechanismRenderSnapshots.end(),
                [&state](const SpecialMechanismRenderSnapshot& snapshot) {
                    return snapshot.kind == "timedBomb"
                        && !runtimeTimedBombDetectedForOwner(
                            state,
                            snapshot.targetObjectId,
                            state.economy.owner
                        );
                }
            ),
            state.specialMechanismRenderSnapshots.end()
        );
    }
    for (const RuntimeSpyDisguiseState& disguise :
            state.spies.disguiseStates()) {
        const WorldObjectInstance* source = findObjectById(
            state,
            disguise.objectId
        );
        if (source == nullptr || !source->alive) {
            continue;
        }
        const RuntimeSpyObserverProjection projection =
            runtimeSpyObserverProjectionForOwner(
                state,
                state.economy.owner,
                *source,
                true
            );
        if (!projection.active || projection.type.empty()) {
            continue;
        }
        SpecialMechanismRenderSnapshot snapshot;
        snapshot.kind = "spyDisguise";
        snapshot.instanceId = disguise.objectId;
        snapshot.objectId = disguise.objectId;
        snapshot.owner = projection.owner;
        snapshot.resourceId = projection.type;
        snapshot.phase = projection.identity
                == RuntimeSpyDisguiseIdentity::Vehicle
            ? "Vehicle"
            : (projection.identity == RuntimeSpyDisguiseIdentity::Terrain
                ? "Terrain"
                : "Infantry");
        state.specialMechanismRenderSnapshots.push_back(
            std::move(snapshot)
        );
    }
    for (const auto& animation : state.repairDepots.animations()) {
        SpecialMechanismRenderSnapshot snapshot;
        snapshot.kind = "repairDepot";
        snapshot.instanceId = snapshot.objectId = animation.hostId;
        snapshot.progress = animation.ageTicks;
        snapshot.resourceId = animation.phase == RuntimeRepairDepotAnimationPhase::Extending
            ? "SpecialAnim" : animation.phase == RuntimeRepairDepotAnimationPhase::Repairing
            ? "SpecialAnimTwo" : "SpecialAnimThree";
        state.specialMechanismRenderSnapshots.push_back(std::move(snapshot));
    }
    ensureRuntimeSuperWeaponsInitialized(state);
    appendRuntimeSuperWeaponBuildingSnapshots(state);
    state.superWeaponRenderSnapshots = state.superWeapons.renderSnapshots();
    for (const SuperWeaponRenderSnapshot& superSnapshot :
            state.superWeaponRenderSnapshots) {
        SpecialMechanismRenderSnapshot snapshot;
        snapshot.kind = superSnapshot.kind;
        if (superSnapshot.kind == "superWeaponProjectile") {
            const auto pose = runtimeSuperWeaponNuclearFlightPose(state, superSnapshot);
            if (!pose.visible) continue;
            snapshot.sourceX = pose.x;
            snapshot.sourceY = pose.y;
            snapshot.sourceLevel = pose.level;
        }
        snapshot.instanceId = superSnapshot.instanceId;
        snapshot.objectId = superSnapshot.sourceObjectId;
        snapshot.targetObjectId = superSnapshot.targetObjectId;
        snapshot.superWeaponId = superSnapshot.superWeaponId;
        snapshot.sourceCell = {
            superSnapshot.cell.x,
            superSnapshot.cell.y
        };
        snapshot.targetCell = {
            superSnapshot.cell2.x,
            superSnapshot.cell2.y
        };
        snapshot.cell = {
            superSnapshot.cell.x,
            superSnapshot.cell.y
        };
        snapshot.cell2 = {
            superSnapshot.cell2.x,
            superSnapshot.cell2.y
        };
        snapshot.radius = superSnapshot.radius;
        snapshot.intensity = superSnapshot.intensity;
        if (superSnapshot.kind == "superWeaponRadiation") {
            const SpecialMechanismRules& specialRules =
                state.rules.getSpecialMechanismRules();
            snapshot.maximumIntensity = std::max(
                1,
                specialRules.radiationLevelMax
            );
            snapshot.color = specialRules.radiationColor;
        }
        snapshot.progress = superSnapshot.progress;
        snapshot.requiredProgress = superSnapshot.requiredProgress;
        snapshot.expireTick = superSnapshot.expireTick;
        snapshot.owner = superSnapshot.owner;
        snapshot.phase = superSnapshot.phase;
        snapshot.resourceId = superSnapshot.resourceId;
        state.specialMechanismRenderSnapshots.push_back(std::move(snapshot));
    }
    for (const RuntimePsychicStatusRecord& status :
            state.psychicStatuses.statuses()) {
        SpecialMechanismRenderSnapshot snapshot;
        snapshot.kind = "psychicStatus";
        snapshot.instanceId = status.targetObjectId;
        snapshot.objectId = status.sourceObjectId;
        snapshot.targetObjectId = status.targetObjectId;
        snapshot.expireTick = status.expiresTick;
        snapshot.intensity = 144;
        snapshot.owner = status.targetOwner;
        snapshot.phase = status.attackOriginalAllies
            ? "BerserkFriendly"
            : "BerserkEnemy";
        state.specialMechanismRenderSnapshots.push_back(std::move(snapshot));
    }
    for (const RuntimeMagBeamBindingState& binding :
            state.magBeams.bindings()) {
        if (!binding.magBeamVisual || binding.phase == RuntimeMagBeamPhase::Falling) {
            continue;
        }
        SpecialMechanismRenderSnapshot snapshot;
        snapshot.kind = "magBeam";
        snapshot.instanceId = binding.bindingId;
        snapshot.objectId = binding.sourceObjectId;
        snapshot.targetObjectId = binding.targetObjectId;
        snapshot.owner = binding.sourceOwner;
        snapshot.phase = runtimeMagBeamPhaseName(binding.phase);
        snapshot.intensity = 208;
        constexpr std::int64_t renderQ16One = 1LL << 16U;
        const std::int64_t groundQ16 =
            static_cast<std::int64_t>(binding.kinematics.location.level)
            * renderQ16One;
        const std::int64_t heightQ16 = std::max<std::int64_t>(
            0,
            static_cast<std::int64_t>(std::llround(
                binding.kinematics.worldZ
                    * static_cast<double>(renderQ16One)
            )) - groundQ16
        );
        snapshot.requiredProgress = 1000;
        snapshot.progress = static_cast<int>(std::clamp<std::int64_t>(
            heightQ16 * snapshot.requiredProgress
                / (renderQ16One * 3LL),
            0,
            snapshot.requiredProgress
        ));
        resolveRuntimeMagBeamRenderEndpoints(state, snapshot, binding);
        state.specialMechanismRenderSnapshots.push_back(std::move(snapshot));
    }
    for (const RuntimeAirstrikeStrikeState& strike :
            state.airstrikes.strikes()) {
        const auto* target = findObjectById(state, strike.targetObjectId);
        if (strike.cancelled || !target || target->health <= 0) continue;
        const bool approaching = std::any_of(strike.planes.begin(), strike.planes.end(), [](const auto& plane) {
            return plane.phase == RuntimeAirstrikePlanePhase::Pending
                || plane.phase == RuntimeAirstrikePlanePhase::Ingress;
        });
        if (!approaching) continue;
        SpecialMechanismRenderSnapshot snapshot;
        snapshot.kind = "airstrikeMarker";
        snapshot.instanceId = strike.strikeId;
        snapshot.objectId = strike.callerObjectId;
        snapshot.targetObjectId = strike.targetObjectId;
        if (const WorldObjectInstance* caller = findObjectById(
                state,
                strike.callerObjectId
            )) {
            snapshot.cell = {caller->x, caller->y};
        }
        snapshot.targetCell = {
            strike.targetCell.x,
            strike.targetCell.y
        };
        snapshot.radius = std::max(
            1,
            static_cast<int>(strike.planes.size())
        );
        snapshot.intensity = 208;
        snapshot.owner = strike.owner;
        snapshot.phase = strike.everSpawned ? "Inbound" : "Designating";
        snapshot.progress = state.tick - strike.requestedTick;
        snapshot.requiredProgress = strike.planes.empty() ? 1
            : std::max(1, strike.planes.front().bombTick - strike.requestedTick);
        snapshot.resourceId = strike.weaponId;
        resolveRuntimeAirstrikeRenderEndpoints(state, snapshot);
        state.specialMechanismRenderSnapshots.push_back(std::move(snapshot));
    }
#include "simulation/abilities/psionic/RuntimePsychicDetectionSnapshots.inl"
}

SpecialEventSink runtimeSpecialEventSink(RuntimeProductionHostState& state) {
    return [&state](const SpecialMechanismEvent& specialEvent) {
        RuntimeReplayEventSnapshot event;
        event.kind = specialEvent.kind;
        event.objectId = specialEvent.objectId;
        event.targetObjectId = specialEvent.targetObjectId;
        event.reason = specialEvent.reason;
        event.commandTargetCell = {
            specialEvent.cell.x,
            specialEvent.cell.y
        };
        event.sourceCell = event.commandTargetCell;
        event.targetCell = event.commandTargetCell;
        event.renderIntentId =
            "special:" + specialEvent.kind + ":" + specialEvent.reason;
        event.renderIntentHash = runtimeStableHashString(
            event.renderIntentId
        );
        recordRuntimeReplayEvent(state, std::move(event));
        state.simulationStatus =
            "special " + specialEvent.kind
            + " #" + std::to_string(specialEvent.objectId);

        const SpecialMechanismRules& specialRules =
            state.rules.getSpecialMechanismRules();
        if (specialEvent.kind == "MindControlEstablished"
            && !specialRules.mindControlSound.empty()) {
            emitRuntimeSound(
                state,
                "sound:" + specialRules.mindControlSound
            );
        } else if (specialEvent.kind == "MindControlRejected") {
            state.interactionStatus =
                "mind control rejected: " + specialEvent.reason;
            if (!state.runtimeSuppressPlayerAudioFeedback) {
                emitRuntimeSound(state, "blocked");
            }
        } else if ((specialEvent.kind == "ElectricChargeStarted"
                || specialEvent.kind == "ElectricChargeRefreshed")
            && !specialRules.teslaChargeSound.empty()) {
            emitRuntimeSound(
                state,
                "sound:" + specialRules.teslaChargeSound
            );
        } else if ((specialEvent.kind == "ElectricArc"
                || specialEvent.kind == "ElectricAssaultArc")
            && !specialRules.teslaZapSound.empty()) {
            emitRuntimeSound(
                state,
                "sound:" + specialRules.teslaZapSound
            );
        } else if (specialEvent.kind == "TemporalCompleted") {
            spawnRuntimeTemporalEraseEffect(state, specialEvent);
        } else if (specialEvent.kind == "TemporalInterrupted"
            || specialEvent.kind == "TemporalTargetCleared") {
            auto* target = findMutableObjectById(state, specialEvent.targetObjectId);
            if (target != nullptr && target->mission == "Temporal"
                && !state.specialMechanisms.isTemporalFrozen(target->instanceId)) {
                target->mission = "Guard";
            }
        } else if (specialEvent.kind == "ChronoWarpOut" || specialEvent.kind == "ChronoWarpIn" || specialEvent.kind == "ChronoReinforcementIn") {
            spawnRuntimeChronoWarpEffect(state, specialEvent);
        }
    };
}

void recordRuntimeCommandReplayEvent(RuntimeProductionHostState& state) {
    if (!state.lastCommand.valid || state.lastCommand.acceptedCount <= 0) {
        return;
    }

    RuntimeReplayEventSnapshot event;
    event.kind = "CommandAccepted";
    event.commandVerb = state.lastCommand.verb;
    event.selectedCount = state.lastCommand.selectedCount;
    event.acceptedCount = state.lastCommand.acceptedCount;
    event.rejectedCount = state.lastCommand.rejectedCount;
    event.targetObjectId = state.lastCommand.targetObjectId;
    event.commandTargetCell = {
        state.lastCommand.targetX,
        state.lastCommand.targetY
    };
    event.renderIntentId = "command:" + state.lastCommand.verb;
    event.renderIntentHash = runtimeStableHashString(event.renderIntentId);
    recordRuntimeReplayEvent(state, std::move(event));
}

void setRuntimeMissionIntent(
    WorldObjectInstance& object,
    RuntimeMissionIntent intent) {
    object.mission = runtimeMissionName(intent);
}

void recordRuntimeMissionTransition(
    RuntimeProductionHostState& state,
    const WorldObjectInstance& object,
    const std::string& previousMission,
    const std::string& nextMission,
    const std::string& reason) {
    if (previousMission == nextMission) {
        return;
    }

    RuntimeReplayEventSnapshot event;
    event.kind = "MissionTransition";
    event.objectId = object.instanceId;
    event.missionFrom = previousMission;
    event.missionTo = nextMission;
    event.reason = reason;
    event.renderIntentId =
        "mission:" + previousMission + ">" + nextMission + ":" + reason;
    event.renderIntentHash = runtimeStableHashString(event.renderIntentId);
    recordRuntimeReplayEvent(state, std::move(event));

    RuntimeCapabilityProfileCache& cache = state.capabilityCache;
    ++cache.stats.missionTransitions;
    cache.lastMissionDiagnosticTick = state.tick;
    std::ostringstream stream;
    stream
        << "mission #"
        << object.instanceId
        << " "
        << object.type
        << " "
        << (previousMission.empty() ? "-" : previousMission)
        << "->"
        << (nextMission.empty() ? "-" : nextMission)
        << " reason="
        << reason
        << " tick="
        << state.tick;
    cache.recentMissionDiagnostics.push_back(stream.str());
    constexpr std::size_t maxMissionDiagnostics = 12;
    if (cache.recentMissionDiagnostics.size() > maxMissionDiagnostics) {
        cache.recentMissionDiagnostics.erase(
            cache.recentMissionDiagnostics.begin(),
            cache.recentMissionDiagnostics.begin()
                + static_cast<std::ptrdiff_t>(
                    cache.recentMissionDiagnostics.size()
                    - maxMissionDiagnostics
                )
        );
    }
}

void setRuntimeMissionIntent(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object,
    RuntimeMissionIntent intent,
    const std::string& reason) {
    const std::string previousMission = object.mission;
    std::string nextMission = runtimeMissionName(intent);
    // Queued, blocked and walking entrants retain their entry mission so
    // saving at any point in the approach keeps a valid entry or C4 intent.
    if ((intent == RuntimeMissionIntent::Moving || intent == RuntimeMissionIntent::Idle)
        && (state.pendingOccupyTargets.contains(object.instanceId)
            || state.pendingTimedBombIntents.contains(object.instanceId)))
        nextMission = runtimeMissionName(RuntimeMissionIntent::Entering);
    if (intent == RuntimeMissionIntent::Moving || intent == RuntimeMissionIntent::Idle) {
        for (const auto& relation : state.grinding.relations()) if (relation.sourceId == object.instanceId) {
            const bool folding = relation.phase == RuntimeGrindingRelationPhase::Queued
                && toLowerAsciiLocal(previousMission) == "undeploying"
                && object.buildAnimTicksRemaining > 0;
            nextMission = folding ? previousMission
                : (relation.phase == RuntimeGrindingRelationPhase::Entering
                    ? "EnteringGrinder" : "GrindingQueued");
            break;
        }
    }
    if (intent == RuntimeMissionIntent::Moving) {
        const auto slave = state.slaveMinerTasks.find(object.instanceId);
        if (slave != state.slaveMinerTasks.end() && slave->second.cargoUnits > 0)
            nextMission = "Return";
    }
    if ((intent == RuntimeMissionIntent::Moving || intent == RuntimeMissionIntent::Idle)
        && state.combatDetails.panics.contains(object.instanceId)) nextMission = "Panic";
    if (runtimeStructureIsRepacking(object)
        && (intent == RuntimeMissionIntent::Moving || intent == RuntimeMissionIntent::Idle
            || intent == RuntimeMissionIntent::Repairing))
        nextMission = "Repacking";
    object.mission = nextMission;
    recordRuntimeMissionTransition(
        state,
        object,
        previousMission,
        nextMission,
        reason
    );
}

std::string runtimeMissionStateNameForObject(
    const WorldObjectInstance& object) {
    const std::string mission = toLowerAsciiLocal(object.mission);
    if (mission == "guard" || mission == "idle") {
        return "Idle";
    }
    if (mission == "move" || mission == "moving") {
        return "Moving";
    }
    if (mission == "attack" || mission == "attacking" || mission == "secondaryfire") {
        return "Attacking";
    }
    if (mission == "landingtodeploy") {
        return "LandingToDeploy";
    }
    if (mission == "deploying") {
        return "Deploying";
    }
    if (mission == "deployed" || mission == "deployedidle") {
        return "DeployedIdle";
    }
    if (mission == "deployedfire") {
        return "DeployedFire";
    }
    if (mission == "undeploying") {
        return "Undeploying";
    }
    if (mission == "takingoffafterundeploy") {
        return "TakingOffAfterUndeploy";
    }
    if (mission == "enter"
        || mission == "entering"
        || mission == "entered") {
        return "Entering";
    }
    if (mission == "occupying" || mission == "occupied") {
        return "Occupying";
    }
    if (mission == "repairing") {
        return "Repairing";
    }
    if (mission == "load"
        || mission == "loading"
        || mission == "harvestload") {
        return "Loading";
    }
    if (mission == "unload" || mission == "unloading") {
        return "Unloading";
    }
    return object.mission.empty() ? "Idle" : object.mission;
}

bool runtimeMissionIsLandingToDeploy(const WorldObjectInstance& object) {
    return toLowerAsciiLocal(object.mission) == "landingtodeploy";
}

bool runtimeMissionIsMcvDeployPending(const WorldObjectInstance& object) {
    const auto mission = toLowerAsciiLocal(object.mission);
    return mission == "mcvdeployturning" || mission == "mcvdeployturningunselected"
        || mission == "mcvdeployready" || mission == "mcvdeployreadyunselected";
}

bool runtimeMissionIsDeploying(const WorldObjectInstance& object) {
    return toLowerAsciiLocal(object.mission) == "deploying" || runtimeMissionIsMcvDeployPending(object);
}

bool runtimeMissionIsUndeploying(const WorldObjectInstance& object) {
    return toLowerAsciiLocal(object.mission) == "undeploying";
}

bool runtimeMissionIsTakingOffAfterUndeploy(
    const WorldObjectInstance& object) {
    return toLowerAsciiLocal(object.mission) == "takingoffafterundeploy";
}

bool runtimeObjectIsDeployedMission(const WorldObjectInstance& object) {
    if (runtimeMissionIsMcvDeployPending(object)) return false;
    return object.deployed
        || runtimeMissionAllowsDeployedWeapon(object)
        || runtimeMissionIsDeploying(object)
        || runtimeMissionIsUndeploying(object);
}

bool runtimeObjectHasDeployedState(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    if (object.deployed) {
        return true;
    }

    if (runtimeObjectIsDeployedMission(object)) {
        return true;
    }

    const auto behaviorIt = state.behaviors.find(object.instanceId);
    return behaviorIt != state.behaviors.end()
        && behaviorIt->second.returnToDeployed;
}

RuntimeDeployProfile runtimeDeployProfileForUnit(const UnitType& unit) {
    RuntimeDeployProfile profile;
    profile.deployedCrushable = unit.deployedCrushable;
    profile.deployToLand = unit.deployToLand;
    profile.undeployDelay = unit.undeployDelay;
    profile.deployFacing = unit.deployFacing;
    profile.deploysInto = unit.deploysInto;
    profile.unloadingClass = unit.unloadingClass;
    profile.deployWeaponId = runtimeDeployedWeaponId(unit);
    profile.deployWeaponSlot = runtimeDeployedWeaponSlot(unit);
    profile.deployTime = unit.deployTime;
    profile.transformsIntoStructure = !unit.deploysInto.empty();
    profile.togglesDeployedState = unit.deploysInto.empty()
        && (unit.deployer
            || unit.deployFire
            || unit.deployToFire
            || unit.isSimpleDeployer
            || !unit.deployWeapon.empty()
            || !unit.eliteDeployWeapon.empty());
    profile.requiresDeploymentToFire = unit.deployToFire;
    profile.usesDeployWeapon = unit.deployFire
        || unit.deployToFire
        || unit.isSimpleDeployer
        || !unit.deployWeapon.empty()
        || !unit.eliteDeployWeapon.empty();
    profile.immobileWhenDeployed = profile.togglesDeployedState;
    profile.hasProfile = profile.transformsIntoStructure
        || profile.togglesDeployedState
        || profile.usesDeployWeapon;
    return profile;
}

RuntimeDeployProfile runtimeDeployProfileForBuilding(
    const BuildingType& building) {
    RuntimeDeployProfile profile;
    profile.deployedCrushable = building.crushable;
    profile.deployFacing = building.deployFacing;
    profile.undeploysInto = building.undeploysInto;
    profile.unloadingClass = building.unloadingClass;
    profile.deployWeaponId = !building.deployWeapon.empty()
        ? building.deployWeapon
        : (!building.eliteDeployWeapon.empty()
            ? building.eliteDeployWeapon
            : building.secondaryWeapon);
    profile.deployWeaponSlot = !building.deployWeapon.empty()
        ? RuntimeWeaponSlot::Deploy
        : (!building.eliteDeployWeapon.empty()
            ? RuntimeWeaponSlot::EliteDeploy
            : (!building.secondaryWeapon.empty()
                ? RuntimeWeaponSlot::Secondary
                : RuntimeWeaponSlot::None));
    profile.deployTime = building.deployTime;
    profile.transformsIntoStructure = false;
    profile.togglesDeployedState = !building.undeploysInto.empty()
        || building.deployer
        || building.deployFire
        || building.deployToFire
        || building.isSimpleDeployer;
    profile.requiresDeploymentToFire = building.deployToFire;
    profile.usesDeployWeapon = building.deployFire
        || building.deployToFire
        || building.isSimpleDeployer
        || !building.deployWeapon.empty()
        || !building.eliteDeployWeapon.empty();
    profile.hasProfile = !profile.undeploysInto.empty()
        || profile.togglesDeployedState
        || profile.usesDeployWeapon;
    return profile;
}

RuntimeDeployProfile runtimeDeployProfileForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    return runtimeCachedCapabilityProfileForObject(state, object).deploy;
}

RuntimeEngineerProfile runtimeEngineerProfileForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    return runtimeCachedCapabilityProfileForObject(state, object).engineer;
}

RuntimeOccupyProfile runtimeOccupyProfileForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    return runtimeCachedCapabilityProfileForObject(state, object).occupy;
}

const BuildingType* runtimeInfantryAbsorberType(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const BuildingType* building = object.kind == WorldObjectKind::Structure
        ? findRuntimeBuildingTypeById(state.rules, object.type) : nullptr;
    return building != nullptr && building->infantryAbsorb ? building : nullptr;
}

bool runtimeObjectHasTurretCapability(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    return runtimeCachedCapabilityProfileForObject(state, object).hasTurret;
}

int runtimeArtSequenceFrameCount(
    const ArtType* art,
    const std::string& sequenceName) {
    if (art == nullptr || sequenceName.empty()) {
        return 0;
    }

    const std::string wanted = toLowerAsciiLocal(sequenceName);
    for (const ArtType::SequenceFrame& frame : art->sequenceFrames) {
        if (frame.present
            && frame.frameCount > 0
            && toLowerAsciiLocal(frame.name) == wanted) {
            return frame.frameCount;
        }
    }
    return 0;
}

int runtimeDeployTransitionTicks(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object,
    const UnitType& unit,
    const std::string& mission) {
    // Psychic area pulses take effect when deploy is accepted. The infantry
    // pose must not introduce a second weapon wind-up before this instant pulse.
    if (object.kind == WorldObjectKind::Infantry
        && toLowerAsciiLocal(mission) == "deploying") {
        const WeaponType* weapon = findRuntimeWeaponType(state.rules, runtimeDeployedWeaponId(unit));
        const WarheadType* warhead = weapon == nullptr ? nullptr
            : findRuntimeWarheadType(state.rules, weapon->warhead);
        if (weapon != nullptr && weapon->areaFire && warhead != nullptr && warhead->psychicDamage) {
            return 0;
        }
    }
    const int fallbackTicks = std::max(4, state.config.fixedTickHz / 4);
    const int configuredTicks = unit.deployTime <= 0.0
        ? fallbackTicks
        : std::clamp(
        static_cast<int>(std::lround(
            unit.deployTime * static_cast<double>(state.config.fixedTickHz)
        )),
        1,
        std::max(1, state.config.fixedTickHz * 4)
    );

    const std::string missionKey = toLowerAsciiLocal(mission);
    const std::string sequenceName =
        missionKey == "undeploying" ? "Undeploy" : "Deploy";
    const int sequenceTicks =
        runtimeArtSequenceFrameCount(
            runtimeArtTypeForObject(state, object),
            sequenceName
        );

    return std::max(configuredTicks, sequenceTicks);
}

void clearRuntimeDeployRenderPosition(WorldObjectInstance& object) {
    if (object.kind == WorldObjectKind::Infantry && worldObjectHasGroundRenderPose(object)) {
        // Deploying stops at the current continuous position, including a
        // partially walked cell and its bridge height.
        object.renderMoveActive = false;
        return;
    }
    clearRuntimeRenderPosition(object);
}

bool runtimeObjectIsEnslavedSlaveWorker(const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const auto* type = object.kind == WorldObjectKind::Infantry
        ? findRuntimeUnitType(state.rules, object) : nullptr;
    return type != nullptr && type->slaved
        && state.slaveMinerTasks.contains(object.instanceId);
}

bool runtimeObjectIsAttachedSlaveWorker(const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const auto task = state.slaveMinerTasks.find(object.instanceId);
    const auto* type = object.kind == WorldObjectKind::Infantry
        ? findRuntimeUnitType(state.rules, object) : nullptr;
    const auto* parent = task == state.slaveMinerTasks.end() ? nullptr
        : findObjectById(state, task->second.refineryId);
    return object.alive && object.health > 0 && type != nullptr && type->slaved
        && parent != nullptr && parent->owner == object.owner;
}

void setRuntimeDeployMission(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object,
    const UnitType& unit,
    const std::string& mission) {
    const std::string previousMission = object.mission;
    object.mission = mission;
    recordRuntimeMissionTransition(
        state,
        object,
        previousMission,
        mission,
        "deployTransition"
    );
    object.turretFacing = object.facing;
    object.deployStateTicksRemaining = -1;
    clearRuntimeDeployRenderPosition(object);

    const std::string normalizedMission = toLowerAsciiLocal(mission);
    if (normalizedMission == "deploying"
        || normalizedMission == "deployed"
        || normalizedMission == "deployedidle"
        || normalizedMission == "deployedfire") {
        object.deployed = true;
    }

    if (normalizedMission == "deploying"
        || normalizedMission == "undeploying") {
        object.buildAnimTicksTotal =
            runtimeDeployTransitionTicks(state, object, unit, mission);
        object.buildAnimTicksRemaining = object.buildAnimTicksTotal;
    } else {
        object.buildAnimTicksTotal = 0;
        object.buildAnimTicksRemaining = 0;
    }
}

int runtimeDeployRuleFramesToTicks(
    const RuntimeGameSessionState& state,
    int authoredFrames) {
    return std::max(
        1,
        static_cast<int>(std::lround(
            static_cast<double>(std::max(0, authoredFrames))
                * static_cast<double>(std::max(1, state.config.fixedTickHz))
                / 15.0
        ))
    );
}

bool runtimeSpawnerHasInfiniteRange(const WeaponType& weapon) {
    return weapon.spawner && weapon.range == -2.0;
}

bool runtimeObjectIsOccupyingMission(const WorldObjectInstance& object) {
    return toLowerAsciiLocal(object.mission) == "occupying";
}

const char* runtimeCapabilityKindKey(WorldObjectKind kind) {
    switch (kind) {
    case WorldObjectKind::Structure:
        return "structure";
    case WorldObjectKind::Unit:
        return "unit";
    case WorldObjectKind::Infantry:
        return "infantry";
    }
    return "object";
}

std::string runtimeCapabilityCacheKeyForObject(
    const WorldObjectInstance& object) {
    const char* kindKey = runtimeCapabilityKindKey(object.kind);
    std::string key;
    key.reserve(std::strlen(kindKey) + 1 + object.type.size());
    key.append(kindKey);
    key.push_back(':');
    key.append(object.type);
    return key;
}

RuntimeUiProfile runtimeBuildUiProfileForCachedObjectType(
    const RuntimeGameSessionState& state,
    WorldObjectKind kind,
    const std::string& typeId,
    const UnitType* unit,
    const BuildingType* building) {
    RuntimeUiProfile profile;
    if (unit != nullptr) {
        profile.maxStrength = unit->strength <= 0 ? 256 : unit->strength;
        profile.pip = unit->pip;
        profile.pipScale = unit->pipScale;
    } else if (building != nullptr) {
        profile.maxStrength =
            building->strength <= 0 ? 256 : building->strength;
        profile.pip = building->pip;
        profile.pipScale = building->pipScale;
        profile.pipsDrawForAll = building->pipsDrawForAll;
    }

    (void)kind;
    if (const ArtType* art = state.art.findArtType(typeId)) {
        profile.cameoId = trimAsciiLocal(art->cameo);
    }
    return profile;
}

RuntimeCachedCapabilityProfile runtimeBuildCachedCapabilityProfile(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    RuntimeCachedCapabilityProfile cached;
    WorldObjectInstance probe;
    probe.kind = object.kind;
    probe.type = object.type;
    probe.alive = true;

    const UnitType* unit = findRuntimeUnitType(state.rules, probe);
    const BuildingType* building = findRuntimeBuildingType(state.rules, probe);
    cached.rulesResolved = unit != nullptr || building != nullptr;

    if (unit != nullptr) {
        cached.deploy = runtimeDeployProfileForUnit(*unit);
        cached.engineer.canCapture = unit->engineer;
        cached.engineer.canRepair = unit->engineer || unit->bridgeRepair;
        // Stock RA2/YR engineers use Engineer=yes for bridge huts; the
        // optional BridgeRepair flag is an extension used by some mods.
        cached.engineer.canBridgeRepair = unit->engineer || unit->bridgeRepair;
        cached.occupy.canOccupy = unit->occupier;
        cached.occupy.occupyWeaponId =
            !unit->occupyWeapon.empty()
                ? unit->occupyWeapon
                : unit->eliteOccupyWeapon;
        cached.transport.passengerCapacity = unit->passengers;
        cached.transport.unloadingClass = unit->unloadingClass;
        cached.transport.canTransport = unit->passengers > 0;
        cached.transport.canUnload =
            cached.transport.canTransport || !unit->unloadingClass.empty();
        cached.hasTurret = unit->turret;
        cached.canPassiveAcquire = unit->canPassiveAquire;
        cached.crusher = unit->crusher;
        cached.omniCrusher = unit->omniCrusher;
        cached.crushable = unit->crushable;
        cached.omniCrushResistant = unit->omniCrushResistant;
        cached.deployedCrushable = unit->deployedCrushable;
        cached.naval = unit->naval;
        cached.organic = unit->organic;
        cached.underwater = unit->underwater;
        cached.spawned = unit->spawned;
        cached.navalTargeting = unit->navalTargeting;
        cached.landTargeting = unit->landTargeting;
        cached.speedType = unit->speedType;
        cached.crushSound = unit->crushSound;
        cached.gattling = unit->gattling;
        cached.weaponStages = unit->weaponStages;
        cached.weaponStageThresholds = unit->weaponStageThresholds;
        cached.eliteWeaponStageThresholds =
            unit->eliteWeaponStageThresholds;
        cached.weaponRateUp = unit->weaponRateUp;
        cached.weaponRateDown = unit->weaponRateDown;
        cached.guardScanRange = static_cast<double>(unit->guardRange);
        cached.airRangeBonus = unit->airRangeBonus;

        if (cached.deploy.usesDeployWeapon) {
            addRuntimeWeaponCandidate(
                cached.deployWeaponCandidates,
                RuntimeWeaponSlot::Deploy,
                unit->deployWeapon
            );
            addRuntimeWeaponCandidate(
                cached.deployWeaponCandidates,
                RuntimeWeaponSlot::EliteDeploy,
                unit->eliteDeployWeapon
            );
            addRuntimeWeaponCandidate(
                cached.deployWeaponCandidates,
                RuntimeWeaponSlot::Secondary,
                unit->secondaryWeapon
            );
            addRuntimeWeaponCandidate(
                cached.deployWeaponCandidates,
                RuntimeWeaponSlot::EliteSecondary,
                unit->eliteSecondaryWeapon
            );
        }
        addRuntimeWeaponCandidate(
            cached.occupyWeaponCandidates,
            RuntimeWeaponSlot::Occupy,
            unit->occupyWeapon
        );
        addRuntimeWeaponCandidate(
            cached.occupyWeaponCandidates,
            RuntimeWeaponSlot::EliteOccupy,
            unit->eliteOccupyWeapon
        );
        cached.openTransportWeapon = runtimeOpenTransportWeaponCandidate(*unit);
        addRuntimeWeaponCandidate(
            cached.baseWeaponCandidates,
            RuntimeWeaponSlot::Primary,
            unit->primaryWeapon
        );
        addRuntimeWeaponCandidate(
            cached.baseWeaponCandidates,
            RuntimeWeaponSlot::Secondary,
            unit->secondaryWeapon
        );
        addRuntimeWeaponCandidate(
            cached.baseWeaponCandidates,
            RuntimeWeaponSlot::ElitePrimary,
            unit->elitePrimaryWeapon
        );
        addRuntimeWeaponCandidate(
            cached.baseWeaponCandidates,
            RuntimeWeaponSlot::EliteSecondary,
            unit->eliteSecondaryWeapon
        );
        cached.indexedWeaponCandidates.reserve(
            unit->indexedWeapons.size()
        );
        for (const std::string& weaponId : unit->indexedWeapons) {
            cached.indexedWeaponCandidates.emplace_back(
                RuntimeWeaponSlot::Indexed,
                weaponId
            );
        }
        cached.eliteIndexedWeaponCandidates.reserve(
            unit->eliteIndexedWeapons.size()
        );
        for (const std::string& weaponId : unit->eliteIndexedWeapons) {
            cached.eliteIndexedWeaponCandidates.emplace_back(
                RuntimeWeaponSlot::EliteIndexed,
                weaponId
            );
        }
    } else if (building != nullptr) {
        const PrismSupportRules& prismRules =
            state.rules.getSpecialMechanismRules().prismSupport;
        const bool prismSupportTower =
            !trimAsciiLocal(prismRules.prismType).empty()
            && toLowerAsciiLocal(trimAsciiLocal(object.type))
                == toLowerAsciiLocal(trimAsciiLocal(prismRules.prismType));
        cached.deploy = runtimeDeployProfileForBuilding(*building);
        cached.occupy.targetCanBeOccupied = building->canBeOccupied;
        cached.occupy.targetCanFire = building->canOccupyFire;
        cached.occupy.maxOccupants = building->maxNumberOccupants;
        cached.transport.passengerCapacity = building->bunker ? 1
            : building->infantryAbsorb ? building->passengers : 0;
        cached.transport.canTransport = cached.transport.passengerCapacity > 0;
        cached.transport.canUnload = cached.transport.canTransport;
        cached.hasTurret = building->turret || !building->turretAnim.empty();
        cached.canPassiveAcquire = building->canPassiveAquire;
        cached.crusher = building->crusher;
        cached.omniCrusher = building->omniCrusher;
        cached.crushable = building->crushable;
        cached.omniCrushResistant = building->omniCrushResistant;
        cached.deployedCrushable = building->crushable;
        cached.wall = building->wall;
        cached.naval = building->naval;
        cached.organic = building->organic;
        cached.navalTargeting = building->navalTargeting;
        cached.landTargeting = building->landTargeting;
        cached.crushSound = building->crushSound;
        cached.gattling = building->gattling;
        cached.weaponStages = building->weaponStages;
        cached.weaponStageThresholds = building->weaponStageThresholds;
        cached.eliteWeaponStageThresholds =
            building->eliteWeaponStageThresholds;
        cached.weaponRateUp = building->weaponRateUp;
        cached.weaponRateDown = building->weaponRateDown;
        cached.guardScanRange = static_cast<double>(building->guardRange);
        cached.airRangeBonus = building->airRangeBonus;

        if (cached.deploy.usesDeployWeapon) {
            addRuntimeWeaponCandidate(
                cached.deployWeaponCandidates,
                RuntimeWeaponSlot::Deploy,
                building->deployWeapon
            );
            addRuntimeWeaponCandidate(
                cached.deployWeaponCandidates,
                RuntimeWeaponSlot::EliteDeploy,
                building->eliteDeployWeapon
            );
            if (!prismSupportTower) {
                addRuntimeWeaponCandidate(
                    cached.deployWeaponCandidates,
                    RuntimeWeaponSlot::Secondary,
                    building->secondaryWeapon
                );
                addRuntimeWeaponCandidate(
                    cached.deployWeaponCandidates,
                    RuntimeWeaponSlot::EliteSecondary,
                    building->eliteSecondaryWeapon
                );
            }
        }
        addRuntimeWeaponCandidate(
            cached.baseWeaponCandidates,
            RuntimeWeaponSlot::Primary,
            building->primaryWeapon
        );
        // Retail Prism forwarding reads only Secondary.Range. The support
        // weapon is metadata and must never become an ordinary attack.
        if (!prismSupportTower) {
            addRuntimeWeaponCandidate(
                cached.baseWeaponCandidates,
                RuntimeWeaponSlot::Secondary,
                building->secondaryWeapon
            );
        }
        addRuntimeWeaponCandidate(
            cached.baseWeaponCandidates,
            RuntimeWeaponSlot::ElitePrimary,
            building->elitePrimaryWeapon
        );
        if (!prismSupportTower) {
            addRuntimeWeaponCandidate(
                cached.baseWeaponCandidates,
                RuntimeWeaponSlot::EliteSecondary,
                building->eliteSecondaryWeapon
            );
        }
        cached.indexedWeaponCandidates.reserve(
            building->indexedWeapons.size()
        );
        for (const std::string& weaponId : building->indexedWeapons) {
            cached.indexedWeaponCandidates.emplace_back(
                RuntimeWeaponSlot::Indexed,
                weaponId
            );
        }
        cached.eliteIndexedWeaponCandidates.reserve(
            building->eliteIndexedWeapons.size()
        );
        for (const std::string& weaponId : building->eliteIndexedWeapons) {
            cached.eliteIndexedWeaponCandidates.emplace_back(
                RuntimeWeaponSlot::EliteIndexed,
                weaponId
            );
        }
    }

    const auto expandGuardRange =
        [&state, &cached](const std::vector<RuntimeWeaponCandidate>& candidates) {
            for (const RuntimeWeaponCandidate& candidate : candidates) {
                const WeaponType* weapon =
                    findRuntimeWeaponType(state.rules, candidate.second);
                if (weapon != nullptr) {
                    double scanRange = weapon->range;
                    const ProjectileType* projectile =
                        findRuntimeProjectileType(
                            state.rules,
                            weapon->projectile
                        );
                    if (projectile != nullptr
                        && projectile->subjectToElevation
                        && projectile->rot == 0) {
                        const ElevationModelRules& model =
                            state.rules.getElevationModelRules();
                        scanRange += std::max(0.0, model.bonusCap)
                            * std::max(0.0, model.incrementBonus);
                    }
                    cached.guardScanRange =
                        std::max(cached.guardScanRange, scanRange);
                }
            }
        };
    expandGuardRange(cached.baseWeaponCandidates);
    expandGuardRange(cached.indexedWeaponCandidates);
    expandGuardRange(cached.eliteIndexedWeaponCandidates);
    expandGuardRange(cached.deployWeaponCandidates);
    expandGuardRange(cached.occupyWeaponCandidates);

    cached.ui = runtimeBuildUiProfileForCachedObjectType(
        state,
        object.kind,
        object.type,
        unit,
        building
    );
    return cached;
}

void runtimeResetLastTickCapabilityStats(RuntimeGameSessionState& state) {
    RuntimePerfTraceScope stageTrace("runtimeResetLastTickCapabilityStats", state.tick);
    RuntimeCapabilityCacheStats& stats = state.capabilityCache.stats;
    stats.lastTickProfileLookups = 0;
    stats.lastTickProfileHits = 0;
    stats.lastTickProfileMisses = 0;
    stats.lastTickWeaponLookups = 0;
    stats.lastTickWeaponCandidateHits = 0;
    stats.lastTickWeaponCandidateMisses = 0;
}

const RuntimeCachedCapabilityProfile& runtimeCachedCapabilityProfileForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    RuntimeCapabilityCacheStats& stats = state.capabilityCache.stats;
    ++stats.profileLookups;
    ++stats.lastTickProfileLookups;

    const std::string key = runtimeCapabilityCacheKeyForObject(object);
    auto found = state.capabilityCache.profilesByType.find(key);
    if (found != state.capabilityCache.profilesByType.end()) {
        ++stats.profileHits;
        ++stats.lastTickProfileHits;
        return found->second;
    }

    ++stats.profileMisses;
    ++stats.lastTickProfileMisses;
    auto [insertedIt, inserted] =
        state.capabilityCache.profilesByType.emplace(
            key,
            runtimeBuildCachedCapabilityProfile(state, object)
        );
    (void)inserted;
    return insertedIt->second;
}

const std::vector<int>& runtimeGattlingStageThresholds(
    const RuntimeCachedCapabilityProfile& cached,
    bool elite) {
    return elite && !cached.eliteWeaponStageThresholds.empty()
        ? cached.eliteWeaponStageThresholds
        : cached.weaponStageThresholds;
}

int runtimeGattlingTimerCap(
    const RuntimeCachedCapabilityProfile& cached,
    bool elite) {
    const std::vector<int>& thresholds =
        runtimeGattlingStageThresholds(cached, elite);
    return thresholds.empty()
        ? std::numeric_limits<int>::max() / 4
        : std::max(
            1,
            *std::max_element(thresholds.begin(), thresholds.end())
        );
}

RuntimeTargetDomain runtimeTargetDomainForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& target) {
    if (runtimeObjectIsAirTarget(state, target)) {
        return RuntimeTargetDomain::Air;
    }
    if (target.onBridge) {
        return RuntimeTargetDomain::Land;
    }
    if (target.submerged) {
        return RuntimeTargetDomain::Water;
    }

    const auto terrainIt = state.terrainInfoByCell.find(
        runtimeCellKey(target.x, target.y)
    );
    if (terrainIt != state.terrainInfoByCell.end()) {
        return terrainIt->second.water && !terrainIt->second.bridge
            ? RuntimeTargetDomain::Water
            : RuntimeTargetDomain::Land;
    }

    const RuntimeCachedCapabilityProfile& targetProfile =
        runtimeCachedCapabilityProfileForObject(state, target);
    return targetProfile.naval
        ? RuntimeTargetDomain::Water
        : RuntimeTargetDomain::Land;
}

RuntimePsychicObjectKind runtimePsychicKindForObject(
    const WorldObjectInstance& object) {
    if (object.kind == WorldObjectKind::Structure) {
        return RuntimePsychicObjectKind::Structure;
    }
    if (object.kind == WorldObjectKind::Infantry) {
        return RuntimePsychicObjectKind::Infantry;
    }
    return object.authoredAircraft
        ? RuntimePsychicObjectKind::Aircraft
        : RuntimePsychicObjectKind::Vehicle;
}

RuntimePsychicObjectKind runtimePsychicKindForLaunchSource(
    int sourceKind,
    bool authoredAircraft) {
    if (sourceKind == static_cast<int>(WorldObjectKind::Structure)) {
        return RuntimePsychicObjectKind::Structure;
    }
    if (sourceKind == static_cast<int>(WorldObjectKind::Infantry)) {
        return RuntimePsychicObjectKind::Infantry;
    }
    if (sourceKind == static_cast<int>(WorldObjectKind::Unit)) {
        return authoredAircraft
            ? RuntimePsychicObjectKind::Aircraft
            : RuntimePsychicObjectKind::Vehicle;
    }
    return RuntimePsychicObjectKind::Other;
}

RuntimePsychicObjectSnapshot runtimePsychicObjectSnapshot(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    RuntimePsychicObjectSnapshot snapshot;
    snapshot.objectId = object.instanceId;
    snapshot.owner = object.owner;
    snapshot.typeId = object.type;
    snapshot.kind = runtimePsychicKindForObject(object);
    snapshot.present = true;
    snapshot.alive = object.alive && object.health > 0;
    snapshot.airborne = object.airborne || object.authoredAircraft;
    if (object.kind == WorldObjectKind::Structure) {
        const BuildingType* building = findRuntimeBuildingTypeById(
            state.rules,
            object.type
        );
        snapshot.immuneToPsionics = building == nullptr
            || building->immuneToPsionics;
    } else {
        const UnitType* unit = findRuntimeUnitType(state.rules, object);
        snapshot.immuneToPsionics = unit != nullptr
            && unit->immuneToPsionics;
        snapshot.berserkFriendly = unit != nullptr
            && unit->berserkFriendly;
    }
    return snapshot;
}

RuntimePsychicRelation runtimePsychicRelationForObjects(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& actor,
    const WorldObjectInstance& candidate) {
    if (actor.instanceId == candidate.instanceId) {
        return RuntimePsychicRelation::Self;
    }
    if (runtimeOwnersAreAllied(state, actor.owner, candidate.owner)) {
        return RuntimePsychicRelation::Allied;
    }
    if (runtimeOwnerIsNeutralForAutoTarget(candidate.owner)) {
        return RuntimePsychicRelation::Neutral;
    }
    return RuntimePsychicRelation::Enemy;
}

bool runtimeObjectIsImmobileDeployed(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const RuntimeCachedCapabilityProfile& cached =
        runtimeCachedCapabilityProfileForObject(state, object);
    const RuntimeDeployProfile deployProfile =
        cached.deploy;
    return cached.rulesResolved
        && runtimeObjectHasDeployedState(state, object)
        && deployProfile.immobileWhenDeployed;
}

bool runtimeInfantryRequiresManualUndeploy(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    return object.kind == WorldObjectKind::Infantry
        && runtimeObjectIsImmobileDeployed(state, object);
}

bool runtimeObjectCanMove(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object,
    bool ignoreDeployedState) {
    const RuntimeCachedCapabilityProfile& cached =
        runtimeCachedCapabilityProfileForObject(state, object);
    const bool immobileDeployed =
        cached.rulesResolved
        && runtimeObjectHasDeployedState(state, object)
        && cached.deploy.immobileWhenDeployed;
    return object.alive
        && (object.kind == WorldObjectKind::Unit
            || object.kind == WorldObjectKind::Infantry)
        && cached.rulesResolved
        && (ignoreDeployedState || !immobileDeployed)
        && !runtimeVehicleStartupCannotMove(state, object)
        && object.mission != "ParadropDrop"
        && object.mission != "SupportFlightEast" && object.mission != "SupportFlightWest"
        && !runtimeMissionIsMcvDeployPending(object)
        && object.tankBunkerHostId < 0
        && !runtimeMissionIsLandingToDeploy(object)
        && !runtimeMissionIsTakingOffAfterUndeploy(object)
        && !runtimeObjectManagedByAirstrike(state, object.instanceId)
        && !runtimeObjectDisabledByParasite(state, object.instanceId)
        && (!state.specialMechanismsInitialized
            || (!state.specialMechanisms.isChronoMovementLocked(object.instanceId, state.tick)
                && !state.specialMechanisms.isTemporalFrozen(
                    object.instanceId
                )
                && !state.specialMechanisms.isCarrierChildDocked(
                    object.instanceId
                )));
}

std::optional<std::string> runtimeVoiceEventFromField(
    const RuntimeProductionHostState& state,
    const WorldObjectInstance& object,
    const std::string& voiceKind,
    const std::string& voiceField) {
    const std::vector<std::string> tokens =
        splitRuntimeTokenList(voiceField);
    if (tokens.empty()) {
        return std::nullopt;
    }
    const std::size_t seed =
        (static_cast<std::size_t>(std::max(0, object.instanceId)) * 131U)
        + (static_cast<std::size_t>(std::max(0, state.tick)) * 17U)
        + (static_cast<std::size_t>(state.runtimeSoundEvents) * 29U)
        + (voiceKind.size() * 7U);
    return tokens[seed % tokens.size()];
}

bool runtimePoweredUnitIsOperational(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const UnitType* unit = findRuntimeUnitType(state.rules, object);
    if (unit == nullptr || !unit->poweredUnit) {
        return true;
    }

    const std::string unitId = toUpperAsciiLocal(trimAsciiLocal(unit->id));
    const std::string unitOwner =
        toUpperAsciiLocal(trimAsciiLocal(object.owner));
    for (const WorldObjectInstance& candidate : state.world.getObjects()) {
        if (!candidate.alive
            || candidate.kind != WorldObjectKind::Structure
            || toUpperAsciiLocal(trimAsciiLocal(candidate.owner))
                != unitOwner) {
            continue;
        }
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, candidate.type);
        if (building == nullptr) {
            continue;
        }
        bool powersThisUnit = false;
        for (const std::string& poweredId :
                splitRuntimeTokenList(building->powersUnit)) {
            if (toUpperAsciiLocal(trimAsciiLocal(poweredId)) == unitId) {
                powersThisUnit = true;
                break;
            }
        }
        if (powersThisUnit
            && (!building->powered || candidate.poweredOperational)) {
            return true;
        }
    }
    return false;
}

std::optional<std::string> runtimeVoiceEventForSelectedUnits(
    const RuntimeProductionHostState& state,
    const std::string& voiceKind,
    const WorldObjectInstance* targetObject,
    bool forceFire) {
    for (int objectId : state.selectedObjectIds) {
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object == nullptr || object->owner != state.economy.owner) {
            continue;
        }

        const UnitType* unit = findRuntimeUnitType(state.rules, *object);
        if (unit == nullptr) {
            continue;
        }

        std::string voice;
        if (voiceKind == "select") {
            const bool deactivated = !runtimePoweredUnitIsOperational(
                state,
                *object
            );
            const bool currentlyEnslaved =
                state.slaveMinerTasks.find(object->instanceId)
                    != state.slaveMinerTasks.end();
            voice = deactivated
                    && !trimAsciiLocal(unit->voiceSelectDeactivated).empty()
                ? unit->voiceSelectDeactivated
                : currentlyEnslaved
                    && !trimAsciiLocal(unit->voiceSelectEnslaved).empty()
                ? unit->voiceSelectEnslaved
                : unit->voiceSelect;
        } else if (voiceKind == "move") {
            voice = unit->voiceMove;
        } else if (voiceKind == "attack") {
            const RuntimeWeaponProfile weaponProfile =
                runtimeWeaponProfileForObject(state, *object, targetObject, forceFire);
            const bool selectedSecondary =
                weaponProfile.slot == RuntimeWeaponSlot::Secondary
                || weaponProfile.slot == RuntimeWeaponSlot::EliteSecondary;
            voice = selectedSecondary
                    && !trimAsciiLocal(
                        unit->voiceSecondaryWeaponAttack
                    ).empty()
                ? unit->voiceSecondaryWeaponAttack
                : unit->voiceAttack;
        } else if (voiceKind == "feedback") {
            voice = unit->voiceFeedback;
        } else if (voiceKind == "special") {
            voice = unit->voiceSpecialAttack;
        } else if (voiceKind == "enter") {
            voice = unit->voiceEnter;
        } else if (voiceKind == "capture") {
            voice = unit->voiceCapture;
        } else if (voiceKind == "harvest") {
            voice = unit->voiceHarvest;
        } else if (voiceKind == "crashing") {
            voice = unit->voiceCrashing;
        }

        if (const std::optional<std::string> event =
                runtimeVoiceEventFromField(
                    state,
                    *object,
                    voiceKind,
                    voice
                );
            event.has_value()) {
            return event;
        }
    }
    return std::nullopt;
}

std::optional<std::string> runtimeSecondaryActionVoiceEvent(
    const RuntimeProductionHostState& state,
    const WorldObjectInstance& object,
    const UnitType& unit) {
    if (!trimAsciiLocal(unit.voiceDeploy).empty()) {
        return runtimeVoiceEventFromField(
            state,
            object,
            "deploy",
            unit.voiceDeploy
        );
    }
    return runtimeVoiceEventFromField(
        state,
        object,
        "special",
        unit.voiceSpecialAttack
    );
}

double runtimeLandTypePercentForMover(
    const LandType& landType,
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& mover) {
    const UnitType* unit = findRuntimeUnitType(state.rules, mover);
    if (unit == nullptr) {
        return mover.kind == WorldObjectKind::Infantry
            ? landType.foot
            : landType.track;
    }

    if (!runtimeSimulationQueryReuseReference()
        && !runtimeMovementClassificationReference()) {
        return runtimeUnitLandPercentProfile(
            landType, *unit, mover.kind == WorldObjectKind::Infantry);
    }

    const std::string speedType = toLowerAsciiLocal(unit->speedType);
    const std::string movementZone = toLowerAsciiLocal(unit->movementZone);
    if (speedType.find("hover") != std::string::npos
        || movementZone.find("hover") != std::string::npos
        || movementZone.find("fly") != std::string::npos) {
        return landType.hover;
    }
    if (speedType.find("amphib") != std::string::npos
        || movementZone.find("amphib") != std::string::npos) {
        return landType.amphibious;
    }
    if (speedType.find("floatbeach") != std::string::npos
        || movementZone.find("floatbeach") != std::string::npos) {
        return landType.floatBeach;
    }
    if (speedType.find("float") != std::string::npos
        || speedType.find("water") != std::string::npos
        || movementZone.find("water") != std::string::npos
        || unit->naval
        || unit->waterBound) {
        return landType.floatSpeed;
    }
    if (speedType.find("track") != std::string::npos) {
        return landType.track;
    }
    if (speedType.find("wheel") != std::string::npos) {
        return landType.wheel;
    }
    if (mover.kind == WorldObjectKind::Infantry
        || speedType.find("foot") != std::string::npos
        || movementZone.find("infantry") != std::string::npos) {
        return landType.foot;
    }
    return unit->crusher ? landType.track : landType.wheel;
}

int runtimeLandTypeCost(int baseCost, double percent) {
    if (baseCost <= 0) {
        return 1;
    }
    if (percent <= 0.0) {
        return std::numeric_limits<int>::max() / 4;
    }

    const double scaled = static_cast<double>(baseCost) * (100.0 / percent);
    return std::clamp(
        static_cast<int>(std::lround(scaled)),
        1,
        240
    );
}

const ArtType* runtimeArtTypeForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    std::string artId = object.type;
    bool alternateArcticArt = false;
    if (const UnitType* unit = findRuntimeUnitType(state.rules, object)) {
        if (!trimAsciiLocal(unit->image).empty()) {
            artId = trimAsciiLocal(unit->image);
        }
        alternateArcticArt = unit->alternateArcticArt;
    } else if (const BuildingType* building =
                   findRuntimeBuildingType(state.rules, object)) {
        if (!trimAsciiLocal(building->image).empty()) {
            artId = trimAsciiLocal(building->image);
        }
        alternateArcticArt = building->alternateArcticArt;
    }
    return state.art.findArtType(runtimeArcticArtId(artId, alternateArcticArt,
        runtimeArcticTheater(state.theaterLoaded ? state.theater.getTileExtension() : state.report.map.theater)));
}

const ArtType::SequenceFrame* runtimeSequenceFrameByName(
    const ArtType& art,
    const std::string& name) {
    const std::string wanted = toLowerAsciiLocal(name);
    for (const ArtType::SequenceFrame& frame : art.sequenceFrames) {
        if (frame.present
            && frame.frameCount > 0
            && toLowerAsciiLocal(frame.name) == wanted) {
            return &frame;
        }
    }
    return nullptr;
}

bool runtimeIdleSequenceLooksSafe(
    const ArtType& art,
    const std::string& name) {
    const ArtType::SequenceFrame* idle = runtimeSequenceFrameByName(art, name);
    if (idle == nullptr || idle->frameCount < 4) {
        return false;
    }

    const int idleBegin = idle->startFrame;
    const int idleEnd = idle->startFrame + std::max(1, idle->frameCount);
    const auto overlapsSequence = [&](const char* otherName) {
        const ArtType::SequenceFrame* other =
            runtimeSequenceFrameByName(art, otherName);
        if (other == nullptr || other->frameCount <= 0) {
            return false;
        }
        const int otherBegin = other->startFrame;
        const int otherEnd =
            other->startFrame + std::max(1, other->frameCount);
        return idleBegin < otherEnd && otherBegin < idleEnd;
    };
    const char* unsafeSequences[] = {
        "Crawl",
        "Prone",
        "FireProne",
        "SecondaryProne",
        "Down",
        "Up",
        "Deploy",
        "Deployed",
        "DeployedIdle",
        "DeployedFire",
        "Undeploy"
    };
    for (const char* unsafe : unsafeSequences) {
        if (overlapsSequence(unsafe)) {
            return false;
        }
    }

    return true;
}

bool runtimeUnitTypeLooksNaval(const UnitType& unit) {
    const std::string speedType = toLowerAsciiLocal(unit.speedType);
    const std::string movementZone = toLowerAsciiLocal(unit.movementZone);
    const std::string dock = toLowerAsciiLocal(unit.dock);
    return unit.naval
        || unit.waterBound
        || speedType.find("float") != std::string::npos
        || speedType.find("water") != std::string::npos
        || movementZone.find("water") != std::string::npos
        || dock.find("yard") != std::string::npos;
}

bool runtimeTextContains(const std::string& value, const std::string& needle) {
    return value.find(needle) != std::string::npos;
}

bool runtimeTileSetMatches(
    const TheaterDatabase& theater,
    int tileSetIndex,
    const std::string& key) {
    return tileSetIndex >= 0
        && tileSetIndex == theater.getGeneralTileSetIndex(key);
}

bool runtimeAuthoredLandOrdinalAllowsMoverUncached(
    const RuntimeGameSessionState& state,
    RuntimeTerrainLandType authoredLandType,
    const WorldObjectInstance& mover) {
    const char* landTypeId = runtimeTerrainLandTypeRulesId(authoredLandType);
    if (landTypeId == nullptr) {
        return true;
    }
    const LandType* landType = state.rules.findLandType(landTypeId);
    return landType == nullptr
        || runtimeLandTypePercentForMover(*landType, state, mover) > 0.0;
}

bool runtimeAuthoredLandTypeAllowsMoverUncached(
    const RuntimeGameSessionState& state,
    const RuntimeTerrainInfo& terrainInfo,
    const WorldObjectInstance& mover) {
    return runtimeAuthoredLandOrdinalAllowsMoverUncached(state,terrainInfo.authoredLandType,mover);
}

bool runtimeTheaterGeneralValueMatches(
    const RuntimeGameSessionState& state,
    int value,
    std::initializer_list<const char*> keys) {
    for (const char* key : keys) {
        if (state.theater.getGeneralTileSetIndex(key) == value) {
            return true;
        }
    }
    return false;
}

std::vector<RuntimeCellPoint> runtimeSameTileCluster(
    RuntimeProductionHostState& state,
    const TerrainCell& seed) {
    std::vector<RuntimeCellPoint> cluster;
    int gridWidth = 0, gridHeight = 0;
    if (!resolveRuntimeTerrainTileGridShape(seed, runtimeTerrainMetadataContext(state),
            state.renderCache, gridWidth, gridHeight)) {
        return cluster;
    }
    const RuntimeCellPoint origin{seed.x - seed.subTileIndex % gridWidth,
        seed.y - seed.subTileIndex / gridWidth};
    std::deque<RuntimeCellPoint> pending;
    std::unordered_set<int> visited;
    pending.push_back({seed.x, seed.y});
    while (!pending.empty()) {
        const RuntimeCellPoint point = pending.front();
        pending.pop_front();
        const int key = runtimeCellKey(point.x, point.y);
        if (!visited.insert(key).second) {
            continue;
        }
        const auto terrainIt = state.terrainByCell.find(key);
        if (terrainIt == state.terrainByCell.end()
            || terrainIt->second == nullptr
            || terrainIt->second->tileIndex != seed.tileIndex
            || terrainIt->second->subTileIndex < 0
            || terrainIt->second->subTileIndex >= gridWidth * gridHeight
            || terrainIt->second->x - terrainIt->second->subTileIndex % gridWidth != origin.x
            || terrainIt->second->y - terrainIt->second->subTileIndex / gridWidth != origin.y) {
            continue;
        }
        cluster.push_back(point);
        pending.push_back({point.x + 1, point.y});
        pending.push_back({point.x - 1, point.y});
        pending.push_back({point.x, point.y + 1});
        pending.push_back({point.x, point.y - 1});
    }
    return cluster;
}

const MapCellFacts* runtimeMapQueryCell(
    const RuntimeGameSessionState& state,
    const RuntimeCellPoint& point) {
    if (!state.mapFactsLoaded || state.mapFacts.cells.empty()) {
        return nullptr;
    }
    constexpr int RuntimeMapCoordinateLimit = 512;
    if (point.x < 0
        || point.y < 0
        || point.x >= RuntimeMapCoordinateLimit
        || point.y >= RuntimeMapCoordinateLimit) {
        return nullptr;
    }

    const int cellIndex = (point.y * RuntimeMapCoordinateLimit) + point.x;
    const auto found = state.mapFacts.cellIndexLookup.find(cellIndex);
    if (found == state.mapFacts.cellIndexLookup.end()
        || found->second >= state.mapFacts.cells.size()) {
        return nullptr;
    }
    return &state.mapFacts.cells[found->second];
}

const MapStructureAnchorFact* runtimeMapQueryStructureAnchor(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& structure,
    const MapQuery& query) {
    if (!state.mapFactsLoaded || structure.kind != WorldObjectKind::Structure) {
        return nullptr;
    }
    if (!structure.mapId.empty()) {
        if (const MapStructureAnchorFact* anchor =
                query.getStructureAnchorById(structure.mapId)) {
            return anchor;
        }
    }
    const std::string wantedType = toUpperAsciiLocal(structure.type);
    for (const MapStructureAnchorFact& anchor : state.mapFacts.structureAnchors) {
        if (toUpperAsciiLocal(anchor.type) != wantedType) {
            continue;
        }
        const int width = std::max(1, anchor.footprintWidth);
        const int height = std::max(1, anchor.footprintHeight);
        const bool insideFootprint =
            structure.x >= anchor.x
            && structure.x < anchor.x + width
            && structure.y >= anchor.y
            && structure.y < anchor.y + height;
        const bool nearAnchor =
            std::abs(structure.x - anchor.x) <= std::max(1, width)
            && std::abs(structure.y - anchor.y) <= std::max(1, height);
        if ((anchor.x == structure.x && anchor.y == structure.y)
            || insideFootprint
            || nearAnchor) {
            return &anchor;
        }
    }
    return nullptr;
}

bool runtimeCellHasHardWholeCellBlocker(
    const RuntimeGameSessionState& state,
    const RuntimeCellPoint& cell,
    int moverObjectId,
    int allowedOccupiedObjectId,
    const std::unordered_set<int>& ignoredObjectIds,
    bool forceReference) {
    RuntimePerfTraceScope movePhaseTrace("moveHardBlocker", state.tick);
    if (!forceReference && !runtimeFrameScalingReferenceMovement()
        && runtimePlannerCensusProvesEmptyCell(state,cell,RuntimePlannerEmptyCellQuery::HardBlocker)) return false;
    if (!forceReference && !runtimeFrameScalingReferenceMovement()
        && runtimeMovementTickProvesEmptyCell(state, cell)) return false;
    for (const WorldTerrainObject& terrainObject :
            state.world.getTerrainObjects()) {
        if (!runtimeTerrainObjectBlocksGround(terrainObject)) {
            continue;
        }
        const std::vector<RuntimeCellPoint> cells =
            runtimeTerrainObjectFootprintCells(terrainObject);
        if (std::find(cells.begin(), cells.end(), cell) != cells.end()) {
            return true;
        }
    }
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (runtimeInvisibleMapBuilding(&state.rules, object)) continue;
        if (!object.alive
            || object.instanceId == moverObjectId
            || object.instanceId == allowedOccupiedObjectId
            || ignoredObjectIds.find(object.instanceId)
                != ignoredObjectIds.end()
            || object.kind == WorldObjectKind::Infantry
            || !runtimeObjectOccupiesCrushCell(state, object, cell)
            || (object.kind != WorldObjectKind::Structure
                && runtimeObjectMovementMode(state, object)
                    == PathMovementMode::Air)) {
            continue;
        }
        return true;
    }
    return false;
}

bool runtimeObjectIsEffectiveCrusher(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const RuntimeCachedCapabilityProfile& cached =
        runtimeCachedCapabilityProfileForObject(state, object);
    return cached.rulesResolved
        && (cached.crusher
            || cached.omniCrusher
            || runtimeVeterancyHasAbility(
                state,
                object,
                VeteranAbility::Crusher
            ));
}

bool runtimeObjectOccupiesCrushCell(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object,
    const RuntimeCellPoint& cell) {
    if (runtimeObjectOffGroundByMagBeam(state, object.instanceId)) {
        return false;
    }
    if (object.kind != WorldObjectKind::Structure) {
        return object.x == cell.x && object.y == cell.y;
    }
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, object);
    const RuntimeCellPoint origin = runtimeCellPointForObject(object);
    const std::int64_t dx = static_cast<std::int64_t>(cell.x) - origin.x;
    const std::int64_t dy = static_cast<std::int64_t>(cell.y) - origin.y;
    return dx >= 0 && dy >= 0
        && dx < std::max(1, footprint.width)
        && dy < std::max(1, footprint.height);
}

bool runtimeAllowedObjectOccupiesCell(
    const RuntimeGameSessionState& state,
    const RuntimeCellPoint& cell,
    int allowedOccupiedObjectId) {
    if (allowedOccupiedObjectId < 0) {
        return false;
    }
    const WorldObjectInstance* allowedObject =
        findObjectById(state, allowedOccupiedObjectId);
    return allowedObject != nullptr
        && runtimeObjectOccupiesCrushCell(state, *allowedObject, cell);
}

bool runtimeCrusherCanCrushObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& crusher,
    const WorldObjectInstance& target,
    const RuntimeCellPoint& destination,
    bool physicalContact) {
    if (!target.alive
        || target.instanceId == crusher.instanceId
        || target.airborne
        || target.dockedToObjectId >= 0
        || runtimeObjectOffGroundByMagBeam(state, target.instanceId)
        || (state.superWeaponsInitialized
            && state.superWeapons.isObjectProtected(target.instanceId, state.tick))
        || target.submerged
        || (!physicalContact && target.onBridge
            != runtimeCellIsBridge(state, destination.x, destination.y))
        || runtimeOwnersAreAllied(state, crusher.owner, target.owner)) {
        return false;
    }

    const RuntimeCachedCapabilityProfile& targetProfile =
        runtimeCachedCapabilityProfileForObject(state, target);
    if (!targetProfile.rulesResolved || targetProfile.omniCrushResistant) {
        return false;
    }

    if (target.kind == WorldObjectKind::Structure) {
        // OmniCrusher never turns ordinary buildings into traversable cells.
        return targetProfile.wall && targetProfile.crushable;
    }

    const RuntimeCachedCapabilityProfile& crusherProfile =
        runtimeCachedCapabilityProfileForObject(state, crusher);
    if (crusherProfile.omniCrusher) {
        return true;
    }
    return runtimeObjectHasDeployedState(state, target)
        ? targetProfile.deployedCrushable
        : targetProfile.crushable;
}

std::uint64_t runtimeCrushCandidateCellKey(int x, int y) {
    return (static_cast<std::uint64_t>(static_cast<std::uint32_t>(x)) << 32U)
        | static_cast<std::uint32_t>(y);
}

RuntimeCrushCandidateLookup buildRuntimeCrushCandidateLookup(
    const RuntimeGameSessionState& state,
    const std::vector<PathTerrainCell>& snapshot,
    const RuntimePathDynamicPreparationBounds* provenBounds) {
    RuntimeCrushCandidateLookup candidates;
    if (snapshot.empty()) {
        return candidates;
    }
    int minimumX = snapshot.front().cell.x;
    int maximumX = minimumX;
    int minimumY = snapshot.front().cell.y;
    int maximumY = minimumY;
    if (provenBounds != nullptr) {
        minimumX = provenBounds->minimumX; maximumX = provenBounds->maximumX;
        minimumY = provenBounds->minimumY; maximumY = provenBounds->maximumY;
    } else {
        for (const PathTerrainCell& cell : snapshot) {
            minimumX = std::min(minimumX, cell.cell.x);
            maximumX = std::max(maximumX, cell.cell.x);
            minimumY = std::min(minimumY, cell.cell.y);
            maximumY = std::max(maximumY, cell.cell.y);
        }
    }
    candidates.reserve(std::min(state.world.getObjects().size(), snapshot.size()));
    const auto appendCandidate = [&](int x, int y, const WorldObjectInstance& object) {
        RuntimeCrushCandidateList& list =
            candidates[runtimeCrushCandidateCellKey(x, y)];
        if (list.empty() || list.back() != &object) {
            list.push_back(&object);
        }
    };
    // Append in world order. Keep all occupants here; the scan below owns
    // alive, air, MagBeam, ignored-object and vehicle-drive-row semantics.
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (object.kind != WorldObjectKind::Structure) {
            if (object.x >= minimumX && object.x <= maximumX
                && object.y >= minimumY && object.y <= maximumY) {
                appendCandidate(object.x, object.y, object);
            }
            continue;
        }
        const RuntimeStructureFootprint footprint =
            runtimeStructureFootprintForObject(state, object);
        const std::int64_t firstX = std::max<std::int64_t>(minimumX, object.x);
        const std::int64_t firstY = std::max<std::int64_t>(minimumY, object.y);
        const std::int64_t lastX = std::min<std::int64_t>(
            maximumX,
            static_cast<std::int64_t>(object.x) + std::max(1, footprint.width) - 1
        );
        const std::int64_t lastY = std::min<std::int64_t>(
            maximumY,
            static_cast<std::int64_t>(object.y) + std::max(1, footprint.height) - 1
        );
        if (firstX > lastX || firstY > lastY) {
            continue;
        }
        const std::uint64_t width = static_cast<std::uint64_t>(lastX - firstX + 1);
        const std::uint64_t height = static_cast<std::uint64_t>(lastY - firstY + 1);
        // Sparse or unusually large foundations must not expand beyond the
        // amount of terrain this one snapshot can actually query.
        if (width > static_cast<std::uint64_t>(snapshot.size()) / height) {
            for (const PathTerrainCell& cell : snapshot) {
                if (cell.cell.x >= firstX && cell.cell.x <= lastX
                    && cell.cell.y >= firstY && cell.cell.y <= lastY) {
                    appendCandidate(cell.cell.x, cell.cell.y, object);
                }
            }
            continue;
        }
        for (std::int64_t y = firstY; y <= lastY; ++y) {
            for (std::int64_t x = firstX; x <= lastX; ++x) {
                appendCandidate(static_cast<int>(x), static_cast<int>(y), object);
            }
        }
    }
    return candidates;
}

RuntimeCrushTargetScan runtimeScanCrushTargetsAtCell(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& crusher,
    const RuntimeCellPoint& cell,
    int allowedOccupiedObjectId,
    const std::unordered_set<int>* additionallyIgnoredObjectIds,
    const RuntimeCrushCandidateList* candidates) {
    RuntimeCrushTargetScan scan;
    const int departureHostId = allowedOccupiedObjectId < 0
        ? runtimeStructureDepartureHostId(state, crusher) : -1;
    const bool crushingMovement =
        runtimeCrusherUsesCrushingMovement(state, crusher);
    const std::unordered_set<int> strictOpenGateIds =
        runtimeStrictOpenGateIdsAtCell(state, crusher, cell);

    const std::vector<WorldObjectInstance>& objects = state.world.getObjects();
    const std::size_t candidateCount = candidates == nullptr
        ? objects.size() : candidates->size();
    for (std::size_t index = 0; index < candidateCount; ++index) {
        const WorldObjectInstance& target = candidates == nullptr
            ? objects[index] : *(*candidates)[index];
        if (!target.alive
            || target.instanceId == crusher.instanceId
            || target.instanceId == allowedOccupiedObjectId
            || strictOpenGateIds.find(target.instanceId)
                != strictOpenGateIds.end()
            || (additionallyIgnoredObjectIds != nullptr
                && additionallyIgnoredObjectIds->find(target.instanceId)
                    != additionallyIgnoredObjectIds->end())
            // Reject unrelated cells before resolving each object's movement
            // rules; snapshot construction queries this for every blocker.
            || !runtimeObjectOccupiesCrushCell(state, target, cell)
            || (runtimeObjectMovementMode(state, target) == PathMovementMode::Air
                && (target.airborne || target.dockedToObjectId >= 0))) {
            continue;
        }
        if (target.instanceId == departureHostId
            && runtimeStructureCellIsVehicleDriveRow(state, target, cell, crusher)) continue;
        if (!crushingMovement
            || !runtimeCrusherCanCrushObject(state, crusher, target, cell)) {
            scan.blocked = true;
            scan.targetIds.clear();
            return scan;
        }
        scan.targetIds.push_back(target.instanceId);
    }
    std::sort(scan.targetIds.begin(), scan.targetIds.end());
    scan.targetIds.erase(
        std::unique(scan.targetIds.begin(), scan.targetIds.end()),
        scan.targetIds.end()
    );
    return scan;
}

bool runtimeCanEnterAndCrushCell(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& crusher,
    const RuntimeCellPoint& cell,
    const std::unordered_set<int>* additionallyIgnoredObjectIds,
    const RuntimeCrushCandidateList* candidates,
    bool forceReference) {
    // A non-crushing mover can never produce an enterable crush-target list.
    // Keep the detailed scan's blocked result unchanged for its other users.
    if (!runtimeCrusherUsesCrushingMovement(state, crusher)) {
        return false;
    }
    if (!forceReference && !runtimeFrameScalingReferenceMovement()
        && candidates == nullptr
        && runtimeCrushRepresentativeProvesBlocked(state, crusher, cell, additionallyIgnoredObjectIds))
        return false;
    const RuntimeCrushTargetScan scan =
        runtimeScanCrushTargetsAtCell(
            state,
            crusher,
            cell,
            -1,
            additionallyIgnoredObjectIds,
            candidates
        );
    return !scan.blocked && !scan.targetIds.empty();
}

bool runtimeCellReservedByOtherRepairUnit(
    const RuntimeGameSessionState& state,
    const RuntimeCellPoint& cell,
    int moverObjectId) {
    if (state.repairDepots.relations().empty()) {
        return false;
    }
    const bool cellOnBridge = runtimeCellIsBridge(state, cell.x, cell.y);
    for (const RuntimeRepairDepotRelation& relation :
            state.repairDepots.relations()) {
        if (relation.unitId == moverObjectId) {
            continue;
        }
        const RuntimeRepairDepotCell& reserved =
            relation.phase == RuntimeRepairDepotRelationPhase::Queued
                ? relation.queueCell
                : relation.dockCell;
        if (reserved.x >= 0
            && reserved.y >= 0
            && reserved.x == cell.x
            && reserved.y == cell.y
            && reserved.onBridge == cellOnBridge) {
            return true;
        }
    }
    return false;
}

std::optional<int> runtimeCellTraversalCost(
    const RuntimeGameSessionState& state,
    const std::unordered_map<int, const TerrainCell*>& terrainByCell,
    const std::unordered_map<int, int>& occupiedByCell,
    const RuntimeCellPoint& current,
    const RuntimeCellPoint& next,
    const WorldObjectInstance& mover,
    int allowedOccupiedObjectId) {
    if (!runtimeCellTransitionIsPassable(
            state,
            terrainByCell,
            occupiedByCell,
            current,
            next,
            mover,
            allowedOccupiedObjectId
        )) {
        return std::nullopt;
    }

    const int dx = next.x - current.x;
    const int dy = next.y - current.y;
    const auto terrainIt = terrainByCell.find(runtimeCellKey(next.x, next.y));
    if (terrainIt == terrainByCell.end() || terrainIt->second == nullptr) {
        return std::nullopt;
    }

    const RuntimeTerrainInfo terrainInfo =
        runtimeCachedTerrainInfoForCell(state, *terrainIt->second);

    const int diagonalMultiplier = (std::abs(dx) == 1 && std::abs(dy) == 1) ? 14 : 10;
    if (runtimeObjectMovementMode(state, mover) == PathMovementMode::Air) {
        return diagonalMultiplier * 10;
    }
    return std::max(1, terrainInfo.cost * diagonalMultiplier);
}

RuntimeCellPoint toRuntimeCellPoint(const PathCell& cell) {
    return {cell.x, cell.y};
}

std::uint64_t runtimeMapQueryApproachContextHash(
    const std::string& purpose,
    const WorldObjectInstance& target,
    const std::vector<RuntimeCellPoint>& candidates) {
    std::uint64_t hash = runtimeStableHashString(purpose);
    runtimeStableHashMixString(hash, target.type);
    runtimeStableHashMix(hash, target.instanceId);
    runtimeStableHashMix(hash, target.x);
    runtimeStableHashMix(hash, target.y);
    for (const RuntimeCellPoint& candidate : candidates) {
        runtimeStableHashMix(hash, candidate.x);
        runtimeStableHashMix(hash, candidate.y);
    }
    return hash;
}

std::uint64_t runtimeRequesterStableHash(
    const WorldObjectInstance& object) {
    std::uint64_t hash = runtimeStableHashString("runtimeRequester");
    runtimeStableHashMix(hash, object.instanceId);
    runtimeStableHashMixString(hash, object.type);
    runtimeStableHashMix(hash, static_cast<int>(object.kind));
    return hash;
}

std::vector<RuntimeCellPoint> runtimeAlternateGoalCellsNear(
    const RuntimeCellPoint& goal,
    int radius) {
    std::vector<RuntimeCellPoint> cells;
    const int clampedRadius = std::clamp(radius, 0, 6);
    cells.reserve(
        static_cast<std::size_t>(
            (clampedRadius * 2 + 1) * (clampedRadius * 2 + 1)
        )
    );
    for (int dy = -clampedRadius; dy <= clampedRadius; ++dy) {
        for (int dx = -clampedRadius; dx <= clampedRadius; ++dx) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            cells.push_back({goal.x + dx, goal.y + dy});
        }
    }
    std::sort(cells.begin(), cells.end(), RuntimeCellPointLess{});
    return cells;
}

void applyRuntimeMapQueryApproachStats(RuntimeProductionHostState& state) {
    if (!state.pathQueueMapQueryApproachObserved) {
        return;
    }

    state.lastPathQueueStats.mapQueryApproachAvailable = true;
    state.lastPathQueueStats.mapQueryApproachPurpose =
        state.pathQueueMapQueryApproachPurpose;
    state.lastPathQueueStats.mapQueryApproachCandidates =
        state.pathQueueMapQueryApproachCandidates;
    state.lastPathQueueStats.mapQueryApproachSubmitted =
        state.pathQueueMapQueryApproachSubmitted;
    state.lastPathQueueStats.mapQueryApproachContextHash =
        state.pathQueueMapQueryApproachContextHash;
    state.lastPathQueueStats.mapQueryApproachRequests = std::max(
        state.lastPathQueueStats.mapQueryApproachRequests,
        state.pathQueueMapQueryApproachSubmitted
    );
}

void recordRuntimeMapQueryApproachContext(
    RuntimeProductionHostState& state,
    const std::string& purpose,
    const WorldObjectInstance& target,
    const std::vector<RuntimeCellPoint>& candidates,
    int submittedCount) {
    if (candidates.empty() && submittedCount <= 0) {
        return;
    }

    state.pathQueueMapQueryApproachObserved = true;
    state.pathQueueMapQueryApproachPurpose = purpose;
    state.pathQueueMapQueryApproachCandidates =
        static_cast<int>(candidates.size());
    state.pathQueueMapQueryApproachSubmitted = submittedCount;
    state.pathQueueMapQueryApproachContextHash =
        runtimeMapQueryApproachContextHash(purpose, target, candidates);
    applyRuntimeMapQueryApproachStats(state);
}

bool runtimeKirovBuildingBombProfile(
    const WorldObjectInstance& object,
    const WorldObjectInstance& target,
    const RuntimeWeaponProfile& profile) {
    if (!object.alive || object.health <= 0 || !object.airborne
        || object.kind != WorldObjectKind::Unit
        || toUpperAsciiLocal(trimAsciiLocal(object.type)) != "ZEP"
        || !target.alive || target.health <= 0
        || target.kind != WorldObjectKind::Structure || target.instanceId < 0
        || profile.weapon == nullptr || profile.projectile == nullptr) return false;
    const std::string weaponId = toUpperAsciiLocal(trimAsciiLocal(profile.weapon->id));
    return (weaponId == "BLIMPBOMB" || weaponId == "BLIMPBOMBE")
        && profile.projectile->vertical && !profile.projectile->inviso
        && !profile.projectile->imageIsNone
        && !trimAsciiLocal(profile.projectile->image).empty();
}

int runtimeMoveTargetSoftPenalty(
    const RuntimeGameSessionState& state,
    const std::unordered_map<int, const TerrainCell*>& terrainByCell,
    const std::unordered_map<int, int>& occupiedByCell,
    const RuntimeCellPoint& candidate) {
    const int key = runtimeCellKey(candidate.x, candidate.y);
    const auto terrainIt = terrainByCell.find(key);
    if (terrainIt == terrainByCell.end() || terrainIt->second == nullptr) {
        return 1200;
    }

    const RuntimeTerrainInfo terrainInfo =
        runtimeCachedTerrainInfoForCell(state, *terrainIt->second);
    int penalty = std::max(0, terrainInfo.cost - 8) * 12;
    if (terrainInfo.ramp) {
        penalty += 20;
    }
    if (terrainInfo.shore) {
        penalty += 90;
    }

    for (const RuntimeCellPoint& neighbor : runtimeNeighborsOf(candidate)) {
        const int neighborKey = runtimeCellKey(neighbor.x, neighbor.y);
        const auto neighborTerrainIt = terrainByCell.find(neighborKey);
        if (neighborTerrainIt == terrainByCell.end()
            || neighborTerrainIt->second == nullptr) {
            penalty += 120;
            continue;
        }

        const RuntimeTerrainInfo neighborInfo =
            runtimeCachedTerrainInfoForCell(state, *neighborTerrainIt->second);
        if (neighborInfo.cliff) {
            penalty += 900;
        } else if (!neighborInfo.passable) {
            penalty += 260;
        } else if (neighborInfo.water && !neighborInfo.bridge) {
            penalty += 180;
        } else if (neighborInfo.shore) {
            penalty += 90;
        }

        if (occupiedByCell.find(neighborKey) != occupiedByCell.end()) {
            penalty += 45;
        }
    }

    return penalty;
}

std::unordered_set<int> buildRuntimeReachableMoveCells(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& mover,
    const std::vector<RuntimeCellPoint>& starts,
    const std::unordered_map<int, const TerrainCell*>& terrainByCell,
    const std::unordered_map<int, int>& occupiedByCell,
    int allowedOccupiedObjectId) {
    std::unordered_set<int> reachable;
    std::deque<RuntimeCellPoint> frontier;
    reachable.reserve(std::min<std::size_t>(
        state.world.getTerrainCells().size(),
        20000U
    ));
    for (const RuntimeCellPoint& start : starts) {
        const int key = runtimeCellKey(start.x, start.y);
        if (key < 0 || reachable.find(key) != reachable.end()) {
            continue;
        }
        reachable.insert(key);
        frontier.push_back(start);
    }

    while (!frontier.empty()) {
        const RuntimeCellPoint current = frontier.front();
        frontier.pop_front();
        for (const RuntimeCellPoint& next : runtimeNeighborsOf(current)) {
            const int key = runtimeCellKey(next.x, next.y);
            if (key < 0 || reachable.find(key) != reachable.end()) {
                continue;
            }
            if (!runtimeCellTraversalCost(
                    state,
                    terrainByCell,
                    occupiedByCell,
                    current,
                    next,
                    mover,
                    allowedOccupiedObjectId
                ).has_value()) {
                continue;
            }
            reachable.insert(key);
            frontier.push_back(next);
        }
    }

    return reachable;
}

std::unordered_map<int, int> buildRuntimeMoveComponentByCell(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& mover,
    const std::unordered_map<int, const TerrainCell*>& terrainByCell,
    const std::unordered_map<int, int>& occupiedByCell) {
    RuntimePerfTraceScope plannerTrace("moveComponentConnectivity", state.tick);
    RuntimeBuildingDepartureReadOnlyQueryScope departureQueries(state, mover);
    const bool infantryQueries = mover.kind == WorldObjectKind::Infantry;
    RuntimeSubcellReadOnlyQueryScope occupancyQueries(state.world.getObjects(), infantryQueries,
        runtimeGroundPoseContext(state));
    RuntimePlannerInvisibleBuildingScope invisibleBuildings(state, infantryQueries);
    RuntimePlannerCellPassabilityScope passabilityQueries(
        state, mover, terrainByCell, occupiedByCell);
    RuntimePlannerLandPermissionScope landPermissions(state, mover);
    RuntimePlannerConnectivityKernel connectivity(state, mover, terrainByCell,
        occupiedByCell,runtimeComponentKernelReference(),&passabilityQueries);
    RuntimePlannerEmptyCellCensusScope emptyCells(state,(infantryQueries
        || (!runtimeComponentCrushAliasReference() && connectivity.queryLeaseEnabled()))
        && !runtimeComponentPassabilityReference() && !runtimeComponentKernelReference()
        && connectivity.precomputedMode()!=PathMovementMode::Air);
    std::unordered_map<int, int> componentByCell;
    componentByCell.reserve(terrainByCell.size());
    RuntimePlannerVisitedCellKeys visited(terrainByCell);
    int nextComponent = 1;

    for (const auto& [seedKey, seedTerrain] : terrainByCell) {
        if (seedTerrain == nullptr || seedKey < 0 || visited.contains(seedKey)) {
            continue;
        }
        const RuntimeCellPoint seed{seedTerrain->x, seedTerrain->y};
        if (!connectivity.seedIsPassable(seed)) {
            visited.insert(seedKey);
            continue;
        }

        const int component = nextComponent++;
        std::deque<RuntimeCellPoint> frontier;
        frontier.push_back(seed);
        visited.insert(seedKey);
        componentByCell[seedKey] = component;

        while (!frontier.empty()) {
            const RuntimeCellPoint current = frontier.front();
            frontier.pop_front();

            for (const RuntimeCellPoint& next : runtimeNeighborsOf(current)) {
                const int key = runtimeCellKey(next.x, next.y);
                if (key < 0 || visited.contains(key)) {
                    continue;
                }
                if (!connectivity.connects(current, next)) {
                    continue;
                }
                visited.insert(key);
                componentByCell[key] = component;
                frontier.push_back(next);
            }
        }
    }

    return componentByCell;
}

bool commitRuntimeInfantryMoveDestination(
    RuntimeGameSessionState& state,
    WorldObjectInstance& object,
    const RuntimeCellPoint& destination) {
    RuntimePerfTraceScope movePhaseTrace("moveSubcellCommit", state.tick);
    if (!runtimeInfantryUsesGroundSubcells(object)) {
        return true;
    }
    ensureRuntimeSubcellsInitialized(state);
    const auto reserved = state.subcells.reservations().find(
        object.instanceId
    );
    const RuntimeSubcellLocation expected =
        runtimeSubcellLocationForCell(state, destination);
    if (reserved == state.subcells.reservations().end()
        || reserved->second.destination.x != expected.x
        || reserved->second.destination.y != expected.y
        || reserved->second.destination.cell != expected.cell
        || reserved->second.destination.onBridge != expected.onBridge) {
        return false;
    }
    const bool stoppedPose = worldObjectHasStoppedGroundPose(object);
    const auto previousSubcellOffset = worldObjectSubCellOffset(object);
    const double previousBaseX = runtimeObjectRenderX(object);
    const double previousBaseY = runtimeObjectRenderY(object);
    const double previousLevel = worldObjectHasGroundRenderPose(object)
        ? object.renderLevel : double(object.level);
    const bool previousOnBridge = worldObjectHasGroundRenderPose(object)
        ? object.renderOnBridge : object.onBridge;
    const RuntimeSubcellCommitResult committed = state.subcells.commit(
        state.world.accessObjects(),
        state.world.getTerrainObjects(),
        object.instanceId,
        runtimeGateSubcellContext(
            state,
            &object,
            RuntimeGatePassageMode::Commit
        )
    );
    if (!committed.committed()) {
        return false;
    }
    const auto nextSubcellOffset = worldObjectSubCellOffset(object);
    if (stoppedPose || previousSubcellOffset.x != nextSubcellOffset.x
        || previousSubcellOffset.y != nextSubcellOffset.y) {
        // Commit selects the destination slot. Keep the old visible body,
        // including a just-completed step, until the new segment interpolates.
        object.hasRenderPosition = true;
        object.renderMoveActive = false;
        object.renderX = previousBaseX + previousSubcellOffset.x - nextSubcellOffset.x;
        object.renderY = previousBaseY + previousSubcellOffset.y - nextSubcellOffset.y;
        object.renderLevel = previousLevel;
        object.renderOnBridge = previousOnBridge;
    }
    const auto terrain = state.terrainByCell.find(object.cell);
    if (terrain != state.terrainByCell.end() && terrain->second != nullptr) {
        object.level = runtimeEffectiveTerrainLevel(*terrain->second);
    }
    invalidateRuntimeSubcellDynamicPathState(state);
    return true;
}

bool runtimeInfantryReservationMatches(
    const RuntimeGameSessionState& state,
    int objectId,
    const RuntimeCellPoint& destination) {
    const auto reserved = state.subcells.reservations().find(objectId);
    if (reserved == state.subcells.reservations().end()) {
        return false;
    }
    const RuntimeSubcellLocation expected =
        runtimeSubcellLocationForCell(state, destination);
    return reserved->second.destination.x == expected.x
        && reserved->second.destination.y == expected.y
        && reserved->second.destination.cell == expected.cell
        && reserved->second.destination.onBridge == expected.onBridge;
}

void prepareRuntimeInfantryStepReservations(RuntimeGameSessionState& state) {
    RuntimePerfTraceScope trace("prepareRuntimeInfantryStepReservations", state.tick);
    ensureRuntimeSubcellsInitialized(state);
    const std::map<int, RuntimeSubcellReservation> previousReservations =
        state.subcells.reservations();
    std::vector<RuntimeSubcellMoveRequest> requests;
    std::unordered_set<int> requestedMovers;
    requests.reserve(state.behaviors.size());
    requestedMovers.reserve(state.behaviors.size());
    for (const auto& [objectId, behavior] : state.behaviors) {
        if ((behavior.kind != RuntimeBehaviorKind::Move
                && behavior.kind != RuntimeBehaviorKind::Attack)
            // A cooldown of one finishes in this tick; the move/attack
            // handler immediately starts its next segment. Reserve for that
            // continuation now instead of inserting one idle tick per cell.
            || behavior.moveCooldownTicks > 1
            || behavior.pathRequestPending
            || behavior.path.empty()) {
            continue;
        }
        const WorldObjectInstance* object = findObjectById(state, objectId);
        if (object == nullptr || !runtimeInfantryUsesGroundSubcells(*object)
            || runtimeInfantryRequiresManualUndeploy(state, *object)) {
            continue;
        }
        if ((behavior.kind == RuntimeBehaviorKind::Move
                && runtimeMoveWillCompleteBeforeSubcellStep(
                    state,
                    *object,
                    behavior
                ))
            || (behavior.kind == RuntimeBehaviorKind::Attack
                && !runtimeAttackWillUseSubcellStep(
                    state,
                    *object,
                    behavior
                ))) {
            continue;
        }
        if (behavior.pendingAllowedOccupiedObjectId >= 0
            && runtimeCellIsAllowedOccupiedStructureFootprint(
                state,
                behavior.path.front(),
                behavior.pendingAllowedOccupiedObjectId,
                object
            )) {
            // Engineer/occupier entry deliberately crosses a structure's
            // hard footprint and is consumed by the entry lifecycle.
            continue;
        }
        requests.push_back({
            objectId,
            runtimeSubcellLocationForCell(state, behavior.path.front())
        });
        requestedMovers.insert(objectId);
    }

    std::vector<int> staleReservations;
    for (const auto& [objectId, reservation] :
            state.subcells.reservations()) {
        (void)reservation;
        if (requestedMovers.find(objectId) == requestedMovers.end()) {
            staleReservations.push_back(objectId);
        }
    }
    for (int objectId : staleReservations) {
        state.subcells.release(objectId);
    }
    if (!requests.empty()) {
        (void)state.subcells.reserveBatch(
            state.world.getObjects(),
            state.world.getTerrainObjects(),
            requests,
            runtimeGateSubcellContext(state)
        );
    }
    if (!runtimeSubcellReservationsEqual(
            previousReservations,
            state.subcells.reservations()
        )) {
        invalidateRuntimeSubcellDynamicPathState(state);
    }
}

void refreshRuntimeWallConnectionMasks(RuntimeGameSessionState& state) {
    std::unordered_map<int, WorldObjectInstance*> wallsByCell;
    wallsByCell.reserve(state.world.getObjects().size());
    for (WorldObjectInstance& object : state.world.accessObjects()) {
        object.wallConnectionMask = 0;
        if (!object.alive || object.kind != WorldObjectKind::Structure) {
            continue;
        }
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, object.type);
        if (building == nullptr || !building->wall) {
            continue;
        }
        const int key = runtimeCellKey(object.x, object.y);
        if (key >= 0) {
            wallsByCell[key] = &object;
        }
    }

    struct WallDirection {
        int dx;
        int dy;
        int bit;
    };
    static constexpr std::array<WallDirection, 4> Directions{{
        {0, -1, 1},
        {1, 0, 2},
        {0, 1, 4},
        {-1, 0, 8}
    }};
    for (const auto& [cellKey, wall] : wallsByCell) {
        (void)cellKey;
        if (wall == nullptr) {
            continue;
        }
        const std::string wallType = toUpperAsciiLocal(wall->type);
        const std::string wallOwner = toUpperAsciiLocal(wall->owner);
        for (const WallDirection& direction : Directions) {
            const auto neighborIt = wallsByCell.find(runtimeCellKey(
                wall->x + direction.dx,
                wall->y + direction.dy
            ));
            if (neighborIt == wallsByCell.end()
                || neighborIt->second == nullptr
                || toUpperAsciiLocal(neighborIt->second->type) != wallType
                || toUpperAsciiLocal(neighborIt->second->owner) != wallOwner) {
                continue;
            }
            wall->wallConnectionMask |= direction.bit;
        }
    }
}

void invalidateRuntimeObjectProjectionCache(RuntimeProductionHostState& state) {
    state.projectedObjectsCacheValid = false;
}

bool runtimeSetObjectCloaked(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object,
    bool cloaked,
    const std::string& reason) {
    if (object.cloaked == cloaked) {
        return false;
    }
    object.cloaked = cloaked;
    if (cloaked
        && !trimAsciiLocal(state.economy.owner).empty()
        && object.owner != state.economy.owner
        && !runtimeOwnersAreAllied(
            state,
            state.economy.owner,
            object.owner
        )) {
        state.selectedObjectIds.erase(
            std::remove(
                state.selectedObjectIds.begin(),
                state.selectedObjectIds.end(),
                object.instanceId
            ),
            state.selectedObjectIds.end()
        );
    }
    invalidateRuntimeObjectProjectionCache(state);
    state.radarTerrainKey.clear();
    state.repaintRequested = true;

    RuntimeReplayEventSnapshot event;
    event.kind = cloaked ? "ObjectCloaked" : "ObjectDecloaked";
    event.objectId = object.instanceId;
    event.reason = reason;
    event.renderIntentId = cloaked
        ? "cloak:hidden"
        : "cloak:revealed";
    event.renderIntentHash =
        runtimeStableHashString(event.renderIntentId);
    recordRuntimeReplayEvent(state, std::move(event));
    return true;
}

bool runtimeSetObjectSubmerged(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object,
    bool submerged,
    const std::string& reason) {
    if (object.submerged == submerged) {
        return false;
    }
    object.submerged = submerged;
    invalidateRuntimeObjectProjectionCache(state);
    state.radarTerrainKey.clear();
    state.repaintRequested = true;

    RuntimeReplayEventSnapshot event;
    event.kind = submerged ? "ObjectSubmerged" : "ObjectSurfaced";
    event.objectId = object.instanceId;
    event.reason = reason;
    event.renderIntentId = submerged
        ? "submerge:underwater"
        : "submerge:surface";
    event.renderIntentHash =
        runtimeStableHashString(event.renderIntentId);
    recordRuntimeReplayEvent(state, std::move(event));
    return true;
}

bool runtimeDecloakObject(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object,
    const std::string& reason) {
    object.cloakCooldownTicks = runtimeObjectCanCloak(state, object)
        ? runtimeObjectCloakTransitionTicks(state, object)
        : 0;
    return runtimeSetObjectCloaked(state, object, false, reason);
}

bool runtimeCountryIsYuri(const std::string& country) {
    const std::string key = toUpperAsciiLocal(trimAsciiLocal(country));
    return key == "YURI" || key == "YURICOUNTRY";
}

bool runtimeCountryIsSoviet(const std::string& country) {
    const std::string key = toUpperAsciiLocal(trimAsciiLocal(country));
    return key == "RUSSIANS"
        || key == "CONFEDERATION"
        || key == "AFRICANS"
        || key == "ARABS"
        || key == "SOVIET";
}

std::string runtimeConstructionYardForCountry(const std::string& country) {
    if (runtimeCountryIsYuri(country)) {
        return "YACNST";
    }
    if (runtimeCountryIsSoviet(country)) {
        return "NACNST";
    }
    return "GACNST";
}

std::optional<std::string> runtimeStartingUnitModeOverride(
    const RuntimeGameSessionState& state,
    const UnitType& unit,
    const std::string& key) {
    if (!state.skirmishModeRulesLoaded) {
        return std::nullopt;
    }
    const IniFile::Section* section = runtimeIniSectionNoCase(
        state.skirmishModeRules,
        unit.id
    );
    return runtimeIniSectionOptionalValueNoCase(section, key);
}

std::string runtimeStartingUnitEffectiveList(
    const RuntimeGameSessionState& state,
    const UnitType& unit,
    const std::string& key,
    const std::string& baseValue) {
    const std::optional<std::string> overrideValue =
        runtimeStartingUnitModeOverride(state, unit, key);
    return overrideValue.has_value() ? *overrideValue : baseValue;
}

bool runtimeUnitAllowedToStartInMultiplayer(
    const RuntimeGameSessionState& state,
    const UnitType& unit) {
    const std::optional<std::string> overrideValue =
        runtimeStartingUnitModeOverride(
            state,
            unit,
            "AllowedToStartInMultiplayer"
        );
    return overrideValue.has_value()
        ? parseRuntimeBool(*overrideValue)
        : unit.allowedToStartInMultiplayer;
}

bool runtimeStartingUnitAllowedForCountry(
    const RuntimeGameSessionState& state,
    const UnitType& unit,
    const std::string& country) {
    int techLevel = unit.techLevel;
    if (const auto value = runtimeStartingUnitModeOverride(state, unit, "TechLevel"))
        (void)parseRuntimeInt(*value, techLevel);
    if (!runtimeUnitAllowedToStartInMultiplayer(state, unit)
        || techLevel < 0 || techLevel > std::clamp(state.config.techLevel, 1, 10)
        || runtimeUnitTypeIsMcv(state, unit)) {
        return false;
    }
    const std::string owner = runtimeStartingUnitEffectiveList(
        state,
        unit,
        "Owner",
        unit.owner
    );
    if (trimAsciiLocal(owner).empty()) {
        return false;
    }
    const std::string requiredHouses = runtimeStartingUnitEffectiveList(
        state,
        unit,
        "RequiredHouses",
        unit.requiredHouses
    );
    const std::string forbiddenHouses = runtimeStartingUnitEffectiveList(
        state,
        unit,
        "ForbiddenHouses",
        unit.forbiddenHouses
    );
    return evaluateTechTreeCountryFilter(
        state.rules,
        country,
        owner,
        requiredHouses,
        forbiddenHouses
    ).visible;
}

int runtimeDifficultyAdjustedStartingUnits(
    const RuntimeGameSessionState& state,
    const std::string& owner,
    int requestedCount) {
    const int count = std::clamp(requestedCount, 0, 50);
    const std::string difficulty = toUpperAsciiLocal(
        runtimeSkirmishDifficultyForOwner(state, owner)
    );
    if (difficulty == "EASY") {
        return count <= 0 ? 0 : std::max(1, (count * 3 + 3) / 4);
    }
    if (difficulty == "HARD" || difficulty == "BRUTAL") {
        return std::min(50, count + std::max(1, count / 3));
    }
    return count;
}

double runtimeDifficultyHealthScale(
    const RuntimeGameSessionState& state,
    const std::string& owner) {
    const std::string difficulty = toUpperAsciiLocal(
        runtimeSkirmishDifficultyForOwner(state, owner)
    );
    if (difficulty == "EASY") {
        return 0.85;
    }
    if (difficulty == "HARD" || difficulty == "BRUTAL") {
        return 1.15;
    }
    return 1.0;
}

std::string runtimeBuildKindName(RuntimeBuildKind kind) {
    switch (kind) {
    case RuntimeBuildKind::Building:
        return "building";
    case RuntimeBuildKind::Defense:
        return "defense";
    case RuntimeBuildKind::Infantry:
        return "infantry";
    case RuntimeBuildKind::Unit:
        return "unit";
    }
    return "item";
}

RuntimeBuildKind runtimeBuildKindFromName(const std::string& name) {
    const std::string lower = toLowerAsciiLocal(trimAsciiLocal(name));
    if (lower == "defense" || lower == "def") {
        return RuntimeBuildKind::Defense;
    }
    if (lower == "infantry" || lower == "inf") {
        return RuntimeBuildKind::Infantry;
    }
    if (lower == "unit" || lower == "vehicle" || lower == "veh") {
        return RuntimeBuildKind::Unit;
    }
    return RuntimeBuildKind::Building;
}

RuntimeBuildKind runtimeBuildKindFromTechTreeKind(const std::string& kind) {
    const std::string lower = toLowerAsciiLocal(trimAsciiLocal(kind));
    if (lower == "defense") {
        return RuntimeBuildKind::Defense;
    }
    if (lower == "infantry") {
        return RuntimeBuildKind::Infantry;
    }
    if (lower == "vehicle" || lower == "aircraft") {
        return RuntimeBuildKind::Unit;
    }
    return RuntimeBuildKind::Building;
}

bool runtimeTechTreeNodeAllowedForRuntime(
    const RuntimeGameSessionState& state,
    const TechTreeNode& node) {
    // Unholy Alliance combines the three ordinary faction trees. Dynamic
    // factory and prerequisite checks still control each construction step.
    return node.buildableByRules
        || (runtimeIsUnholyAllianceMode(state)
            && node.requiredHousesAllowed && node.forbiddenHousesAllowed
            && node.techAllowed && node.hasPrerequisite && node.cost >= 0);
}

void addRuntimeBuildCatalogItem(
    RuntimeGameSessionState& state,
    RuntimeBuildKind kind,
    const std::string& id,
    const TechTreeNode* techNode) {
    const auto duplicateIt = std::find_if(
        state.economy.catalog.begin(),
        state.economy.catalog.end(),
        [kind, &id](const RuntimeBuildCatalogItem& item) {
            return item.kind == kind
                && toUpperAsciiLocal(item.typeId) == toUpperAsciiLocal(id);
        }
    );
    if (duplicateIt != state.economy.catalog.end()) {
        return;
    }

    RuntimeBuildCatalogItem item;
    item.kind = kind;
    item.typeId = id;
    item.techTreeKind =
        techNode == nullptr ? runtimeBuildKindName(kind) : techNode->kind;
    item.techTreeAllowed =
        techNode == nullptr || runtimeTechTreeNodeAllowedForRuntime(state, *techNode);
    item.techTreeBlockedReason =
        techNode == nullptr ? "" : techNode->blockedReason;

    if (kind == RuntimeBuildKind::Building || kind == RuntimeBuildKind::Defense) {
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, id);
        if (building == nullptr) {
            return;
        }
        item.label = building->name.empty() ? building->id : building->name;
        item.owner = building->owner;
        item.requiredHouses = building->requiredHouses;
        item.forbiddenHouses = building->forbiddenHouses;
        item.techLevel = building->techLevel;
        item.buildLimit = building->buildLimit;
        item.cost = std::max(0, building->cost);
        item.powerDelta = building->power;
        item.prerequisite = building->prerequisite;
        item.prerequisiteOverride = building->prerequisiteOverride;
        item.requiredFactory = "BuildingType";
        item.waterBound = building->waterBound;
        item.naval = building->naval;
        item.wall = building->wall;
    } else {
        const UnitType* unit = findRuntimeUnitTypeById(state.rules, id);
        if (unit == nullptr) {
            return;
        }
        item.label = unit->name.empty() ? unit->id : unit->name;
        item.owner = unit->owner;
        item.requiredHouses = unit->requiredHouses;
        item.forbiddenHouses = unit->forbiddenHouses;
        item.techLevel = unit->techLevel;
        item.buildLimit = unit->buildLimit;
        item.cost = std::max(0, unit->cost);
        item.prerequisite = unit->prerequisite;
        item.prerequisiteOverride = unit->prerequisiteOverride;
        item.requiredFactory =
            techNode == nullptr
                ? (kind == RuntimeBuildKind::Infantry ? "InfantryType" : "UnitType")
                : techNode->requiredFactory;
        item.waterBound = unit->waterBound;
        item.naval = runtimeUnitTypeLooksNaval(*unit);
    }

    if (techNode != nullptr) {
        item.owner = techNode->owner;
        item.requiredHouses = techNode->requiredHouses;
        item.forbiddenHouses = techNode->forbiddenHouses;
        item.techLevel = techNode->techLevel;
        item.prerequisite = techNode->prerequisite;
        item.prerequisiteOverride = techNode->prerequisiteOverride;
        item.requiredFactory = techNode->requiredFactory;
    }

    // PadAircraft is a physical delivery contract, independent of whether
    // the authored type lives in AircraftTypes or VehicleTypes.  Tech-tree
    // classification must not route a listed VTOL back through a land
    // factory after the production matcher has reserved an aircraft pad.
    if (kind == RuntimeBuildKind::Unit
        && state.rules.isPadAircraft(item.typeId)) {
        item.requiredFactory = "AircraftType";
    }

    item.buildTicks = runtimeBaseBuildTimeTicks(state, item);
    item.cost = runtimeAdjustedFactoryPlantCost(
        state,
        state.economy.owner,
        item,
        item.cost
    );
    state.economy.catalog.push_back(std::move(item));
}

const TechTreeNode* runtimeFindTechTreeNode(
    const TechTreeReport& report,
    const std::string& id) {
    const std::string wanted = toUpperAsciiLocal(id);
    for (const TechTreeNode& node : report.nodes) {
        if (toUpperAsciiLocal(node.id) == wanted) {
            return &node;
        }
    }
    return nullptr;
}

bool runtimeTechTreeNodeCanEnterCatalog(
    const RuntimeGameSessionState& state,
    const TechTreeNode& node) {
    return runtimeTechTreeNodeAllowedForRuntime(state, node) && node.cost > 0;
}

int runtimeBasePlanningSideForCountry(const std::string& countryId) {
    const std::string country =
        toUpperAsciiLocal(trimAsciiLocal(countryId));
    if (country == "YURI" || country == "YURICOUNTRY") {
        return 2;
    }
    if (country == "RUSSIANS"
        || country == "CONFEDERATION"
        || country == "AFRICANS"
        || country == "ARABS"
        || country == "SOVIET"
        || country == "SOVIETS") {
        return 1;
    }
    if (country == "AMERICANS"
        || country == "AMERICA"
        || country == "USA"
        || country == "USTATES"
        || country == "BRITISH"
        || country == "UKINGDOM"
        || country == "UNITEDKINGDOM"
        || country == "FRENCH"
        || country == "FRANCE"
        || country == "GERMANS"
        || country == "GERMANY"
        || country == "ALLIANCE"
        || country == "KOREA"
        || country == "ALLIED"
        || country == "ALLIES") {
        return 0;
    }
    return -1;
}

RuntimeBuildKind runtimeBuildKindForBuildingType(
    const BuildingType& building) {
    const std::string buildCat = toUpperAsciiLocal(building.buildCat);
    if (buildCat == "COMBAT"
        && (!building.primaryWeapon.empty()
            || !building.secondaryWeapon.empty()
            || building.power < 0)) {
        return RuntimeBuildKind::Defense;
    }
    return RuntimeBuildKind::Building;
}

void addRuntimeTechTreeBuildCatalog(RuntimeGameSessionState& state) {
    const std::string playerCountry =
        runtimeCountryForOwner(state, state.economy.owner);
    state.techTree = analyzeTechTree(state.rules, playerCountry);
    state.techTreeLoaded = true;

    const std::string owner = toUpperAsciiLocal(playerCountry);
    const bool yuriOwner = owner == "YURI" || owner == "YURICOUNTRY";
    const bool sovietOwner =
        owner == "RUSSIANS"
        || owner == "CONFEDERATION"
        || owner == "AFRICANS"
        || owner == "ARABS"
        || owner == "SOVIET";
    std::vector<std::string> preferredOrder;
    if (yuriOwner) {
        preferredOrder = {
            "YAPOWR", "YAREFN", "YABRCK", "YAWEAP", "NAPSIS", "YATECH",
            "YAGRND", "YAYARD", "YAGGUN", "YAPSYT", "YAGNTC",
            "INIT", "ENGINEER", "BRUTE", "VIRUS", "YURI", "YURIPR",
            "LTNK", "YTNK", "TELE", "MIND", "DISK", "SMIN", "PCV"
        };
    } else if (sovietOwner) {
        preferredOrder = {
            "NAPOWR", "NAREFN", "NAHAND", "NAWEAP", "NARADR", "NATECH",
            "NANRCT", "NADEPT", "NAYARD", "NALASR", "NASAM", "TESLA",
            "E2", "FLAKT", "ENGINEER", "DOG", "SHK", "IVAN", "TERROR",
            "HTNK", "HTK", "V3", "APOC", "HARV", "SMCV"
        };
    } else {
        preferredOrder = {
            "GAPOWR", "GAREFN", "GAPILE", "GAWEAP", "GAAIRC", "AMRADR",
            "GAYARD", "GADEPT", "GATECH", "GAOREP", "GAWALL", "GAPILL",
            "NASAM", "ATESLA", "GAGAP", "E1", "ENGINEER", "GGI", "ADOG",
            "JUMPJET", "SPY", "TANY", "CMIN", "MTNK", "FV", "SREF",
            "MGTK", "AMCV"
        };
    }

    for (const std::string& id : preferredOrder) {
        const TechTreeNode* node = runtimeFindTechTreeNode(state.techTree, id);
        if (node == nullptr || !runtimeTechTreeNodeCanEnterCatalog(state, *node)) {
            continue;
        }
        addRuntimeBuildCatalogItem(
            state,
            runtimeBuildKindFromTechTreeKind(node->kind),
            node->id,
            node
        );
    }

    for (const TechTreeNode& node : state.techTree.nodes) {
        if (!runtimeTechTreeNodeCanEnterCatalog(state, node)) {
            continue;
        }
        addRuntimeBuildCatalogItem(
            state,
            runtimeBuildKindFromTechTreeKind(node.kind),
            node.id,
            &node
        );
    }
}

int addRuntimeSecretLabBuildCatalog(RuntimeGameSessionState& state) {
    int added = 0;
    const std::string localOwner = runtimeRepairDepotCanonicalOwnerId(
        state,
        state.economy.owner
    );
    const std::vector<RuntimeSpecialBuildingUnlock> unlocks =
        RuntimeSpecialBuildingSystem::secretLabUnlocks(
            makeRuntimeSpecialBuildingContext(state)
        );
    for (const RuntimeSpecialBuildingUnlock& unlock : unlocks) {
        if (runtimeRepairDepotCanonicalOwnerId(state, unlock.owner)
            != localOwner) {
            continue;
        }
        const std::size_t before = state.economy.catalog.size();
        switch (unlock.kind) {
        case RuntimeSpecialBuildingUnlockKind::Infantry:
            addRuntimeBuildCatalogItem(
                state,
                RuntimeBuildKind::Infantry,
                unlock.typeId
            );
            break;
        case RuntimeSpecialBuildingUnlockKind::Unit:
            addRuntimeBuildCatalogItem(
                state,
                RuntimeBuildKind::Unit,
                unlock.typeId
            );
            break;
        case RuntimeSpecialBuildingUnlockKind::Building: {
            const BuildingType* building =
                findRuntimeBuildingTypeById(state.rules, unlock.typeId);
            if (building != nullptr) {
                addRuntimeBuildCatalogItem(
                    state,
                    runtimeBuildKindForBuildingType(*building),
                    unlock.typeId
                );
            }
            break;
        }
        }
        if (state.economy.catalog.size() > before) {
            state.economy.catalog.back().secretLabInjected = true;
            ++added;
        }
    }
    return added;
}

void addRuntimeModeOverrideBuildCatalog(RuntimeGameSessionState& state) {
    for (const std::string& sectionName :
            state.skirmishModeRules.getSectionNames()) {
        if (const BuildingType* building =
                findRuntimeBuildingTypeById(state.rules, sectionName)) {
            if (building->cost > 0 && !building->buildCat.empty()) {
                addRuntimeBuildCatalogItem(
                    state,
                    runtimeBuildKindForBuildingType(*building),
                    building->id
                );
            }
            continue;
        }
        if (const UnitType* unit =
                findRuntimeUnitTypeById(state.rules, sectionName)) {
            if (unit->cost > 0) {
                addRuntimeBuildCatalogItem(
                    state,
                    runtimeBuildKindForUnitTypeId(state.rules, unit->id),
                    unit->id
                );
            }
        }
    }
}

void initializeRuntimeHumanHouseAuthorities(RuntimeProductionHostState& state) {
    state.humanHouseAuthorities.clear();
    state.humanHouseScopeActive = false;
    state.remoteHumanHouseScopeActive = false;
    if (state.campaignMode) {
        return;
    }

    const std::string localOwnerKey =
        runtimeCanonicalHumanHouseOwner(state.economy.owner);
    for (std::size_t slotIndex = 0;
        slotIndex < state.config.playerSlots.size();
        ++slotIndex) {
        const RuntimeConfig::PlayerSlot& slot =
            state.config.playerSlots[slotIndex];
        if (!slot.enabled || !slot.human) {
            continue;
        }
        RuntimeHumanHouseAuthority authority;
        authority.slotIndex = slotIndex;
        authority.owner = runtimeSkirmishOwnerForSlot(slotIndex);
        authority.canonicalOwner =
            runtimeCanonicalHumanHouseOwner(authority.owner);
        authority.country = runtimeCountryForOwner(state, authority.owner);
        authority.localFacade = authority.canonicalOwner == localOwnerKey;
        if (!authority.localFacade) {
            RuntimeEconomyState economy;
            initializeRuntimeLocalProductionLanes(economy);
            economy.owner = authority.owner;
            economy.techLevel = std::clamp(state.config.techLevel, 1, 10);
            economy.credits = std::clamp(
                state.config.startingCredits,
                0,
                runtimeMaximumCreditBalance
            );
            economy.status = "remote human economy initializing";
            authority.remoteEconomy.emplace(std::move(economy));
            authority.remoteTechTree.emplace();
        }
        state.computerAiByOwner.erase(authority.canonicalOwner);
        state.humanHouseAuthorities.push_back(std::move(authority));
    }
    std::sort(
        state.humanHouseAuthorities.begin(),
        state.humanHouseAuthorities.end(),
        [](const RuntimeHumanHouseAuthority& left,
           const RuntimeHumanHouseAuthority& right) {
            return std::tie(left.canonicalOwner, left.slotIndex)
                < std::tie(right.canonicalOwner, right.slotIndex);
        }
    );

    for (RuntimeHumanHouseAuthority& authority :
            state.humanHouseAuthorities) {
        if (authority.localFacade) {
            continue;
        }
        RuntimeHumanHouseScope scope(state, authority.owner);
        if (!scope) {
            continue;
        }
        addRuntimeTechTreeBuildCatalog(state);
        (void)addRuntimeSecretLabBuildCatalog(state);
        loadAndApplyRuntimeSkirmishModeRules(state);
        applyRuntimeSuperweaponCatalogOption(state);
        initializeRuntimeLimitedBuildHistory(state);
        refreshRuntimeEconomyMetricsForCurrentOwner(state);
        (void)refreshRuntimeFactoryPlantCatalog(state);
        state.economy.status =
            "economy ready for " + state.economy.owner
            + " (" + authority.country + ") tech nodes "
            + std::to_string(state.techTree.buildableNodes)
            + "/" + std::to_string(state.techTree.totalNodes);
    }
}

int nextRuntimeObjectInstanceId(const RuntimeGameSessionState& state) {
    int maxId = 0;
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        maxId = std::max(maxId, object.instanceId);
    }
    return maxId + 1;
}

std::unordered_set<int> runtimeBuildingRubblePlacementCells(
    const RuntimeGameSessionState& state) {
    std::unordered_set<int> cells;
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (object.kind != WorldObjectKind::Structure || object.alive || !object.rubble) {
            continue;
        }
        for (const RuntimeCellPoint& cell : runtimeStructureFootprintCellsForObject(state, object)) {
            const int key = runtimeCellKey(cell.x, cell.y);
            if (key >= 0) {
                cells.insert(key);
            }
        }
    }
    return cells;
}

bool runtimeCellCanPlaceBuildingFast(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& cell,
    const std::unordered_map<int, int>& occupiedByCell,
    const std::string& placementOwner,
    int ignoredObjectId,
    const std::unordered_set<int>* rubbleCellsOverride) {
    if (item.kind != RuntimeBuildKind::Building
        && item.kind != RuntimeBuildKind::Defense) {
        return false;
    }

    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForBuildItem(state, item);
    const std::vector<RuntimeCellPoint> footprintCells =
        runtimeStructureFootprintCells(cell, footprint);
    std::unordered_set<int> generatedRubbleCells;
    if (rubbleCellsOverride == nullptr) {
        generatedRubbleCells = runtimeBuildingRubblePlacementCells(state);
        rubbleCellsOverride = &generatedRubbleCells;
    }
    const auto committedCells=runtimeGroundMoveSegmentPlacementCells(state,ignoredObjectId);
    int baseLevel = std::numeric_limits<int>::min();
    const auto anchorIt = state.terrainByCell.find(runtimeCellKey(cell.x, cell.y));
    if (anchorIt != state.terrainByCell.end() && anchorIt->second != nullptr) {
        baseLevel = anchorIt->second->level;
    }

    for (const RuntimeCellPoint& current : footprintCells) {
        const int key = runtimeCellKey(current.x, current.y);
        const auto terrainIt = state.terrainByCell.find(key);
        if (terrainIt == state.terrainByCell.end()
            || terrainIt->second == nullptr) {
            return false;
        }

        const TerrainCell& terrain = *terrainIt->second;
        if (state.visionEnabled
            && !state.vision.isCellExploredBy(
                placementOwner.empty() ? state.economy.owner : placementOwner,
                current.x, current.y
            )) {
            return false;
        }
        if (baseLevel == std::numeric_limits<int>::min()) {
            baseLevel = terrain.level;
        }
        if (occupiedByCell.find(key) != occupiedByCell.end() || committedCells.contains(key) || rubbleCellsOverride->contains(key)) {
            return false;
        }
        if (runtimeResourceOverlayBlocksPlacement(state, terrain)) {
            return false;
        }
        if (terrain.hasOverlay
            && !runtimeOverlayLooksBridge(terrain)
            && !terrain.overlayIsOre
            && !terrain.overlayIsGem) {
            return false;
        }

        const RuntimeTerrainInfo info =
            runtimeCachedTerrainInfoForCell(state, terrain);
        // Beach TMP subtiles contain exposed shore, not a water foundation.
        // Authored fully submerged shore subtiles are already classified as water.
        const bool buildCellIsWater = info.water && !info.shore;
        if (item.waterBound) {
            if (!buildCellIsWater) {
                return false;
            }
        } else if (info.water || info.shore || info.cliff) {
            return false;
        }
        if (terrain.level != baseLevel) {
            return false;
        }
    }

    return true;
}

bool runtimeCellCanPlaceBuilding(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item,
    const RuntimeCellPoint& cell,
    int ignoredObjectId,
    const std::unordered_map<int, int>* occupiedByCellOverride,
    const std::string& placementOwner,
    const std::unordered_set<int>* rubbleCellsOverride) {
    if (occupiedByCellOverride != nullptr) {
        return runtimeCellCanPlaceBuildingFast(
            state,
            item,
            cell,
            *occupiedByCellOverride,
            placementOwner,
            ignoredObjectId,
            rubbleCellsOverride
        );
    }

    const std::unordered_map<int, int> occupiedByCell =
        buildRuntimeOccupancyLookup(state, ignoredObjectId);
    return runtimeCellCanPlaceBuildingFast(
        state,
        item,
        cell,
        occupiedByCell,
        placementOwner,
        ignoredObjectId,
        rubbleCellsOverride
    );
}

void applyRuntimePlacementRenderAnchor(
    RuntimeGameSessionState& state,
    WorldObjectInstance& object,
    RuntimeBuildKind kind,
    const RuntimeCellPoint& topLeftCell) {
    if (kind != RuntimeBuildKind::Building
        && kind != RuntimeBuildKind::Defense) {
        return;
    }

    (void)state;
    // RuntimeMapRenderer treats structure render coordinates as the footprint
    // top-left and derives the rear-cell draw anchor from the foundation.
    // Passing the rear cell here offsets newly placed structures twice.
    object.hasRenderPosition = true;
    object.renderX = static_cast<double>(topLeftCell.x);
    object.renderY = static_cast<double>(topLeftCell.y);
    object.renderMoveActive = false;
    object.renderLevel = static_cast<double>(object.level);
    object.renderOnBridge = object.onBridge;
}

void applyRuntimePlacementObjectPose(
    RuntimeGameSessionState& state,
    WorldObjectInstance& object,
    RuntimeBuildKind kind,
    const RuntimeCellPoint& topLeftCell) {
    object.x = topLeftCell.x;
    object.y = topLeftCell.y;
    object.cell = runtimeCellKey(topLeftCell.x, topLeftCell.y);
    object.level = terrainLevelAtRuntimeCell(
        state,
        topLeftCell.x,
        topLeftCell.y
    );
    object.onBridge = runtimeCellIsBridge(
        state,
        topLeftCell.x,
        topLeftCell.y
    );
    applyRuntimePlacementRenderAnchor(state, object, kind, topLeftCell);
}

int runtimeInitialProducedFacing(
    const RuntimeGameSessionState& state,
    RuntimeBuildKind kind,
    const std::string& typeId) {
    if (kind != RuntimeBuildKind::Building
        && kind != RuntimeBuildKind::Defense) {
        return 0;
    }

    const BuildingType* building =
        findRuntimeBuildingTypeById(state.rules, typeId);
    // Match the terminal stock SHP pose to this renderer's voxel projection.
    // LASER/SAM/GTGCANTUR settle at the intermediate north-east heading;
    // FLAKTUR and YAGGUN settle at the full north-east heading. Do not apply
    // this creation-only pose calibration to map-authored or restored facings.
    if (building == nullptr || (!building->turret && building->turretAnim.empty())) return 0;
    const std::string turret = toLowerAsciiLocal(building->turretAnim);
    if (turret == "gtgcantur" || turret == "laser" || turret == "sam") return 16;
    return 32;
}

bool runtimeAircraftPadBuildingHasCompatibleType(
    const RulesDatabase& rules,
    const std::string& buildingTypeId) {
    const std::string buildingKey = toUpperAsciiLocal(
        trimAsciiLocal(buildingTypeId)
    );
    if (buildingKey.empty()) {
        return false;
    }
    for (const std::string& typeId : rules.getPadAircraft()) {
        const UnitType* unit = findRuntimePadAircraftUnitType(
            rules,
            typeId
        );
        if (unit == nullptr) {
            continue;
        }
        const std::vector<std::string> dockTypes = splitRuntimeTokenList(
            unit->dock
        );
        if (dockTypes.empty()
            || std::any_of(
                dockTypes.begin(),
                dockTypes.end(),
                [&buildingKey](const std::string& dockType) {
                    return toUpperAsciiLocal(trimAsciiLocal(dockType))
                        == buildingKey;
                }
            )) {
            return true;
        }
    }
    return false;
}

std::map<std::string, std::size_t>
runtimeAircraftPadSlotCapacityByOwner(
    const RuntimeGameSessionState& state) {
    std::map<std::string, std::size_t> capacityByOwner;
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive
            || object.health == 0
            || object.rubble
            || object.kind != WorldObjectKind::Structure) {
            continue;
        }
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, object.type);
        if (building == nullptr
            || building->numberOfDocks <= 0
            || !runtimeProductionFactorySupportsLane(
                *building,
                RuntimeProductionLane::Aircraft
            )
            || !runtimeAircraftPadBuildingHasCompatibleType(
                state.rules,
                object.type
            )) {
            continue;
        }
        const std::string owner = runtimeRepairDepotCanonicalOwnerId(
            state,
            object.owner
        );
        if (owner.empty()) {
            continue;
        }
        std::size_t& capacity = capacityByOwner[owner];
        const std::size_t dockCount = static_cast<std::size_t>(
            building->numberOfDocks
        );
        if (capacity > runtimeAircraftProductionMaximumSlots
            || dockCount
                > runtimeAircraftProductionMaximumSlots - capacity) {
            capacity = runtimeAircraftProductionMaximumSlots + 1U;
        } else {
            capacity += dockCount;
        }
    }
    return capacityByOwner;
}

bool runtimeAircraftPadSlotCapacityAllowsStructure(
    const RuntimeGameSessionState& state,
    const std::string& owner,
    const std::string& buildingTypeId,
    const BuildingType& building) {
    if (building.numberOfDocks <= 0
        || !runtimeProductionFactorySupportsLane(
            building,
            RuntimeProductionLane::Aircraft
        )
        || !runtimeAircraftPadBuildingHasCompatibleType(
            state.rules,
            buildingTypeId
        )) {
        return true;
    }
    const std::string canonicalOwner = runtimeRepairDepotCanonicalOwnerId(
        state,
        owner
    );
    if (canonicalOwner.empty()) {
        return false;
    }
    const std::map<std::string, std::size_t> capacityByOwner =
        runtimeAircraftPadSlotCapacityByOwner(state);
    const auto current = capacityByOwner.find(canonicalOwner);
    const std::size_t currentCapacity = current == capacityByOwner.end()
        ? 0U
        : current->second;
    const std::size_t additional = static_cast<std::size_t>(
        building.numberOfDocks
    );
    return currentCapacity <= runtimeAircraftProductionMaximumSlots
        && additional
            <= runtimeAircraftProductionMaximumSlots - currentCapacity;
}

bool validateRuntimeAircraftPadSlotCapacity(
    const RuntimeGameSessionState& state,
    std::string& errorMessage) {
    for (const auto& [owner, capacity] :
            runtimeAircraftPadSlotCapacityByOwner(state)) {
        if (capacity > runtimeAircraftProductionMaximumSlots) {
            errorMessage =
                "aircraft pad slot capacity exceeds the supported owner "
                "limit for " + owner;
            return false;
        }
    }
    return true;
}

const SmudgeType* runtimeSmudgeTypeForId(
    const RulesDatabase& rules,
    const std::string& typeId) {
    const std::string wanted = toUpperAsciiLocal(trimAsciiLocal(typeId));
    const auto found = std::find_if(
        rules.getSmudgeTypes().begin(),
        rules.getSmudgeTypes().end(),
        [&wanted](const SmudgeType& type) {
            return toUpperAsciiLocal(trimAsciiLocal(type.id)) == wanted;
        }
    );
    return found == rules.getSmudgeTypes().end() ? nullptr : &*found;
}

std::size_t clearRuntimeSmudgesForPlacedStructure(
    RuntimeProductionHostState& state,
    const WorldObjectInstance& structure) {
    if (structure.kind != WorldObjectKind::Structure) {
        return 0;
    }
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, structure);
    const int structureWidth = std::max(1, footprint.width);
    const int structureHeight = std::max(1, footprint.height);
    std::vector<WorldSmudge>& smudges = state.world.accessSmudges();
    const std::size_t before = smudges.size();
    smudges.erase(
        std::remove_if(
            smudges.begin(),
            smudges.end(),
            [&state, &structure, structureWidth, structureHeight](
                const WorldSmudge& smudge
            ) {
                const SmudgeType* type = runtimeSmudgeTypeForId(
                    state.rules,
                    smudge.type
                );
                const int smudgeWidth = type == nullptr
                    ? 1
                    : std::max(1, type->width);
                const int smudgeHeight = type == nullptr
                    ? 1
                    : std::max(1, type->height);
                return structure.x < smudge.x + smudgeWidth
                    && structure.x + structureWidth > smudge.x
                    && structure.y < smudge.y + smudgeHeight
                    && structure.y + structureHeight > smudge.y;
            }
        ),
        smudges.end()
    );
    const std::size_t cleared = before - smudges.size();
    if (cleared > 0) {
        state.repaintRequested = true;
    }
    return cleared;
}

WorldObjectInstance* addRuntimeObjectInstanceForOwner(
    RuntimeProductionHostState& state,
    const std::string& owner,
    RuntimeBuildKind kind,
    const std::string& typeId,
    const RuntimeCellPoint& cell,
    std::optional<RuntimeProductionLane> productionLane,
    bool clearPlacedSmudges,
    bool initialTransportCargo,
    int initialOccupiedStructureId) {
    if (kind == RuntimeBuildKind::Building
        || kind == RuntimeBuildKind::Defense) {
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, typeId);
        if (building != nullptr
            && !runtimeAircraftPadSlotCapacityAllowsStructure(
                state,
                owner,
                typeId,
                *building
            )) {
            return nullptr;
        }
    }

    WorldObjectInstance object;
    object.instanceId = nextRuntimeObjectInstanceId(state);
    object.kind = runtimeKindForBuildItem(kind);
    object.owner = owner;
    object.type = typeId;
    if (kind == RuntimeBuildKind::Unit) {
        const bool listedVehicle =
            state.rules.findUnitType("UnitType", typeId) != nullptr;
        const bool listedAircraft =
            state.rules.findUnitType("AircraftType", typeId) != nullptr;
        object.authoredAircraft = productionLane.has_value()
            ? *productionLane == RuntimeProductionLane::Aircraft
            : listedAircraft && !listedVehicle;
    }
    applyRuntimePlacementObjectPose(state, object, kind, cell);
    object.facing = runtimeInitialProducedFacing(state, kind, typeId);
    object.turretFacing = -1;
    if (kind == RuntimeBuildKind::Infantry) {
        constexpr std::array<int, 3> infantrySubCells = {2, 4, 3};
        object.subCell = infantrySubCells[
            static_cast<std::size_t>(object.instanceId)
                % infantrySubCells.size()
        ];
    } else {
        object.subCell = -1;
    }
    object.mission =
        (kind == RuntimeBuildKind::Building || kind == RuntimeBuildKind::Defense)
            ? "Construction"
            : "Guard";
    object.alive = true;

    if (kind == RuntimeBuildKind::Building || kind == RuntimeBuildKind::Defense) {
        const BuildingType* building =
            findRuntimeBuildingTypeById(state.rules, typeId);
        object.health = building == nullptr || building->strength <= 0
            ? 256
            : building->strength;
        initializeRuntimeInfantryServiceAmmo(object, building);
        const bool wall = building != nullptr && building->wall;
        object.buildAnimTicksTotal = wall ? 0 : runtimeStructureBuildupTiming(state, object).fixedTicks;
        object.buildAnimTicksRemaining = object.buildAnimTicksTotal;
        applyRuntimePlacementRenderAnchor(state, object, kind, cell);
    } else {
        const UnitType* unit = object.authoredAircraft
            ? state.rules.findUnitType("AircraftType", typeId)
            : findRuntimeUnitTypeById(state.rules, typeId);
        object.health = unit == nullptr || unit->strength <= 0
            ? 256
            : unit->strength;
        object.submerged = unit != nullptr && unit->underwater;
        initializeRuntimeObjectAmmo(object, unit);
        applyRuntimeInitialObjectFlightState(state.rules, object, true);
        if (unit != nullptr && unit->turret) {
            object.turretFacing = object.facing;
        }
    }

    runtimeInitializeModExtensions(object, state.rules, state.config.fixedTickHz);
    if (initialTransportCargo) {
        object.alive = false;
        object.mission = "InsideTransport";
        object.subCell = -1;
        object.airborne = false;
        object.flightLevel = object.level;
    }
    initializeRuntimeObjectCloakState(state, object);
    if (runtimeObjectOccupiesAirNavigation(object)
        && !runtimeAirCellIsClear(state, object.instanceId, cell)) {
        const auto freeAirCell = findRuntimeAirMoveTarget(state, object, cell);
        if (!freeAirCell.has_value()) return nullptr;
        setRuntimeObjectCell(state, object, *freeAirCell);
    }

    if (initialOccupiedStructureId >= 0) {
        const auto* host = findObjectById(state, initialOccupiedStructureId);
        if (initialTransportCargo || kind != RuntimeBuildKind::Infantry
            || host == nullptr || !host->alive || host->owner != owner
            || !runtimeCellIsAllowedOccupiedStructureFootprint(
                state, cell, initialOccupiedStructureId, &object)
            || !findRuntimePassableCellNear(
                state, object, cell, 0, initialOccupiedStructureId).has_value()) {
            return nullptr;
        }
    }

    state.world.accessObjects().push_back(std::move(object));
    if (!initialTransportCargo && runtimeInfantryUsesGroundSubcells(state.world.accessObjects().back())) {
        assignRuntimeInfantrySubcellAtCurrentLocation(
            state,
            state.world.accessObjects().back()
        );
        // Interior workers use the same subcell state as returning workers.
        // The host's navigation cell has no free slot; other foundation cells
        // may have one. Canonicalize both without relocating outside the host.
        if (initialOccupiedStructureId < 0 && state.world.accessObjects().back().subCell < 0) {
            const std::optional<RuntimeCellPoint> relocated =
                findRuntimePassableCellNear(
                    state,
                    state.world.accessObjects().back(),
                    cell,
                    6
                );
            if (relocated.has_value()
                && *relocated != runtimeCellPointForObject(
                    state.world.accessObjects().back()
                )) {
                setRuntimeObjectCell(
                    state,
                    state.world.accessObjects().back(),
                    *relocated
                );
            }
        }
        if (initialOccupiedStructureId < 0 && state.world.accessObjects().back().subCell < 0) {
            const int rejectedObjectId =
                state.world.accessObjects().back().instanceId;
            state.world.accessObjects().pop_back();
            releaseRuntimeInfantrySubcellReservation(
                state,
                rejectedObjectId
            );
            invalidateRuntimeObjectProjectionCache(state);
            return nullptr;
        }
    }
    state.cloakObservedHealthByObject[
        state.world.accessObjects().back().instanceId
    ] = state.world.accessObjects().back().health;
    if (clearPlacedSmudges) {
        (void)clearRuntimeSmudgesForPlacedStructure(
            state,
            state.world.accessObjects().back()
        );
    }
    initializeRuntimeSpyDefaultDisguiseForObject(
        state,
        state.world.accessObjects().back().instanceId
    );
    if (state.world.accessObjects().back().kind == WorldObjectKind::Structure)
        refreshRuntimeObjectOccupancyAfterLocalChange(state);
    else invalidateRuntimeObjectProjectionCache(state);
    return &state.world.accessObjects().back();
}

bool advanceRuntimeBuildAnimations(RuntimeProductionHostState& state) {
    bool changed = false;
    std::set<std::string> freeBuildupCandidates;
    for (WorldObjectInstance& object : state.world.accessObjects()) {
        if ((!object.alive && !runtimeStructureIsSelling(object)) || object.buildAnimTicksRemaining <= 0) {
            continue;
        }
        if (runtimeStructureIsRepacking(object) && state.specialMechanismsInitialized
            && state.specialMechanisms.isTemporalFrozen(object.instanceId)) continue;
        --object.buildAnimTicksRemaining;
        if (object.buildAnimTicksRemaining <= 0) {
            object.buildAnimTicksRemaining = 0;
            if (object.kind == WorldObjectKind::Structure) {
                const ArtType* art = runtimeArtTypeForObject(state, object);
                if (art != nullptr
                    && art->freeBuildup
                    && !trimAsciiLocal(art->buildup).empty()) {
                    freeBuildupCandidates.insert(art->buildup);
                }
                if (toLowerAsciiLocal(object.mission) == "construction") {
                    object.mission = "Guard";
                }
            }
            if (!runtimeStructureIsRepacking(object)) object.buildAnimTicksTotal = 0;
        }
        changed = true;
    }

    for (const std::string& imageId : freeBuildupCandidates) {
        const bool stillInUse = std::any_of(
            state.world.getObjects().begin(),
            state.world.getObjects().end(),
            [&state, &imageId](const WorldObjectInstance& object) {
                if ((!object.alive && !runtimeStructureIsSelling(object))
                    || object.kind != WorldObjectKind::Structure
                    || object.buildAnimTicksRemaining <= 0) {
                    return false;
                }
                const ArtType* art = runtimeArtTypeForObject(state, object);
                return art != nullptr
                    && toLowerAsciiLocal(trimAsciiLocal(art->buildup))
                        == toLowerAsciiLocal(trimAsciiLocal(imageId));
            }
        );
        if (!stillInUse) {
            (void)releaseRuntimeAuxiliaryShpImageFromCache(
                state.renderCache,
                imageId
            );
        }
    }
    return changed;
}

bool advanceRuntimeInfantryProneStates(RuntimeGameSessionState& state) {
    RuntimePerfTraceScope stageTrace("advanceRuntimeInfantryProneStates", state.tick);
    bool changed = false;
    for (WorldObjectInstance& object : state.world.accessObjects()) {
        if (!object.prone) {
            object.proneTicksRemaining = 0;
            continue;
        }
        if (!object.alive
            || object.kind != WorldObjectKind::Infantry
            || runtimeObjectHasDeployedState(state, object)) {
            object.prone = false;
            object.proneTicksRemaining = 0;
            changed = true;
            continue;
        }
        if (object.proneTicksRemaining > 0) {
            --object.proneTicksRemaining;
            changed = true;
        }
        if (object.proneTicksRemaining <= 0) {
            object.prone = false;
            object.proneTicksRemaining = 0;
            changed = true;
        }
    }
    return changed;
}

std::optional<RuntimeSelectedPlacement> runtimeSelectedPlacement(
    const RuntimeProductionHostState& state) {
    std::optional<RuntimeProductionLane> selectedLane =
        state.economy.selectedPlacementLane;
    std::uint64_t selectedSerial =
        state.economy.selectedPlacementSerial;
    if (runtimeUsesGameplayIntentRouter(state)
        && !state.humanHouseScopeActive) {
        const auto& intent = state.multiplayerIntentRouter.placement();
        if (!intent.has_value()) {
            return std::nullopt;
        }
        selectedLane = static_cast<RuntimeProductionLane>(intent->lane);
        selectedSerial = intent->productionSerial;
    }
    if (!selectedLane.has_value() || selectedSerial == 0) {
        return std::nullopt;
    }
    const RuntimeProductionLane lane = *selectedLane;
    if (lane != RuntimeProductionLane::Structures
        && lane != RuntimeProductionLane::Armory) {
        return std::nullopt;
    }
    const RuntimeProductionLaneState& laneState =
        state.economy.localProductionLanes.lanes[
            runtimeProductionLaneIndex(lane)
        ];
    if (!laneState.ready.has_value()
        || laneState.ready->serial
            != selectedSerial) {
        return std::nullopt;
    }
    const std::optional<RuntimeProductionCatalogAdapter> catalog =
        runtimeProductionCatalogLookup(state, laneState.ready->itemKey);
    if (!catalog.has_value()
        || catalog->item == nullptr
        || catalog->lane != lane
        || !runtimeBuildKindUsesSingleStructureSlot(catalog->item->kind)) {
        return std::nullopt;
    }
    return RuntimeSelectedPlacement{lane, *laneState.ready, catalog->item};
}

void clearRuntimePlacementSelection(RuntimeGameSessionState& state) {
    state.economy.selectedPlacementLane.reset();
    state.economy.selectedPlacementSerial = 0;
    state.economy.placementCell = RuntimeCellPoint{};
    state.economy.placementValid = false;
}

void clearRuntimeInvalidPlacementSelection(RuntimeGameSessionState& state) {
    // Validate the ledger selection independently of local multiplayer mouse
    // intent. A completed order stays ready until an explicit sidebar click.
    const auto lane = state.economy.selectedPlacementLane;
    if (lane && (*lane == RuntimeProductionLane::Structures || *lane == RuntimeProductionLane::Armory)) {
        const auto& ready = state.economy.localProductionLanes.lanes[runtimeProductionLaneIndex(*lane)].ready;
        if (ready && ready->serial == state.economy.selectedPlacementSerial) return;
    }
    clearRuntimePlacementSelection(state);
}

std::optional<RuntimeCellPoint> findRuntimeOpenSurfaceWaterCellNear(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& mover,
    const RuntimeCellPoint& desired,
    int maximumRadius,
    const std::unordered_map<int, int>* occupiedByCell,
    const RuntimeCellPoint* excludedCell) {
    for (int radius = 0; radius <= std::max(0, maximumRadius); ++radius) {
        for (int y = desired.y - radius;
            y <= desired.y + radius;
            ++y) {
            for (int x = desired.x - radius;
                x <= desired.x + radius;
                ++x) {
                if (radius > 0
                    && std::abs(x - desired.x) != radius
                    && std::abs(y - desired.y) != radius) {
                    continue;
                }
                const RuntimeCellPoint candidate{x, y};
                if (excludedCell != nullptr && candidate == *excludedCell) {
                    continue;
                }
                if (!runtimeProductionCellIsOpenSurfaceWater(
                        state,
                        candidate
                    )) {
                    continue;
                }
                const std::optional<RuntimeCellPoint> passable =
                    findRuntimePassableCellNear(
                        state,
                        mover,
                        candidate,
                        0,
                        -1,
                        nullptr,
                        nullptr,
                        occupiedByCell
                    );
                if (passable.has_value() && *passable == candidate) {
                    return passable;
                }
            }
        }
    }
    return std::nullopt;
}

const UnitType* findRuntimePadAircraftUnitType(
    const RulesDatabase& rules,
    const std::string& typeId) {
    if (!rules.isPadAircraft(typeId)) {
        return nullptr;
    }
    if (const UnitType* vehicle = findRuntimeProductionListedUnitType(
            rules.getVehicleTypes(),
            typeId
        )) {
        return vehicle;
    }
    return findRuntimeProductionListedUnitType(
        rules.getAircraftTypes(),
        typeId
    );
}

const UnitType* findRuntimePadAircraftUnitType(
    const RulesDatabase& rules,
    const WorldObjectInstance& object) {
    if (!rules.isPadAircraft(object.type)) {
        return nullptr;
    }
    if (object.authoredAircraft) {
        return findRuntimeProductionListedUnitType(
            rules.getAircraftTypes(),
            object.type
        );
    }
    if (const UnitType* vehicle = findRuntimeProductionListedUnitType(
            rules.getVehicleTypes(),
            object.type
        )) {
        return vehicle;
    }
    return findRuntimeProductionListedUnitType(
        rules.getAircraftTypes(),
        object.type
    );
}

bool runtimeAircraftPadHostStructurallyEligibleForOwner(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& anchor,
    const std::string& owner) {
    if (!anchor.alive || anchor.health == 0 || anchor.rubble
        || anchor.kind != WorldObjectKind::Structure
        || !runtimeProductionOwnersMatch(state, anchor.owner, owner)) {
        return false;
    }
    const BuildingType* building =
        findRuntimeBuildingTypeById(state.rules, anchor.type);
    return building != nullptr
        && building->numberOfDocks > 0
        && runtimeProductionFactorySupportsLane(
            *building,
            RuntimeProductionLane::Aircraft
        );
}

bool runtimeAircraftCanDockAtStructureForOwner(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item,
    const WorldObjectInstance& anchor,
    const std::string& owner) {
    const UnitType* unit = findRuntimePadAircraftUnitType(
        state.rules,
        item.typeId
    );
    const BuildingType* building =
        findRuntimeBuildingTypeById(state.rules, anchor.type);
    if (unit == nullptr
        || building == nullptr
        || building->numberOfDocks <= 0
        || !runtimeAircraftPadHostStructurallyEligibleForOwner(
            state,
            anchor,
            owner
        )) {
        return false;
    }
    const std::vector<std::string> dockTypes =
        splitRuntimeTokenList(unit->dock);
    if (dockTypes.empty()) {
        return true;
    }
    const std::string anchorType = toUpperAsciiLocal(anchor.type);
    return std::any_of(
        dockTypes.begin(),
        dockTypes.end(),
        [&anchorType](const std::string& dockType) {
            return toUpperAsciiLocal(trimAsciiLocal(dockType)) == anchorType;
        }
    );
}

int runtimeFreeAircraftDockIndex(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& anchor,
    int dockCount) {
    std::vector<bool> occupied(
        static_cast<std::size_t>(std::max(0, dockCount)),
        false
    );
    for (const WorldObjectInstance& object : state.world.getObjects()) {
        if (!object.alive
            || object.dockedToObjectId != anchor.instanceId
            || object.dockIndex < 0
            || object.dockIndex >= dockCount) {
            continue;
        }
        occupied[static_cast<std::size_t>(object.dockIndex)] = true;
    }
    for (int index = 0; index < dockCount; ++index) {
        if (!occupied[static_cast<std::size_t>(index)]) {
            return index;
        }
    }
    return -1;
}

RuntimeProductionSpawn runtimeAircraftDockSpawn(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& anchor,
    int dockIndex) {
    RuntimeProductionSpawn spawn;
    spawn.anchor = &anchor;
    spawn.dockIndex = dockIndex;
    spawn.aircraftDock = true;
    spawn.renderX = runtimeObjectRenderX(anchor);
    spawn.renderY = runtimeObjectRenderY(anchor);
    spawn.level = anchor.level;
    const ArtType* art = runtimeArtTypeForObject(state, anchor);
    RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, anchor);
    if (art != nullptr) {
        const RuntimeStructureFootprint authoredFootprint =
            parseRuntimeFoundationSize(art->foundation);
        if (authoredFootprint.valid) {
            footprint = authoredFootprint;
        }
    }
    // DockingOffset is measured from the full foundation center in the
    // building art's coordinate space. Using (size - 1) / 2 instead moves
    // every pad up by half a tile (15 pixels at 60x30). Keep the fractional
    // position for rendering, and use the containing cell for navigation.
    spawn.renderX +=
        static_cast<double>(std::max(1, footprint.width)) * 0.5;
    spawn.renderY +=
        static_cast<double>(std::max(1, footprint.height)) * 0.5;
    if (art != nullptr) {
        const auto offset = std::find_if(
            art->dockingOffsets.begin(),
            art->dockingOffsets.end(),
            [dockIndex](const ArtType::DockingOffset& candidate) {
                return candidate.index == dockIndex;
            }
        );
        if (offset != art->dockingOffsets.end()) {
            spawn.renderX += static_cast<double>(offset->x) / 256.0;
            spawn.renderY += static_cast<double>(offset->y) / 256.0;
            spawn.level += static_cast<int>(std::lround(
                static_cast<double>(offset->z) / 256.0
            ));
        }
    }
    spawn.cell = {
        static_cast<int>(std::floor(spawn.renderX)),
        static_cast<int>(std::floor(spawn.renderY))
    };
    const int cellKey = runtimeCellKey(spawn.cell.x, spawn.cell.y);
    if (cellKey < 0
        || (!state.terrainByCell.empty()
            && state.terrainByCell.find(cellKey) == state.terrainByCell.end())) {
        spawn.cell = runtimeCellPointForObject(anchor);
    }
    return spawn;
}

bool applyRuntimeAircraftDockPose(
    const RuntimeGameSessionState& state,
    WorldObjectInstance& aircraft,
    const WorldObjectInstance& anchor,
    int dockIndex,
    bool actualArrival) {
    const bool landingSound = actualArrival && aircraft.airborne;
    const RuntimeProductionSpawn dock =
        runtimeAircraftDockSpawn(state, anchor, dockIndex);
    const bool cellChanged = aircraft.x != dock.cell.x
        || aircraft.y != dock.cell.y;
    aircraft.x = dock.cell.x;
    aircraft.y = dock.cell.y;
    aircraft.cell = runtimeCellKey(dock.cell.x, dock.cell.y);
    aircraft.dockedToObjectId = anchor.instanceId;
    aircraft.dockIndex = dockIndex;
    aircraft.mission = "Dock";
    aircraft.level = dock.level;
    // Fixed-wing descent and its auxiliary sound finish before attachment.
    // Emit only on an actual arrival, never pad creation or reconciliation.
    if (landingSound) queueRuntimeAircraftAuxSound(state, aircraft, false, 0);
    aircraft.airborne = false;
    aircraft.flightLevel = dock.level;
    aircraft.onBridge = false;
    aircraft.hasRenderPosition = true;
    aircraft.renderX = dock.renderX;
    aircraft.renderY = dock.renderY;
    aircraft.renderMoveActive = false;
    aircraft.renderLevel = static_cast<double>(aircraft.level);
    aircraft.renderOnBridge = aircraft.onBridge;
    const int poseDir = state.rules.getPoseDir();
    aircraft.facing = worldObjectFacingFromMapFacing(poseDir);
    return cellChanged;
}

bool runtimeAircraftDockAssignmentCompatible(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& aircraft,
    const WorldObjectInstance& anchor) {
    if (!aircraft.alive
        || !anchor.alive
        || anchor.kind != WorldObjectKind::Structure
        || !runtimeProductionOwnersMatch(
            state,
            aircraft.owner,
            anchor.owner
        )) {
        return false;
    }
    const UnitType* padUnit = findRuntimePadAircraftUnitType(
        state.rules,
        aircraft
    );
    const BuildingType* building =
        findRuntimeBuildingTypeById(state.rules, anchor.type);
    if (padUnit == nullptr
        || building == nullptr
        || !runtimeAircraftPadHostStructurallyEligibleForOwner(
            state,
            anchor,
            aircraft.owner
        )) {
        return false;
    }
    const std::vector<std::string> dockTypes =
        splitRuntimeTokenList(padUnit->dock);
    if (dockTypes.empty()) {
        return true;
    }
    const std::string anchorType = toUpperAsciiLocal(anchor.type);
    return std::any_of(
        dockTypes.begin(),
        dockTypes.end(),
        [&anchorType](const std::string& dockType) {
            return toUpperAsciiLocal(trimAsciiLocal(dockType)) == anchorType;
        }
    );
}

std::uint64_t runtimeAircraftDockSlotKey(int anchorId, int dockIndex) {
    return (static_cast<std::uint64_t>(
                static_cast<std::uint32_t>(anchorId)) << 32)
        | static_cast<std::uint32_t>(dockIndex);
}

void refreshRuntimeAircraftDockAssignments(RuntimeProductionHostState& state) {
    struct PendingAircraftAssignment {
        WorldObjectInstance* aircraft = nullptr;
        bool wasPhysicallyDocked = false;
    };

    std::unordered_set<std::uint64_t> occupiedSlots;
    if (state.repairDepotsInitialized) {
        for (const RuntimeRepairDepotRelation& relation :
                state.repairDepots.relations()) {
            if (state.repairDepots.claimsDock(
                    relation.hostId,
                    relation.dockIndex
                )) {
                occupiedSlots.insert(runtimeAircraftDockSlotKey(
                    relation.hostId,
                    relation.dockIndex
                ));
            }
        }
    }
    std::vector<WorldObjectInstance*> padAircraft;
    padAircraft.reserve(state.world.getObjects().size());
    for (WorldObjectInstance& object : state.world.accessObjects()) {
        if (object.alive
            && !runtimeObjectSuspendedByMagBeam(state, object.instanceId)
            && findRuntimePadAircraftUnitType(
                state.rules,
                object
            ) != nullptr) {
            padAircraft.push_back(&object);
            continue;
        }
        // Ground repair depots and other dock users share the same world
        // mirror. Their live reservation must win before an airport assigns
        // a pad, even on a modded UnitRepair+UnitReload host.
        if (object.alive
            && object.dockedToObjectId >= 0
            && object.dockIndex >= 0) {
            occupiedSlots.insert(runtimeAircraftDockSlotKey(
                object.dockedToObjectId,
                object.dockIndex
            ));
        }
    }
    std::sort(
        padAircraft.begin(),
        padAircraft.end(),
        [](const WorldObjectInstance* left,
           const WorldObjectInstance* right) {
            return left != nullptr && right != nullptr
                ? left->instanceId < right->instanceId
                : right != nullptr;
        }
    );
    std::vector<PendingAircraftAssignment> pending;
    bool physicallyRelocated = false;
    for (WorldObjectInstance* aircraftPointer : padAircraft) {
        if (aircraftPointer == nullptr) {
            continue;
        }
        WorldObjectInstance& aircraft = *aircraftPointer;

        const WorldObjectInstance* anchor =
            findObjectById(state, aircraft.dockedToObjectId);
        const BuildingType* building =
            anchor == nullptr
                ? nullptr
                : findRuntimeBuildingTypeById(state.rules, anchor->type);
        const bool slotInRange = building != nullptr
            && aircraft.dockIndex >= 0
            && aircraft.dockIndex < building->numberOfDocks;
        const std::uint64_t slotKey = runtimeAircraftDockSlotKey(
            aircraft.dockedToObjectId,
            aircraft.dockIndex
        );
        if (anchor != nullptr
            && slotInRange
            && runtimeAircraftDockAssignmentCompatible(
                state,
                aircraft,
                *anchor
            )
            && occupiedSlots.insert(slotKey).second) {
            if (toLowerAsciiLocal(aircraft.mission) == "dock") {
                physicallyRelocated = applyRuntimeAircraftDockPose(
                    state,
                    aircraft,
                    *anchor,
                    aircraft.dockIndex
                ) || physicallyRelocated;
            }
            continue;
        }

        const bool wasPhysicallyDocked =
            toLowerAsciiLocal(aircraft.mission) == "dock";
        aircraft.dockedToObjectId = -1;
        aircraft.dockIndex = -1;
        if (wasPhysicallyDocked) {
            clearRuntimeRenderPosition(aircraft);
            aircraft.mission = "Guard";
        }
        pending.push_back({&aircraft, wasPhysicallyDocked});
    }

    for (PendingAircraftAssignment& assignment : pending) {
        WorldObjectInstance* aircraft = assignment.aircraft;
        if (aircraft == nullptr || !aircraft->alive) {
            continue;
        }
        bool assigned = false;
        for (const WorldObjectInstance& anchor : state.world.getObjects()) {
            if (!runtimeAircraftDockAssignmentCompatible(
                    state,
                    *aircraft,
                    anchor
                )) {
                continue;
            }
            const BuildingType* building =
                findRuntimeBuildingTypeById(state.rules, anchor.type);
            const int dockCount = building == nullptr
                ? 0
                : std::max(0, building->numberOfDocks);
            for (int dockIndex = 0; dockIndex < dockCount; ++dockIndex) {
                const std::uint64_t slotKey = runtimeAircraftDockSlotKey(
                    anchor.instanceId,
                    dockIndex
                );
                if (!occupiedSlots.insert(slotKey).second) {
                    continue;
                }
                aircraft->dockedToObjectId = anchor.instanceId;
                aircraft->dockIndex = dockIndex;
                if (assignment.wasPhysicallyDocked) {
                    physicallyRelocated = applyRuntimeAircraftDockPose(
                        state,
                        *aircraft,
                        anchor,
                        dockIndex
                    ) || physicallyRelocated;
                }
                assigned = true;
                break;
            }
            if (assigned) {
                break;
            }
        }
    }
    // Changing a support slot cancels the old pad's descent immediately,
    // including snapshots taken between the host exit and the next tick.
    // Retain the height envelope for a continuous climb or stopped pose.
    for (const auto* aircraft : padAircraft) {
        if (!aircraft) continue;
        const auto found = state.aircraftFlights.find(aircraft->instanceId);
        if (found != state.aircraftFlights.end() && found->second.landingHostId >= 0
            && (found->second.landingHostId != aircraft->dockedToObjectId
                || found->second.landingDockIndex != aircraft->dockIndex)) {
            found->second.landingHostId = found->second.landingDockIndex = -1;
        }
    }
    if (physicallyRelocated) {
        refreshRuntimeObjectOccupancyAfterLocalChange(state);
    }
}

std::optional<RuntimeCellPoint> runtimeSpecialBuildingInfantryExitCell(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& host,
    const std::string& owner,
    const std::string& infantryTypeId) {
    WorldObjectInstance probe;
    probe.instanceId = -1;
    probe.kind = WorldObjectKind::Infantry;
    probe.owner = owner;
    probe.type = infantryTypeId;
    probe.alive = true;
    const RuntimeCellPoint anchor = runtimeCellPointForObject(host);
    const RuntimeStructureFootprint footprint =
        runtimeStructureFootprintForObject(state, host);
    const int width = std::max(1, footprint.width);
    const int height = std::max(1, footprint.height);
    const int centerX = anchor.x + width / 2;
    const int centerY = anchor.y + height / 2;
    const std::array<RuntimeCellPoint, 8> candidates{{
        {centerX, anchor.y + height},
        {centerX - 1, anchor.y + height},
        {centerX + 1, anchor.y + height},
        {anchor.x + width, centerY},
        {anchor.x - 1, centerY},
        {centerX, anchor.y - 1},
        {anchor.x + width, anchor.y + height},
        {anchor.x - 1, anchor.y + height}
    }};
    const std::unordered_map<int, int> occupiedByCell =
        buildRuntimeOccupancyLookup(state);
    for (int searchRadius : {0, 3, 6}) {
        for (const RuntimeCellPoint& candidate : candidates) {
            const std::optional<RuntimeCellPoint> passable =
                findRuntimePassableCellNear(
                    state,
                    probe,
                    candidate,
                    searchRadius,
                    -1,
                    nullptr,
                    nullptr,
                    &occupiedByCell
                );
            if (passable.has_value()) {
                return passable;
            }
        }
    }
    return std::nullopt;
}

bool reconcileRuntimeCloneDeliveryLeases(RuntimeGameSessionState& state) {
    bool changed = false;
    for (WorldObjectInstance& host : state.world.accessObjects()) {
        if (host.specialCloneDeliveryObjectId < 0) {
            continue;
        }
        const WorldObjectInstance* clone = findObjectById(
            state,
            host.specialCloneDeliveryObjectId
        );
        const bool invalidClone = clone == nullptr
            || !clone->alive
            || clone->health <= 0
            || clone->kind != WorldObjectKind::Infantry
            || !host.alive
            || host.health <= 0
            || host.kind != WorldObjectKind::Structure
            || runtimeRepairDepotCanonicalOwnerId(state, clone->owner)
                != runtimeRepairDepotCanonicalOwnerId(state, host.owner);
        if (invalidClone) {
            host.specialCloneDeliveryObjectId = -1;
            changed = true;
            continue;
        }

        const RuntimeStructureFootprint footprint =
            runtimeStructureFootprintForObject(state, host);
        const RuntimeCellPoint anchor = runtimeCellPointForObject(host);
        const int width = std::max(1, footprint.width);
        const int height = std::max(1, footprint.height);
        const bool cloneClearedDeliveryArea = clone->x < anchor.x - 1
            || clone->x > anchor.x + width
            || clone->y < anchor.y - 1
            || clone->y > anchor.y + height;
        if (cloneClearedDeliveryArea) {
            host.specialCloneDeliveryObjectId = -1;
            changed = true;
        }
    }
    return changed;
}

std::optional<RuntimeCellPoint> findRuntimeSpawnCellNearObjectForOwner(
    const RuntimeGameSessionState& state,
    const RuntimeBuildCatalogItem& item,
    const WorldObjectInstance& anchor,
    const std::string& owner) {
    WorldObjectInstance probe;
    probe.instanceId = -1;
    probe.kind = runtimeKindForBuildItem(item.kind);
    probe.owner = owner;
    probe.type = item.typeId;
    probe.alive = true;

    const RuntimeCellPoint anchorCell = runtimeCellPointForObject(anchor);
    for (int radius = 1; radius <= 6; ++radius) {
        for (int dy = -radius; dy <= radius; ++dy) {
            for (int dx = -radius; dx <= radius; ++dx) {
                if (std::abs(dx) != radius && std::abs(dy) != radius) {
                    continue;
                }
                const RuntimeCellPoint candidate{
                    anchorCell.x + dx,
                    anchorCell.y + dy
                };
                const std::optional<RuntimeCellPoint> passable =
                    findRuntimePassableCellNear(state, probe, candidate, 0);
                if (passable.has_value()) {
                    return passable;
                }
            }
        }
    }

    return std::nullopt;
}

WorldObjectKind runtimeWorldObjectKindFromName(const std::string& name) {
    const std::string lower = toLowerAsciiLocal(trimAsciiLocal(name));
    if (lower == "unit") {
        return WorldObjectKind::Unit;
    }
    if (lower == "infantry") {
        return WorldObjectKind::Infantry;
    }
    return WorldObjectKind::Structure;
}

std::string runtimeBehaviorKindName(RuntimeBehaviorKind kind) {
    switch (kind) {
    case RuntimeBehaviorKind::Move:
        return "move";
    case RuntimeBehaviorKind::Attack:
        return "attack";
    case RuntimeBehaviorKind::None:
        return "none";
    }
    return "none";
}

