        runtimeMultiplayerAuthoritativeMixBool(hash, weapon->charges);
        runtimeMultiplayerAuthoritativeMixBool(hash, weapon->decloakToFire);
        // RevealOnFire is covered by RulesDatabase::getDetailRulesHash().
        runtimeMultiplayerAuthoritativeMixBool(hash, weapon->cellRangefinding);
        runtimeMultiplayerAuthoritativeMixBool(hash, weapon->neverUse);
        runtimeMultiplayerAuthoritativeMixBool(hash, weapon->laser);
        runtimeMultiplayerAuthoritativeMixBool(hash, weapon->magBeam);
