std::uint64_t runtimeMultiplayerSnapshotCanonicalDoubleBits(double value) {
    if (std::isnan(value)) {
        return 0x7ff8000000000000ULL;
    }
    return value == 0.0 ? 0ULL : std::bit_cast<std::uint64_t>(value);
}

bool runtimeMultiplayerSnapshotDoubleFromBits(
    const std::string& value,
    double& output) {
    std::uint64_t bits = 0;
    if (!parseRuntimeUint64Strict(value, bits)) {
        return false;
    }
    if (bits == 0x8000000000000000ULL) {
        return false;
    }
    const std::uint64_t exponent = bits & 0x7ff0000000000000ULL;
    const std::uint64_t mantissa = bits & 0x000fffffffffffffULL;
    if (exponent == 0x7ff0000000000000ULL && mantissa != 0U
        && bits != 0x7ff8000000000000ULL) {
        return false;
    }
    output = std::bit_cast<double>(bits);
    return true;
}

std::uint64_t runtimeMultiplayerSnapshotTechTreeHash(
    const TechTreeReport& report,
    bool loaded) {
    std::uint64_t hash = runtimeStableHashString(
        "runtimeMultiplayerSnapshotTechTree/v1"
    );
    runtimeMultiplayerAuthoritativeMixTechTree(hash, report, loaded);
    return hash == 0U ? 1U : hash;
}

std::string runtimeMultiplayerSnapshotCatalogRecord(
    const RuntimeBuildCatalogItem& item) {
    std::ostringstream output;
    output << static_cast<int>(item.kind) << '|'
           << iniHexEncode(item.typeId) << '|'
           << iniHexEncode(item.owner) << '|'
           << iniHexEncode(item.requiredHouses) << '|'
           << iniHexEncode(item.forbiddenHouses) << '|'
           << iniHexEncode(item.prerequisite) << '|'
           << iniHexEncode(item.prerequisiteOverride) << '|'
           << iniHexEncode(item.requiredFactory) << '|'
           << item.cost << '|'
           << item.buildTicks << '|'
           << item.powerDelta << '|'
           << item.techLevel << '|'
           << runtimeBoolText(item.buildLimit.has_value()) << '|'
           << item.buildLimit.value_or(0) << '|'
           << runtimeBoolText(item.waterBound) << '|'
           << runtimeBoolText(item.naval) << '|'
           << runtimeBoolText(item.wall) << '|'
           << runtimeBoolText(item.techTreeAllowed) << '|'
           << runtimeBoolText(item.secretLabInjected) << '|'
           << iniHexEncode(item.techTreeKind);
    return output.str();
}

bool parseRuntimeMultiplayerSnapshotCatalogRecord(
    const std::string& value,
    RuntimeBuildCatalogItem& item) {
    const std::vector<std::string> fields = splitRuntimeSaveFields(value);
    if (fields.size() != 20U) {
        return false;
    }
    int kind = -1;
    bool hasBuildLimit = false;
    int buildLimit = 0;
    if (!parseRuntimeInt(fields[0], kind)
        || kind < static_cast<int>(RuntimeBuildKind::Building)
        || kind > static_cast<int>(RuntimeBuildKind::Unit)
        || !iniHexDecode(fields[1], item.typeId, 256U)
        || !iniHexDecode(fields[2], item.owner, 256U)
        || !iniHexDecode(fields[3], item.requiredHouses, 4096U)
        || !iniHexDecode(fields[4], item.forbiddenHouses, 4096U)
        || !iniHexDecode(fields[5], item.prerequisite, 4096U)
        || !iniHexDecode(fields[6], item.prerequisiteOverride, 4096U)
        || !iniHexDecode(fields[7], item.requiredFactory, 256U)
        || !parseRuntimeInt(fields[8], item.cost)
        || !parseRuntimeInt(fields[9], item.buildTicks)
        || !parseRuntimeInt(fields[10], item.powerDelta)
        || !parseRuntimeInt(fields[11], item.techLevel)
        || !parseRuntimeStrictBool(fields[12], hasBuildLimit)
        || !parseRuntimeInt(fields[13], buildLimit)
        || !parseRuntimeStrictBool(fields[14], item.waterBound)
        || !parseRuntimeStrictBool(fields[15], item.naval)
        || !parseRuntimeStrictBool(fields[16], item.wall)
        || !parseRuntimeStrictBool(fields[17], item.techTreeAllowed)
        || !parseRuntimeStrictBool(fields[18], item.secretLabInjected)
        || !iniHexDecode(fields[19], item.techTreeKind, 256U)
        || trimAsciiLocal(item.typeId).empty()
        || item.cost < 0 || item.buildTicks <= 0) {
        return false;
    }
    item.kind = static_cast<RuntimeBuildKind>(kind);
    item.buildLimit = hasBuildLimit
        ? std::optional<int>(buildLimit)
        : std::nullopt;
    item.label.clear();
    item.techTreeBlockedReason.clear();
    return true;
}

bool runtimeMultiplayerSnapshotRebindHumanFacade(
    RuntimeGameSessionState& state,
    const std::string& requestedOwner,
    std::string& errorMessage) {
    const std::string requestedKey =
        runtimeCanonicalHumanHouseOwner(requestedOwner);
    RuntimeHumanHouseAuthority* current = nullptr;
    RuntimeHumanHouseAuthority* requested = nullptr;
    for (RuntimeHumanHouseAuthority& authority :
            state.humanHouseAuthorities) {
        if (authority.localFacade) {
            if (current != nullptr) {
                errorMessage = "multiple local multiplayer facades";
                return false;
            }
            current = &authority;
        }
        if (authority.canonicalOwner == requestedKey) {
            requested = &authority;
        }
    }
    if (current == nullptr || requested == nullptr) {
        errorMessage = "multiplayer facade owner is unavailable";
        return false;
    }
    if (current == requested) {
        errorMessage.clear();
        return true;
    }
    if (!requested->remoteEconomy.has_value()
        || !requested->remoteTechTree.has_value()) {
        errorMessage = "requested multiplayer facade state is incomplete";
        return false;
    }

    current->remoteEconomy.emplace(std::move(state.economy));
    current->remoteTechTree.emplace(std::move(state.techTree));
    current->remoteTechTreeLoaded = state.techTreeLoaded;
    current->localFacade = false;
    state.economy = std::move(*requested->remoteEconomy);
    state.techTree = std::move(*requested->remoteTechTree);
    state.techTreeLoaded = requested->remoteTechTreeLoaded;
    requested->remoteEconomy.reset();
    requested->remoteTechTree.reset();
    requested->remoteTechTreeLoaded = false;
    requested->localFacade = true;
    errorMessage.clear();
    return true;
}

bool parseRuntimeMultiplayerSnapshotCellsText(
    const std::string& value,
    std::vector<RuntimeCellPoint>& cells,
    std::size_t maximumCount) {
    std::vector<RuntimeCellPoint> parsed;
    if (!value.empty()) {
        std::size_t begin = 0;
        while (begin <= value.size()) {
            const std::size_t end = value.find(';', begin);
            const std::string token = value.substr(
                begin,
                end == std::string::npos
                    ? std::string::npos
                    : end - begin
            );
            const std::size_t comma = token.find(',');
            RuntimeCellPoint cell;
            if (comma == std::string::npos
                || token.find(',', comma + 1U) != std::string::npos
                || !parseRuntimeInt(token.substr(0, comma), cell.x)
                || !parseRuntimeInt(token.substr(comma + 1U), cell.y)
                || parsed.size() >= maximumCount) {
                return false;
            }
            parsed.push_back(cell);
            if (end == std::string::npos) break;
            begin = end + 1U;
        }
    }
    cells = std::move(parsed);
    return true;
}

bool parseRuntimeMultiplayerSnapshotIntsText(
    const std::string& value,
    std::vector<int>& values,
    std::size_t maximumCount) {
    std::vector<int> parsed;
    if (!value.empty()) {
        std::size_t begin = 0;
        while (begin <= value.size()) {
            const std::size_t end = value.find(',', begin);
            int entry = 0;
            if (!parseRuntimeInt(
                    value.substr(
                        begin,
                        end == std::string::npos
                            ? std::string::npos
                            : end - begin
                    ),
                    entry
                )
                || parsed.size() >= maximumCount) {
                return false;
            }
            parsed.push_back(entry);
            if (end == std::string::npos) break;
            begin = end + 1U;
        }
    }
    values = std::move(parsed);
    return true;
}

std::string runtimeMultiplayerSnapshotBehaviorRecord(
    int objectId,
    const RuntimeObjectBehavior& behavior) {
    std::vector<int> ignored(
        behavior.pendingIgnoredObjectIds.begin(),
        behavior.pendingIgnoredObjectIds.end()
    );
    std::ostringstream output;
    output << objectId << '|'
           << static_cast<int>(behavior.kind) << '|'
           << static_cast<int>(behavior.state) << '|'
           << behavior.moveTarget.x << '|' << behavior.moveTarget.y << '|'
           << behavior.targetObjectId << '|'
           << runtimeBoolText(behavior.autoAcquired) << '|'
           << runtimeBoolText(behavior.attackBridge) << '|'
           << behavior.attackBridgeCell.x << '|'
           << behavior.attackBridgeCell.y << '|'
           << iniHexEncode(runtimeMultiplayerSnapshotCellsText(behavior.path))
           << '|' << runtimeBoolText(behavior.pathRequestPending)
           << '|' << runtimeBoolText(behavior.pendingPathTowardRange)
           << '|' << behavior.pendingPathStart.x
           << '|' << behavior.pendingPathStart.y
           << '|' << behavior.pendingPathGoal.x
           << '|' << behavior.pendingPathGoal.y
           << '|' << runtimeBoolText(behavior.pendingHasSharedGoal)
           << '|' << behavior.pendingSharedGoal.x
           << '|' << behavior.pendingSharedGoal.y
           << '|' << behavior.pendingAllowedOccupiedObjectId
           << '|' << behavior.pendingTargetObjectId
           << '|' << runtimeMultiplayerSnapshotCanonicalDoubleBits(
                behavior.pendingRangeCells
              )
           << '|' << runtimeBoolText(behavior.pendingAllowNearbyTarget)
           << '|' << iniHexEncode(runtimeMultiplayerSnapshotIntsText(ignored))
           << '|' << behavior.moveCooldownTicks
           << '|' << behavior.moveIntervalRemainderQ16
           << '|' << behavior.weaponCooldownTicks
           << '|' << behavior.blockedTicks
           << '|' << behavior.pathReplans
           << '|' << behavior.nextRepathTick
           << '|' << runtimeBoolText(behavior.returnToDeployed)
           << '|' << behavior.approachSlotIndex
           << '|' << runtimeBoolText(behavior.forceFire)
           << '|' << runtimeBoolText(behavior.attackGround);
    if (behavior.moveSegmentFrom.x >= 0 || behavior.factoryExitClearanceHostId >= 0) {
        output << '|' << behavior.moveSegmentFrom.x << '|' << behavior.moveSegmentFrom.y;
    }
    if (behavior.factoryExitClearanceHostId >= 0) {
        output << '|' << behavior.factoryExitClearanceHostId;
    }
    return output.str();
}

bool parseRuntimeMultiplayerSnapshotBehaviorRecord(
    const std::string& value,
    int& objectId,
    RuntimeObjectBehavior& behavior) {
    const std::vector<std::string> fields = splitRuntimeSaveFields(value);
    if (fields.size() != 33U && fields.size() != 35U && fields.size() != 37U
        && fields.size() != 38U) return false;
    behavior.factoryExitClearanceHostId = -1;
    int kind = -1;
    int state = -1;
    std::string pathText;
    std::string ignoredText;
    std::vector<RuntimeCellPoint> path;
    std::vector<int> ignored;
    if (!parseRuntimeInt(fields[0], objectId)
        || !parseRuntimeInt(fields[1], kind)
        || !parseRuntimeInt(fields[2], state)
        || kind < static_cast<int>(RuntimeBehaviorKind::None)
        || kind > static_cast<int>(RuntimeBehaviorKind::Attack)
        || state < static_cast<int>(RuntimeBehaviorState::Idle)
        || state > static_cast<int>(RuntimeBehaviorState::Complete)
        || !parseRuntimeInt(fields[3], behavior.moveTarget.x)
        || !parseRuntimeInt(fields[4], behavior.moveTarget.y)
        || !parseRuntimeInt(fields[5], behavior.targetObjectId)
        || !parseRuntimeStrictBool(fields[6], behavior.autoAcquired)
        || !parseRuntimeStrictBool(fields[7], behavior.attackBridge)
        || !parseRuntimeInt(fields[8], behavior.attackBridgeCell.x)
        || !parseRuntimeInt(fields[9], behavior.attackBridgeCell.y)
        || !iniHexDecode(fields[10], pathText)
        || !parseRuntimeMultiplayerSnapshotCellsText(pathText, path)
        || !parseRuntimeStrictBool(fields[11], behavior.pathRequestPending)
        || !parseRuntimeStrictBool(fields[12], behavior.pendingPathTowardRange)
        || !parseRuntimeInt(fields[13], behavior.pendingPathStart.x)
        || !parseRuntimeInt(fields[14], behavior.pendingPathStart.y)
        || !parseRuntimeInt(fields[15], behavior.pendingPathGoal.x)
        || !parseRuntimeInt(fields[16], behavior.pendingPathGoal.y)
        || !parseRuntimeStrictBool(fields[17], behavior.pendingHasSharedGoal)
        || !parseRuntimeInt(fields[18], behavior.pendingSharedGoal.x)
        || !parseRuntimeInt(fields[19], behavior.pendingSharedGoal.y)
        || !parseRuntimeInt(
            fields[20],
            behavior.pendingAllowedOccupiedObjectId
        )
        || !parseRuntimeInt(fields[21], behavior.pendingTargetObjectId)
        || !runtimeMultiplayerSnapshotDoubleFromBits(
            fields[22],
            behavior.pendingRangeCells
        )
        || !parseRuntimeStrictBool(
            fields[23],
            behavior.pendingAllowNearbyTarget
        )
        || !iniHexDecode(fields[24], ignoredText)
        || !parseRuntimeMultiplayerSnapshotIntsText(ignoredText, ignored)
        || !parseRuntimeInt(fields[25], behavior.moveCooldownTicks)
        || !parseRuntimeInt(fields[26], behavior.moveIntervalRemainderQ16)
        || !parseRuntimeInt(fields[27], behavior.weaponCooldownTicks)
        || !parseRuntimeInt(fields[28], behavior.blockedTicks)
        || !parseRuntimeInt(fields[29], behavior.pathReplans)
        || !parseRuntimeInt(fields[30], behavior.nextRepathTick)
        || !parseRuntimeStrictBool(fields[31], behavior.returnToDeployed)
        || !parseRuntimeInt(fields[32], behavior.approachSlotIndex)
        || objectId <= 0) {
        return false;
    }
    behavior.forceFire = false;
    behavior.attackGround = false;
    if (fields.size() >= 35U
        && (!parseRuntimeStrictBool(fields[33], behavior.forceFire)
            || !parseRuntimeStrictBool(fields[34], behavior.attackGround)
            || (behavior.attackGround && (!behavior.forceFire || behavior.attackBridge
                || behavior.targetObjectId >= 0)))) {
        return false;
    }
    behavior.moveSegmentFrom = {-1, -1};
    if (fields.size() == 37U || fields.size() == 38U) {
        if (!parseRuntimeInt(fields[35], behavior.moveSegmentFrom.x)
            || !parseRuntimeInt(fields[36], behavior.moveSegmentFrom.y)) return false;
        const bool noSegment = fields.size() == 38U
            && behavior.moveSegmentFrom.x == -1 && behavior.moveSegmentFrom.y == -1;
        if (noSegment && behavior.moveCooldownTicks != 0) return false;
        if (!noSegment && (behavior.moveSegmentFrom.x < 0 || behavior.moveSegmentFrom.x >= 512
            || behavior.moveSegmentFrom.y < 0 || behavior.moveSegmentFrom.y >= 512)) return false;
    }
    behavior.kind = static_cast<RuntimeBehaviorKind>(kind);
    behavior.state = static_cast<RuntimeBehaviorState>(state);
    if (fields.size() == 38U
        && (!parseRuntimeInt(fields[37], behavior.factoryExitClearanceHostId)
            || behavior.moveCooldownTicks < 0
            || behavior.factoryExitClearanceHostId < -1
            || (behavior.factoryExitClearanceHostId >= 0
                && (behavior.kind != RuntimeBehaviorKind::Move || behavior.targetObjectId != -1
                    || behavior.forceFire || behavior.attackGround || behavior.attackBridge)))) return false;
    behavior.path.assign(path.begin(), path.end());
    behavior.pendingIgnoredObjectIds.clear();
    for (int ignoredId : ignored) {
        if (!behavior.pendingIgnoredObjectIds.insert(ignoredId).second) {
            return false;
        }
    }
    return true;
}

void writeRuntimeMultiplayerObjectPoses(const RuntimeGameSessionState& state, std::ostream& output) {
    std::vector<const WorldObjectInstance*> objects;
    for (const auto& object : state.world.getObjects()) objects.push_back(&object);
    std::sort(objects.begin(), objects.end(), [](const auto* a, const auto* b) {
        return a->instanceId < b->instanceId;
    });
    output << "\n[MultiplayerObjectPoses]\nSchema=1\nCount=" << objects.size() << '\n';
    for (std::size_t index = 0; index < objects.size(); ++index) {
        const auto& object = *objects[index];
        output << index << '=' << object.instanceId << '|' << runtimeBoolText(object.hasRenderPosition)
            << '|' << runtimeMultiplayerSnapshotCanonicalDoubleBits(object.renderX)
            << '|' << runtimeMultiplayerSnapshotCanonicalDoubleBits(object.renderY)
            << '|' << runtimeBoolText(object.renderMoveActive)
            << '|' << runtimeMultiplayerSnapshotCanonicalDoubleBits(object.renderLevel)
            << '|' << runtimeBoolText(object.renderOnBridge) << '\n';
    }
}

bool runtimeMultiplayerSnapshotSectionExcluded(
    const std::string& section) {
    const std::string key = toUpperAsciiLocal(trimAsciiLocal(section));
    return key == "SKIRMISHSESSION"
        || key == "CAMPAIGN"
        || key == "RUNTIMEWORLDAUDIOHOST"
        || key == "WORLDAUDIORUNTIME"
        || key == "RUNTIMELIGHTINGHOST"
        || key == "LIGHTINGRUNTIME"
        // Death timelines are already in MultiplayerTransientEffects. The
        // ordinary-save section additionally carries local presentation.
        || key == "UNITDEATHANIMATIONS";
}

bool runtimeMultiplayerSnapshotNumericRecordKey(
    const std::string& key,
    int& index) {
    if (!parseRuntimeInt(key, index) || index < 0
        || std::to_string(index) != trimAsciiLocal(key)) {
        return false;
    }
    return true;
}

bool runtimeMultiplayerSnapshotSequenceSection(
    const std::string& section) {
    const std::string key = toUpperAsciiLocal(trimAsciiLocal(section));
    return key == "PROJECTILES"
        || key == "CRATES"
        || key == "TEAMMISSIONS"
        // Pose rows share their indices with OrderN and SegmentN records.
        || key == "CARRIERFLIGHTPOSES"
        // House/team headers precede their members and production records.
        || key == "COMPUTERTACTICS"
        || key == "CLONEPENDINGDELIVERIES";
}

const char* runtimeMultiplayerSnapshotKindName(
    RuntimeMultiplayerSnapshotKind kind) {
    return kind == RuntimeMultiplayerSnapshotKind::Save ? "Save" : "Load";
}

std::string runtimeMultiplayerSnapshotAuthorityDifferenceSummary(
    const RuntimeProductionHostState& expected,
    const RuntimeProductionHostState& restored) {
    std::vector<std::string> differences;
    const auto add = [&differences](bool different, const char* label) {
        if (different) differences.emplace_back(label);
    };
    add(expected.tick != restored.tick, "tick");
    add(expected.world.deterministicSimulationStateHash()
            != restored.world.deterministicSimulationStateHash(),
        "world");
    std::uint64_t expectedTriggers = runtimeStableHashString("trigger-probe");
    std::uint64_t restoredTriggers = runtimeStableHashString("trigger-probe");
    runtimeMultiplayerAuthoritativeMixTriggers(
        expectedTriggers,
        expected.triggers
    );
    runtimeMultiplayerAuthoritativeMixTriggers(
        restoredTriggers,
        restored.triggers
    );
    add(expectedTriggers != restoredTriggers, "triggers");
    add(expected.behaviors.size() != restored.behaviors.size(), "behaviors");
    add(expected.pendingPathObjectIds != restored.pendingPathObjectIds,
        "pending-paths");
    add(expected.pathFailureCache.size() != restored.pathFailureCache.size(),
        "path-failures");
    add(expected.attackApproachCache.size()
            != restored.attackApproachCache.size(),
        "attack-approaches");

    std::set<std::string> humanOwners;
    for (const RuntimeHumanHouseAuthority& authority :
            expected.humanHouseAuthorities) {
        humanOwners.insert(authority.canonicalOwner);
    }
    for (const RuntimeHumanHouseAuthority& authority :
            restored.humanHouseAuthorities) {
        humanOwners.insert(authority.canonicalOwner);
    }
    for (const std::string& owner : humanOwners) {
        const RuntimeEconomyState* expectedEconomy =
            runtimeHumanHouseEconomy(expected, owner);
        const RuntimeEconomyState* restoredEconomy =
            runtimeHumanHouseEconomy(restored, owner);
        std::uint64_t expectedEconomyHash = runtimeStableHashString("economy");
        std::uint64_t restoredEconomyHash = runtimeStableHashString("economy");
        if (expectedEconomy != nullptr) {
            runtimeMultiplayerAuthoritativeMixEconomy(
                expectedEconomyHash,
                *expectedEconomy
            );
        }
        if (restoredEconomy != nullptr) {
            runtimeMultiplayerAuthoritativeMixEconomy(
                restoredEconomyHash,
                *restoredEconomy
            );
        }
        if (expectedEconomy == nullptr || restoredEconomy == nullptr
            || expectedEconomyHash != restoredEconomyHash) {
            differences.push_back("economy:" + owner);
        }
    }
    add(expected.computerAiByOwner.size()
            != restored.computerAiByOwner.size(),
        "computer-ai-count");
    add(expected.harvesterTasks.size() != restored.harvesterTasks.size(),
        "harvesters");
    add(expected.slaveMinerTasks.size() != restored.slaveMinerTasks.size(),
        "slave-miners");
    add(expected.repairingStructureTicks.size()
            != restored.repairingStructureTicks.size(),
        "repairs");
    add(expected.nextProjectileActorId != restored.nextProjectileActorId,
        "projectile-allocation");
    add(expected.projectiles.size() != restored.projectiles.size(),
        "projectiles");
    add(expected.recentExpiredProjectiles.size()
            != restored.recentExpiredProjectiles.size(),
        "expired-projectiles");
    add(expected.impactEffects.size() != restored.impactEffects.size(),
        "impacts");
    add(expected.skirmishCrates.size() != restored.skirmishCrates.size(),
        "crates");
    add(expected.initialOreFieldsSeeded != restored.initialOreFieldsSeeded
            || expected.initialOreCellsSeeded
                != restored.initialOreCellsSeeded
            || expected.initialOreCellsDensified
                != restored.initialOreCellsDensified,
        "initial-ore");
    add(expected.terrainObjectInitialStateCaptured
            != restored.terrainObjectInitialStateCaptured
            || expected.terrainObjectInitialLayoutSignature
                != restored.terrainObjectInitialLayoutSignature
            || expected.terrainObjectInitialStateByKey.size()
                != restored.terrainObjectInitialStateByKey.size(),
        "terrain-initial");
    add(expected.terrainInfoByCell.size()
            != restored.terrainInfoByCell.size(),
        "terrain-info");
    add(expected.bridgeHealthByCell.size()
            != restored.bridgeHealthByCell.size()
            || expected.bridgeRepairSpansByHut.size()
                != restored.bridgeRepairSpansByHut.size()
            || expected.destroyableBridges != restored.destroyableBridges
            || expected.bridgeSpecialFlagsLoaded
                != restored.bridgeSpecialFlagsLoaded,
        "bridges");
    add(expected.cloakStateInitialized != restored.cloakStateInitialized
            || expected.cloakObservedHealthByObject.size()
                != restored.cloakObservedHealthByObject.size(),
        "cloak");
    add(expected.visionEnabled != restored.visionEnabled, "vision");
    add(expected.gatesInitialized != restored.gatesInitialized
            || expected.gates.stateHash() != restored.gates.stateHash(),
        "gates");
    add(expected.garrisonsInitialized != restored.garrisonsInitialized
            || expected.garrisons.stateHash(expected.world.getObjects())
                != restored.garrisons.stateHash(restored.world.getObjects()),
        "garrisons");
    add(expected.subcellsInitialized != restored.subcellsInitialized
            || expected.subcells.stateHash(
                    expected.world.getObjects(),
                    expected.world.getTerrainObjects(),
                    runtimeGroundPoseContext(expected)
                ) != restored.subcells.stateHash(
                    restored.world.getObjects(),
                    restored.world.getTerrainObjects(),
                    runtimeGroundPoseContext(restored)
                ),
        "subcells");
    add(expected.repairDepotsInitialized
            != restored.repairDepotsInitialized
            || expected.repairDepots.stateHash()
                != restored.repairDepots.stateHash(),
        "repair-depots");
    add(expected.aircraftServicesInitialized
            != restored.aircraftServicesInitialized
            || expected.aircraftServices.stateHash()
                != restored.aircraftServices.stateHash(),
        "aircraft-services");
    add(expected.specialMechanismsInitialized
            != restored.specialMechanismsInitialized
            || expected.specialMechanisms.stateHash()
                != restored.specialMechanisms.stateHash(),
        "special-mechanisms");
    add(expected.spiesInitialized != restored.spiesInitialized
            || expected.spies.stateHash() != restored.spies.stateHash(),
        "spies");
    add(expected.particlesInitialized != restored.particlesInitialized
            || expected.particles.stateHash()
                != restored.particles.stateHash(),
        "particles");
    add(expected.superWeaponsInitialized
            != restored.superWeaponsInitialized
            || expected.superWeapons.stateHash()
                != restored.superWeapons.stateHash(),
        "superweapons");
    add(expected.deathWeapons.stateHash()
            != restored.deathWeapons.stateHash(),
        "death-weapons");
    add(expected.combatDetails.deterministicHash() != restored.combatDetails.deterministicHash(),
        "combat-details");
    add(expected.psychicStatuses.stateHash()
            != restored.psychicStatuses.stateHash(),
        "psychic-statuses");
    add(expected.magBeams.stateHash() != restored.magBeams.stateHash(),
        "mag-beams");
    add(expected.airstrikes.stateHash() != restored.airstrikes.stateHash(),
        "airstrikes");
    add(expected.factoryDeliveries.stateHash()
            != restored.factoryDeliveries.stateHash(),
        "factory-deliveries");
    add(runtimeClonePendingDeliveriesHash(expected)
            != runtimeClonePendingDeliveriesHash(restored),
        "clone-pending-deliveries");
    add(expected.playerCommands.stateHash() != restored.playerCommands.stateHash(), "player-commands");
    add(expected.grinding.stateHash() != restored.grinding.stateHash(),
        "grinding");
    add(expected.matchScores != restored.matchScores, "match-score");
    add(expected.skirmishMatchFinished != restored.skirmishMatchFinished
            || expected.multiplayerDefeatedOwners
                != restored.multiplayerDefeatedOwners
            || expected.multiplayerWinningOwners
                != restored.multiplayerWinningOwners
            || expected.multiplayerWinningTeams
                != restored.multiplayerWinningTeams,
        "outcome");
    if (differences.empty()) return "unreported-domain";
    std::ostringstream output;
    for (std::size_t index = 0; index < differences.size(); ++index) {
        if (index != 0U) output << ',';
        output << differences[index];
    }
    return output.str();
}

RuntimeCameraWorldBounds runtimeCameraWorldBounds(
    const RuntimeProductionHostState& state) {
    RuntimeCameraWorldBounds bounds;
    const RuntimeRadarProjection playableProjection =
        buildRuntimeRadarProjection(state);
    const int halfWidth = std::max(1, state.camera.tileWidth / 2);
    const int halfHeight = std::max(1, state.camera.tileHeight / 2);
    const auto accumulateBounds = [&](bool restrictToPlayableProjection) {
        for (const TerrainCell& cell : state.world.getTerrainCells()) {
            if (restrictToPlayableProjection
                && !runtimeRadarTerrainCellIntersectsProjection(
                    playableProjection,
                    cell
                )) {
                continue;
            }
            const int projectedX =
                ((cell.x - cell.y) * state.camera.tileWidth) / 2;
            const int projectedY =
                ((cell.x + cell.y) * state.camera.tileHeight) / 2
                - ((cell.level * state.camera.tileHeight) / 2);
            const int left = projectedX - halfWidth;
            const int right = projectedX + halfWidth;
            const int top = projectedY - halfHeight;
            const int bottom = projectedY + halfHeight;
            if (!bounds.valid) {
                bounds = RuntimeCameraWorldBounds{
                    left,
                    top,
                    right,
                    bottom,
                    true
                };
            } else {
                bounds.left = std::min(bounds.left, left);
                bounds.top = std::min(bounds.top, top);
                bounds.right = std::max(bounds.right, right);
                bounds.bottom = std::max(bounds.bottom, bottom);
            }
        }
    };
    accumulateBounds(playableProjection.valid);
    // A malformed but syntactically valid LocalSize must not disable camera
    // clamping.  If it intersects no decoded terrain, fall back to the actual
    // terrain envelope just as we do when LocalSize is absent.
    if (!bounds.valid && playableProjection.valid) {
        accumulateBounds(false);
    }
    return bounds;
}

RuntimeCameraRevealMargins runtimeCameraRevealMargins(
    const RuntimeProductionHostState& state,
    const RuntimeCameraWorldBounds& playableBounds,
    const RuntimeCameraWorldBounds* completedFullBounds) {
    const int horizontal = std::max(1, state.camera.tileWidth);
    const int foundationVertical = std::max(1, state.camera.tileHeight * 2);
    const int terrainTopOverhang = std::max(
        foundationVertical,
        state.camera.tileHeight * 4
    );
    int buildableArtHeight = 0;
    if (state.artLoaded && state.rulesLoaded) {
        for (const BuildingType& building : state.rules.getBuildingTypes()) {
            if (building.techLevel < 0 || building.cost <= 0) {
                continue;
            }
            const std::string artId = trimAsciiLocal(building.image).empty()
                ? building.id
                : trimAsciiLocal(building.image);
            const ArtType* art = state.art.findArtType(artId);
            if (art == nullptr || art->height <= 0) {
                continue;
            }
            buildableArtHeight = std::max(
                buildableArtHeight,
                art->height * std::max(4, state.camera.tileHeight / 3)
            );
        }
    }
    // Structure art is anchored at its foundation and grows primarily upward.
    // Keep the normal tile gutter on all sides, then enlarge only the upper
    // gutter to the tallest authored structure the player can actually build.
    RuntimeCameraRevealMargins reveal{
        horizontal,
        std::clamp(
            std::max(terrainTopOverhang, buildableArtHeight),
            terrainTopOverhang,
            240
        ),
        horizontal,
        foundationVertical
    };
    const RuntimeCameraWorldBounds fullBounds = completedFullBounds != nullptr
        ? *completedFullBounds : runtimeFullTerrainCameraWorldBounds(state);
    if (!playableBounds.valid || !fullBounds.valid) {
        return RuntimeCameraRevealMargins{};
    }

    // Never spend reveal reserve beyond decoded terrain.  Keep another half
    // tile outside each viewport edge so the physical saw-tooth map boundary
    // itself remains offscreen when LocalSize reaches the end of IsoMapPack5.
    const int halfWidth = std::max(1, state.camera.tileWidth / 2);
    const int halfHeight = std::max(1, state.camera.tileHeight / 2);
    const auto safeReveal = [](int desired, int available, int cover) {
        return std::min(desired, std::max(0, available) - cover);
    };
    reveal.left = safeReveal(
        reveal.left,
        playableBounds.left - fullBounds.left,
        halfWidth
    );
    reveal.top = safeReveal(
        reveal.top,
        playableBounds.top - fullBounds.top,
        halfHeight
    );
    reveal.right = safeReveal(
        reveal.right,
        fullBounds.right - playableBounds.right,
        halfWidth
    );
    reveal.bottom = safeReveal(
        reveal.bottom,
        fullBounds.bottom - playableBounds.bottom,
        halfHeight
    );
    return reveal;
}

int clampRuntimeCameraAxis(
    int offset,
    int worldMinimum,
    int worldMaximum,
    int viewportExtent) {
    const int worldExtent = std::max(0, worldMaximum - worldMinimum);
    viewportExtent = std::max(1, viewportExtent);
    if (worldExtent <= viewportExtent) {
        return worldMinimum - ((viewportExtent - worldExtent) / 2);
    }
    return std::clamp(
        offset,
        worldMinimum,
        worldMaximum - viewportExtent
    );
}

bool clampRuntimeMapCameraToPixels(
    RuntimeProductionHostState& state,
    const RuntimeInputPixelRect& viewport) {
    const bool referenceBounds = runtimeCameraBoundsPassReference();
    const RuntimeCombinedCameraBounds combined = referenceBounds
        ? RuntimeCombinedCameraBounds{} : runtimeMemoizedCameraWorldBounds(state);
    RuntimeCameraWorldBounds bounds = referenceBounds
        ? runtimeCameraWorldBounds(state) : combined.playable;
    if (!bounds.valid) {
        return false;
    }
    // Leave a small reveal reserve beyond the playable terrain envelope.  A
    // legal edge foundation may have tall or overhanging art, and a strict
    // terrain-only clamp makes that art impossible to inspect.
    const RuntimeCameraRevealMargins reveal =
        runtimeCameraRevealMargins(state, bounds, referenceBounds ? nullptr : &combined.full);
    bounds.left -= reveal.left;
    bounds.right += reveal.right;
    bounds.top -= reveal.top;
    bounds.bottom += reveal.bottom;
    const int viewportWidth = std::max(
        1,
        static_cast<int>(viewport.right - viewport.left)
    );
    const int viewportHeight = std::max(
        1,
        static_cast<int>(viewport.bottom - viewport.top)
    );
    const int clampedX = clampRuntimeCameraAxis(
        state.camera.worldOffsetX,
        bounds.left,
        bounds.right,
        viewportWidth
    );
    const int clampedY = clampRuntimeCameraAxis(
        state.camera.worldOffsetY,
        bounds.top,
        bounds.bottom,
        viewportHeight
    );
    // IsoMapPack cell coordinates form a diamond, but (x-y, x+y) projection
    // already turns that playable envelope into screen-aligned axes.  A second
    // diamond clamp here couples X/Y and prevents the viewport from reaching
    // legal projected corners.  Clamp the two projected axes independently.
    const bool changed = clampedX != state.camera.worldOffsetX
        || clampedY != state.camera.worldOffsetY;
    state.camera.worldOffsetX = clampedX;
    state.camera.worldOffsetY = clampedY;
    return changed;
}

bool selectionContains(const RuntimeProductionHostState& state, int objectId) {
    return std::find(
        state.selectedObjectIds.begin(),
        state.selectedObjectIds.end(),
        objectId
    ) != state.selectedObjectIds.end();
}

void removeSelectedObject(RuntimeProductionHostState& state, int objectId) {
    state.selectedObjectIds.erase(
        std::remove(
            state.selectedObjectIds.begin(),
            state.selectedObjectIds.end(),
            objectId
        ),
        state.selectedObjectIds.end()
    );
}

bool runtimeObjectAcceptsPlayerSelection(const RuntimeGameSessionState& state, const WorldObjectInstance& object) {
    // Frozen bodies remain hit-testable for hover health, but cannot enter
    // local click, box or keyboard selections. End-of-tick cleanup removes
    // a selection that was already active when the temporal beam connected.
    if (state.specialMechanismsInitialized
        && state.specialMechanisms.isTemporalFrozen(object.instanceId)) return false;
    if (runtimeObjectIsEnslavedSlaveWorker(state, object)) return false;
    // Stock V3ROCKET/DMISL/CMISL are targetable, hoverable MissileSpawn
    // aircraft with Selectable=no. Keep hit testing independent of selection.
    const auto* unit = findRuntimeUnitType(state.rules, object);
    return unit == nullptr || !unit->missileSpawn;
}

void addSelectedObject(RuntimeProductionHostState& state, int objectId) {
    const auto* object = findObjectById(state, objectId);
    if (object && !runtimeObjectAcceptsPlayerSelection(state, *object)) return;
    if (!runtimeFactoryDeliveryOwnsEgress(state, objectId)
        && !selectionContains(state, objectId)) {
        state.selectedObjectIds.push_back(objectId);
    }
}

const WorldObjectInstance* findObjectById(
    const RuntimeGameSessionState& state,
    int objectId) {
    const WorldObjectInstance* object =
        state.objectIndex.find(state.world.getObjects(), objectId);
    return object != nullptr && object->alive ? object : nullptr;
}

WorldObjectInstance* findMutableObjectById(
    RuntimeGameSessionState& state,
    int objectId) {
    WorldObjectInstance* object =
        state.objectIndex.find(state.world.accessObjects(), objectId);
    return object != nullptr && object->alive ? object : nullptr;
}

RuntimeInputPixelPoint approximateCellFromScreenPixelPoint(
    const RuntimeProductionHostState& state,
    const RuntimeInputPixelRect& viewport,
    RuntimeInputPixelPoint point) {
    if (!runtimeSessionGeometryAvailable(state)) throw std::logic_error("screen-surface picking is unsupported by this Session presentation provider");
    RuntimeMapRenderContext surfaceContext = runtimeTerrainMetadataContext(state);
    surfaceContext.art = state.artLoaded ? &state.art : nullptr;
    surfaceContext.rules = state.rulesLoaded ? &state.rules : nullptr;
    surfaceContext.mapFacts = state.mapFactsLoaded ? &state.mapFacts : nullptr;
    surfaceContext.palettePath = runtimePalettePath(state.config, state.report.map);
    surfaceContext.structureRootPath = runtimeStructureRootPath(state.config, state.report.map);
    surfaceContext.structurePalettePath = runtimeStructurePalettePath(state.config, state.report.map);
    RuntimeMapSurfaceCell surfaceCell{};
    if (state.geometry->pickRuntimeMapSurfaceCell(state.world, surfaceContext, state.camera,
            viewport, point, state.renderCache, surfaceCell)) {
        return {surfaceCell.x,surfaceCell.y};
    }

    // Untextured/asset-free diagnostic worlds keep the geometric fallback.
    // Normal gameplay uses the exact visible surface ownership above.
    const double worldX =
        static_cast<double>(point.x - viewport.left + state.camera.worldOffsetX);
    const double worldY =
        static_cast<double>(point.y - viewport.top + state.camera.worldOffsetY);
    const int tileWidth = std::max(1, state.camera.tileWidth);
    const int tileHeight = std::max(1, state.camera.tileHeight);
    const int x = static_cast<int>(
        std::floor((worldY / tileHeight) + (worldX / tileWidth) + 0.5)
    );
    const int y = static_cast<int>(
        std::floor((worldY / tileHeight) - (worldX / tileWidth) + 0.5)
    );

    RuntimeInputPixelPoint best{x, y};
    long long bestScore = std::numeric_limits<long long>::max();
    for (int dy = -5; dy <= 5; ++dy) {
        for (int dx = -5; dx <= 5; ++dx) {
            const RuntimeCellPoint candidate{x + dx, y + dy};
            const int key = runtimeCellKey(candidate.x, candidate.y);
            const auto terrainIt = state.terrainByCell.find(key);
            if (terrainIt == state.terrainByCell.end()
                || terrainIt->second == nullptr) {
                continue;
            }
            const RuntimeProjectedPoint projected =
                runtimeProjectCellXY(
                    candidate.x,
                    candidate.y,
                    terrainIt->second->level,
                    state.camera
                );
            const RuntimeInputPixelPoint center =
                runtimeScreenPixelPoint(projected, viewport, state.camera);
            const long long sx = static_cast<long long>(point.x - center.x);
            const long long sy = static_cast<long long>(point.y - center.y);
            const long long score = (sx * sx) + (sy * sy * 4);
            if (score < bestScore) {
                bestScore = score;
                best = {candidate.x, candidate.y};
            }
        }
    }

    return best;
}

int runtimeMaxHealthForObject(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const int authoredStrength = std::max(
        1,
        runtimeCachedCapabilityProfileForObject(state, object).ui.maxStrength
    );
    const std::string ownerKey = toLowerAsciiLocal(trimAsciiLocal(
        object.owner
    ));
    bool computerControlled =
        state.computerAiByOwner.find(ownerKey)
            != state.computerAiByOwner.end();
    for (std::size_t slotIndex = 0;
        !computerControlled && slotIndex < state.config.playerSlots.size();
        ++slotIndex) {
        const RuntimeConfig::PlayerSlot& slot =
            state.config.playerSlots[slotIndex];
        computerControlled = slot.enabled
            && !slot.human
            && ownerKey == toLowerAsciiLocal(
                runtimeSkirmishOwnerForSlot(slotIndex)
            );
    }
    const double difficultyScale = computerControlled
        ? runtimeDifficultyHealthScale(state, object.owner)
        : 1.0;
    return std::max(1, static_cast<int>(std::lround(
        static_cast<double>(authoredStrength)
            * difficultyScale
    )));
}

void applySelection(
    RuntimeProductionHostState& state,
    const std::vector<int>& objectIds,
    bool append,
    bool toggle) {
    if (!append && !toggle) {
        state.selectedObjectIds.clear();
    }

    bool selectionAdded = false;
    for (int objectId : objectIds) {
        const auto* object = findObjectById(state, objectId);
        if (object && !runtimeObjectAcceptsPlayerSelection(state, *object)) continue;
        if (toggle && selectionContains(state, objectId)) {
            removeSelectedObject(state, objectId);
        } else {
            selectionAdded =
                selectionAdded || !selectionContains(state, objectId);
            addSelectedObject(state, objectId);
        }
    }

    if (state.selectedObjectIds.empty()) {
        state.interactionStatus = "selection cleared";
    } else {
        state.interactionStatus =
            "selected " + std::to_string(state.selectedObjectIds.size());
        if (selectionAdded && !state.runtimeSuppressPlayerAudioFeedback) {
            if (const std::optional<std::string> voice =
                    runtimeVoiceEventForSelectedUnits(state, "select");
                voice.has_value()) {
                emitRuntimeSound(state, *voice);
            }
        }
    }
}

void setRuntimeObjectCell(
    RuntimeGameSessionState& state,
    WorldObjectInstance& object,
    const RuntimeCellPoint& point,
    bool resetRenderPosition) {
    RuntimePerfTraceScope movePhaseTrace("moveSetCell", state.tick);
    object.x = point.x;
    object.y = point.y;
    object.cell = runtimeCellKey(point.x, point.y);
    if (runtimeObjectMovementMode(state, object) == PathMovementMode::Air
        && object.airborne) {
        // Air movement is planar: crossing hills, cliffs, water, or bridges
        // must not pull the aircraft up and down with ground elevation.
        object.level = object.flightLevel;
        object.onBridge = false;
    } else {
        object.level = terrainLevelAtRuntimeCell(state, point.x, point.y);
        object.onBridge = runtimeCellIsBridge(state, point.x, point.y);
    }
    assignRuntimeInfantrySubcellAtCurrentLocation(state, object);
    if (resetRenderPosition) {
        object.hasRenderPosition = false;
        object.renderX = static_cast<double>(object.x);
        object.renderY = static_cast<double>(object.y);
        object.renderMoveActive = false;
        object.renderLevel = static_cast<double>(object.level);
        object.renderOnBridge = object.onBridge;
    }
    syncRuntimeTransportCargoPositions(state, object);
}

void clearRuntimeRenderPosition(WorldObjectInstance& object) {
    object.hasRenderPosition = false;
    object.renderX = static_cast<double>(object.x);
    object.renderY = static_cast<double>(object.y);
    object.renderMoveActive = false;
    object.renderLevel = static_cast<double>(object.level);
    object.renderOnBridge = object.onBridge;
}

void releaseRuntimeAircraftDock(WorldObjectInstance& object) {
    if (object.dockedToObjectId < 0 && object.dockIndex < 0) {
        return;
    }
    object.dockedToObjectId = -1;
    object.dockIndex = -1;
    object.airborne = false;
    object.flightLevel = object.level;
    clearRuntimeRenderPosition(object);
}

void releaseRuntimeAircraftSupportAuthority(WorldObjectInstance& object) {
    object.dockedToObjectId = -1;
    object.dockIndex = -1;
}

int runtimeAircraftCruiseLevel(const RuntimeGameSessionState& state) {
    int highestTerrainLevel = 0;
    for (const TerrainCell& terrain : state.world.getTerrainCells()) {
        highestTerrainLevel = std::max(
            highestTerrainLevel,
            runtimeEffectiveTerrainLevel(terrain)
        );
    }
    // Four height levels clear the tallest terrain while retaining the
    // existing isometric scale used by WorldObjectInstance::level.
    return highestTerrainLevel + 4;
}

void departRuntimeAircraftDock(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object) {
    // DeployToLand keeps the body on the ground until the explicit
    // undeploy transition owns takeoff. Attack/guard orders also pass here.
    const auto* deploymentUnit = findRuntimeUnitType(state.rules, object);
    if (deploymentUnit != nullptr && deploymentUnit->deployToLand
        && (runtimeObjectHasDeployedState(state, object)
            || runtimeMissionIsLandingToDeploy(object))) {
        return;
    }
    if (runtimeObjectMovementMode(state, object) == PathMovementMode::Air) {
        if (!object.airborne) {
            queueRuntimeAircraftAuxSound(state, object, true);
            const UnitType* unit = findRuntimeUnitType(state.rules, object);
            const int groundLevel = terrainLevelAtRuntimeCell(state, object.x, object.y);
            object.flightLevel = unit != nullptr && runtimeUnitUsesJumpjetMovement(*unit)
                ? groundLevel
                : runtimeAircraftCruiseLevel(state);
            object.airborne = true;
            refreshRuntimeObjectOccupancyAfterLocalChange(state);
        }
        object.level = object.flightLevel;
        object.onBridge = false;
    }
    if (object.dockedToObjectId < 0 || object.dockIndex < 0) {
        return;
    }
    if (runtimeFixedWingProfile(state, object)) { applyRuntimeFixedWingPose(state, object); return; }
    // A sortie vacates the visible pad but not the aircraft's support slot.
    // AirportBound capacity is a live-aircraft quota, so the same plane keeps
    // its host/index while airborne and can return to that pad later.
    clearRuntimeRenderPosition(object);
}

void beginRuntimeRenderMove(
    WorldObjectInstance& object,
    RuntimeObjectBehavior& behavior,
    const RuntimeCellPoint& from,
    const RuntimeCellPoint& to,
    double fromLevel,
    bool fromOnBridge,
    int cooldownTicks,
    RuntimeProductionHostState* context) {
    if (context && object.kind == WorldObjectKind::Unit
        && !context->pendingTransportTargets.empty()
        && runtimeCachedCapabilityProfileForObject(*context, object).transport.canTransport)
        cancelRuntimeTransportBoardingForMovingHost(*context, object.instanceId);
    behavior.moveSegmentFrom = from;
    behavior.renderFromOffsetX = behavior.renderFromOffsetY = 0.0;
    behavior.renderToOffsetX = behavior.renderToOffsetY = 0.0;
    const bool stoppedPose = worldObjectHasStoppedGroundPose(object);
    if (stoppedPose) {
        behavior.renderFromOffsetX = object.renderX - from.x;
        behavior.renderFromOffsetY = object.renderY - from.y;
        fromLevel = object.renderLevel;
        fromOnBridge = object.renderOnBridge;
    }
    if (context && object.kind == WorldObjectKind::Unit && !object.airborne) {
        if (object.hasRenderPosition && !stoppedPose) {
            behavior.renderFromOffsetX = object.renderX - from.x;
            behavior.renderFromOffsetY = object.renderY - from.y;
        }
        if (const auto dock = runtimeRepairDepotApproachPoint(*context, object, to)) {
            behavior.renderToOffsetX = (*dock)[0] - to.x;
            behavior.renderToOffsetY = (*dock)[1] - to.y;
        }
    }
    if (context && object.airborne && object.hasRenderPosition
        && runtimeCarrierHasDeckFlight(*context, object)) {
        behavior.renderFromOffsetX = object.renderX - from.x;
        behavior.renderFromOffsetY = object.renderY - from.y;
        fromLevel = object.renderLevel;
    }
    behavior.renderFrom = from;
    behavior.renderTo = to;
    behavior.renderFromLevel = fromLevel;
    behavior.renderToLevel = static_cast<double>(object.level);
    behavior.renderFromOnBridge = fromOnBridge;
    behavior.renderToOnBridge = object.onBridge;
    if (context && runtimeObjectUsesOmniCrushApproach(*context, object)
        && runtimeCellPointForObject(object) == from && from != to) {
        behavior.renderToLevel = terrainLevelAtRuntimeCell(*context, to.x, to.y);
        behavior.renderToOnBridge = runtimeCellIsBridge(*context, to.x, to.y);
    }
    if (runtimeInfantryMoveUsesCommittedCorner(object, behavior)) {
        const double stepDistance = std::hypot(double(to.x - from.x), double(to.y - from.y));
        const double distance = std::hypot(behavior.renderFromOffsetX, behavior.renderFromOffsetY)
            + stepDistance;
        cooldownTicks = static_cast<int>(std::clamp(std::ceil(cooldownTicks * distance / stepDistance),
            1.0, double(std::numeric_limits<int>::max() - 1)));
        behavior.moveCooldownTicks = cooldownTicks;
    } else if (context && stoppedPose && !object.airborne
        && (object.kind == WorldObjectKind::Infantry || object.kind == WorldObjectKind::Unit)
        && behavior.kind == RuntimeBehaviorKind::Move
        && behavior.transportTransferKind == RuntimeTransportTransferKind::None
        && runtimeTransportUnitBoardingPending(*context, object.instanceId)) {
        const auto intent = context->pendingTransportTargets.find(object.instanceId);
        if (intent != context->pendingTransportTargets.end()
            && intent->second == behavior.pendingAllowedOccupiedObjectId) {
            const double stepDistance = std::hypot(double(to.x - from.x), double(to.y - from.y));
            const double actualDistance = std::hypot(to.x + behavior.renderToOffsetX - from.x - behavior.renderFromOffsetX,
                to.y + behavior.renderToOffsetY - from.y - behavior.renderFromOffsetY);
            if (stepDistance > 0.0 && actualDistance > stepDistance) {
                cooldownTicks = static_cast<int>(std::clamp(std::ceil(cooldownTicks * actualDistance / stepDistance),
                    1.0, double(std::numeric_limits<int>::max() - 1)));
                behavior.moveCooldownTicks = cooldownTicks;
            }
        }
    }
    behavior.renderMoveTicksTotal = std::max(1, cooldownTicks);
    behavior.renderMoveTicksRemaining = behavior.renderMoveTicksTotal;
    // The visible body direction is a hard invariant of the active segment.
    // Turning is completed before this point, and no other subsystem may make
    // a moving unit render against (or sideways to) its actual displacement.
    alignRuntimeFacingToRenderMove(object, behavior);
    object.hasRenderPosition = true;
    object.renderX = static_cast<double>(from.x) + behavior.renderFromOffsetX;
    object.renderY = static_cast<double>(from.y) + behavior.renderFromOffsetY;
    object.renderMoveActive = true;
    object.renderLevel = fromLevel;
    object.renderOnBridge = fromOnBridge;
    // Keep same-tick nearby-body queries current when this segment is accepted.
    // Retaining old buckets is conservative and avoids rebuilding the army index.
    if (context && !object.airborne
        && !runtimeTrackGroundPoseSpatialMove(*context, object))
        invalidateRuntimeTickOccupancyCache(*context);
    if (context && object.airborne && runtimeJumpjetProfile(*context, object)) {
        const auto flight=context->jumpjetFlights.find(object.instanceId);
        if(flight!=context->jumpjetFlights.end() && flight->second.active)
            object.movementAnimationDistance=std::fmod(object.movementAnimationDistance
                +double(flight->second.progress)/runtimeJumpjetCellQ16,1024.0);
        applyRuntimeJumpjetPose(*context, object);
    }
}

bool runtimeGroundRenderStepWaitsForStoppedBody(RuntimeGameSessionState& state,
    const WorldObjectInstance& object, const RuntimeObjectBehavior& behavior) {
    if (!worldObjectHasGroundRenderPose(object) || !object.renderMoveActive
        || behavior.renderMoveTicksTotal <= 0 || behavior.renderMoveTicksRemaining <= 0
        || runtimeObjectMovementMode(state, object) == PathMovementMode::Air) return false;
    (void)runtimeTickOccupancyLookup(state);
    if (state.movementEmptyCellProof.additionalGroundPoseObjectIndices.empty()) return false;
    const double progress = runtimeVehicleMoveRenderProgressAtRemaining(behavior,
        std::max(0, behavior.renderMoveTicksRemaining - 1));
    const auto point = runtimeGroundRenderMovePoint(object, behavior, progress);
    return runtimeStoppedGroundPoseBlocksRenderMove(state, object, point[0], point[1]);
}

bool advanceRuntimeRenderMove(
    RuntimeProductionHostState& state,
    WorldObjectInstance& object,
    RuntimeObjectBehavior& behavior) {
    RuntimePerfTraceScope movePhaseTrace("moveRender", state.tick);
    if (behavior.renderMoveTicksTotal <= 0) {
        clearRuntimeRenderPosition(object);
        return false;
    }

    RuntimeInfantryWaterPoseQuery waterPose(state);
    const auto waterBefore = waterPose.pose(object);
    const double previousRenderX = object.renderX;
    const double previousRenderY = object.renderY;
    behavior.renderMoveTicksRemaining =
        std::max(0, behavior.renderMoveTicksRemaining - 1);
    const double progress = runtimeVehicleMoveRenderProgress(behavior);
    object.hasRenderPosition = true;
    object.renderMoveActive = true;
    const auto point = runtimeGroundRenderMovePoint(object, behavior, progress);
    object.renderX = point[0];
    object.renderY = point[1];
    alignRuntimeFacingToRenderMove(object, behavior);
    object.renderLevel =
        behavior.renderFromLevel
        + ((behavior.renderToLevel - behavior.renderFromLevel) * progress);
    object.renderOnBridge = progress < 0.5
        ? behavior.renderFromOnBridge
        : behavior.renderToOnBridge;

    object.movementAnimationDistance += std::hypot(
        object.renderX - previousRenderX,
        object.renderY - previousRenderY
    );
    if (object.movementAnimationDistance >= 1024.0) {
        object.movementAnimationDistance =
            std::fmod(object.movementAnimationDistance, 1024.0);
    }

    if (progress >= 1.0 && !runtimeOmniCrushPendingSegment(state, object, behavior)) {
        if (behavior.transportTransferKind == RuntimeTransportTransferKind::Boarding
            || behavior.renderToOffsetX != 0.0 || behavior.renderToOffsetY != 0.0) {
            object.renderMoveActive = false;
        } else clearRuntimeRenderPosition(object);
        behavior.renderMoveTicksTotal = 0;
        behavior.renderMoveTicksRemaining = 0;
        behavior.renderArrivalDistanceAfter = -1.0;
        behavior.renderStartupAccelerationDistance = 0.0;
        if (behavior.transportTransferKind == RuntimeTransportTransferKind::Egress) {
            if (behavior.kind == RuntimeBehaviorKind::Move
                && behavior.pendingAllowedOccupiedObjectId == behavior.transportTransferHostId
                && !state.pendingTransportTargets.contains(object.instanceId)) {
                behavior.pendingAllowedOccupiedObjectId = -1;
            }
            behavior.transportTransferHostId = -1;
            behavior.transportTransferKind = RuntimeTransportTransferKind::None;
        }
    }
    emitRuntimeInfantryWaterTransition(state, object, waterBefore, &waterPose);
    return true;
}

int runtimeFacingFromDelta(int dx, int dy) {
    if (dx == 0 && dy == 0) {
        return -1;
    }

    constexpr double pi = 3.14159265358979323846;
    const double screenDx = static_cast<double>(dx - dy);
    const double screenDy = static_cast<double>(dx + dy);
    double directionDegrees =
        std::atan2(screenDx, -screenDy) * 180.0 / pi;
    directionDegrees = std::fmod(directionDegrees + 360.0, 360.0);
    if (directionDegrees < 0.0) {
        directionDegrees += 360.0;
    }

    int facing = static_cast<int>(std::lround((directionDegrees / 360.0) * 256.0));
    facing %= 256;
    if (facing < 0) {
        facing += 256;
    }
    return facing;
}

int normalizeRuntimeFacing(int facing) {
    int normalized = facing % 256;
    if (normalized < 0) {
        normalized += 256;
    }
    return normalized;
}

int runtimeSignedFacingDelta(int from, int to) {
    int delta = normalizeRuntimeFacing(to) - normalizeRuntimeFacing(from);
    if (delta > 128) {
        delta -= 256;
    } else if (delta < -128) {
        delta += 256;
    }
    return delta;
}

int runtimeFacingAbsDifference(int left, int right) {
    return std::abs(runtimeSignedFacingDelta(left, right));
}

int runtimeTurnFacingToward(int current, int desired, int step) {
    current = normalizeRuntimeFacing(current);
    desired = normalizeRuntimeFacing(desired);
    if (step <= 0) return current;

    const int delta = runtimeSignedFacingDelta(current, desired);
    if (std::abs(delta) <= step) {
        return desired;
    }

    return normalizeRuntimeFacing(current + (delta > 0 ? step : -step));
}

bool runtimeObjectHasTurret(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    return runtimeObjectHasTurretCapability(state, object);
}

std::chrono::steady_clock::time_point runtimeSmokeNow() {
    return std::chrono::steady_clock::now();
}

double runtimeSmokeElapsedMs(
    std::chrono::steady_clock::time_point start) {
    return std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - start
    ).count();
}

int runtimeTurretTurnStep(const RuntimeGameSessionState& state, const WorldObjectInstance& object) {
    if (const auto* unit = findRuntimeUnitType(state.rules, object)) return std::clamp(unit->rot, 0, 127);
    if (const auto* building = findRuntimeBuildingType(state.rules, object)) return std::clamp(building->rot, 0, 127);
    return 0;
}

int runtimeBodyTurnStep(const RuntimeGameSessionState& state, const WorldObjectInstance& object) {
    const auto* unit = findRuntimeUnitType(state.rules, object);
    return unit ? std::clamp(unit->rot, 0, 127) : 0;
}

int runtimeAdvanceBodyFacing(const RuntimeGameSessionState& state, WorldObjectInstance& object,
    int current, int desired) {
    if (const auto* unit = runtimeJumpjetProfile(state, object)) {
        object.bodyFacingClock = {};
        return runtimeTurnFacingToward(current, desired, runtimeJumpjetTurnStep(state, *unit));
    }
    return runtimeAdvanceFacingClock(object.bodyFacingClock, current, desired,
        runtimeBodyTurnStep(state, object), state.tick, state.config.fixedTickHz);
}

bool updateRuntimeMoveFacingToward(
    const RuntimeGameSessionState& state,
    WorldObjectInstance& object,
    const RuntimeCellPoint& from,
    const RuntimeCellPoint& to) {
    const int desiredFacing = runtimeMoveTargetFacing(state, object, from, to);
    if (desiredFacing < 0) {
        return true;
    }

    if (!runtimeJumpjetCanEnter(state, object, to)) return false;
    if ((object.kind == WorldObjectKind::Infantry && !runtimeJumpjetProfile(state, object)) || object.facing < 0) {
        object.facing = desiredFacing;
        return true;
    }

    const int nextFacing = runtimeAdvanceBodyFacing(state, object, object.facing, desiredFacing);
    object.facing = nextFacing;
    return nextFacing == desiredFacing;
}

bool runtimeObjectIsPoisonImmune(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& target) {
    if (target.kind == WorldObjectKind::Structure) {
        const BuildingType* building = findRuntimeBuildingTypeById(state.rules, target.type);
        return building != nullptr && building->immuneToPoison;
    }
    const UnitType* unit = findRuntimeUnitType(state.rules, target);
    return unit != nullptr && unit->immuneToPoison;
}

bool runtimeObjectIsAirTarget(
    const RuntimeGameSessionState&,
    const WorldObjectInstance& object) {
    // Locomotor and aircraft type describe flight capability. The current
    // flight authority decides the target domain, including landed choppers,
    // parachuting infantry and suspended ground vehicles.
    return object.kind != WorldObjectKind::Structure && object.airborne;
}

bool runtimeObjectIsTiberiumProof(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    const UnitType* unit = findRuntimeUnitType(state.rules, object);
    return (unit != nullptr && unit->tiberiumProof)
        || runtimeVeterancyHasAbility(
            state,
            object,
            VeteranAbility::TiberiumProof
        );
}

RuntimeParticleSpawnResult spawnRuntimeArtAnimationParticles(
    RuntimeGameSessionState& state,
    const std::string& animationId,
    const RuntimeParticleSpawnContext& context) {
    const std::string authoredId = trimAsciiLocal(animationId);
    if (authoredId.empty()) {
        return {};
    }
    const ArtType* animation = state.art.findArtType(authoredId);
    if (animation == nullptr) {
        return {};
    }

    ensureRuntimeParticlesInitialized(state);
    return state.particles.spawnFromAnimation(
        state.rules,
        *animation,
        context
    );
}

void removeRuntimeSelection(RuntimeProductionHostState& state, int objectId) {
    removeSelectedObject(state, objectId);
}

bool eraseRuntimeBehavior(RuntimeProductionHostState& state, int objectId) {
    const auto previous = state.behaviors.find(objectId);
    WorldObjectInstance* object = findMutableObjectById(state, objectId);
    if (object && previous != state.behaviors.end()
        && runtimeCancelledStructureEntryNeedsRecovery(state, *object, previous->second)
        && !recoverRuntimeCancelledStructureEntry(state, *object, previous->second)) return false;
    const auto chronoEntry = state.pendingTransportTargets.find(objectId);
    const auto* warp = state.specialMechanisms.chronoMoveState(objectId);
    const auto* chronoType = object ? findRuntimeUnitType(state.rules, *object) : nullptr;
    const auto* chronoHost = chronoEntry != state.pendingTransportTargets.end()
        ? findRuntimeObjectByIdIncludingInactive(state, chronoEntry->second) : nullptr;
    if (object && object->kind == WorldObjectKind::Infantry && chronoType
        && chronoType->teleporter && !chronoType->harvester && chronoHost
        && chronoHost->kind == WorldObjectKind::Unit && warp
        && previous != state.behaviors.end() && previous->second.kind == RuntimeBehaviorKind::Move
        && previous->second.pendingAllowedOccupiedObjectId == chronoHost->instanceId
        && warp->destination.x == previous->second.moveTarget.x
        && warp->destination.y == previous->second.moveTarget.y)
        state.specialMechanisms.cancelChronoMoveInTransit(objectId);
    cancelRuntimeDiskDrainSource(state, objectId);
    state.gattlingWeaponTimers.erase(objectId);
    if (state.combatDetails.panics.erase(objectId) != 0) {
        if (auto* stopped = findMutableObjectById(state, objectId); stopped && stopped->mission == "Panic")
            stopped->mission = "Guard";
    }
    if (state.specialMechanismsInitialized && previous != state.behaviors.end()
        && previous->second.kind == RuntimeBehaviorKind::Attack) {
        state.specialMechanisms.clearTemporalAttacker(objectId,
            previous->second.targetObjectId, state.tick, runtimeSpecialEventSink(state),
            "attack order removed");
    }
    const bool cancelsMcvDeploy = object && runtimeMissionIsMcvDeployPending(*object);
    if (object == nullptr || !object->alive || !object->airborne || !runtimeJumpjetProfile(state, *object))
        state.jumpjetFlights.erase(objectId);
    if (object != nullptr && object->renderMoveActive) {
        if (previous != state.behaviors.end()
            && previous->second.transportTransferKind == RuntimeTransportTransferKind::Boarding) {
            // Boarding has not committed the hull cell or lost its original slot.
            // Cancelling the intent therefore leaves a valid ordinary stopped pose.
            object->renderMoveActive = false;
        } else clearRuntimeRenderPosition(*object);
    }
    if (object && object->alive && object->airborne && runtimeFixedWingProfile(state, *object)) {
        const auto flight=state.aircraftFlights.find(objectId);
        if(flight!=state.aircraftFlights.end())flight->second.moving=false;
        applyRuntimeFixedWingPose(state,*object);
    } else state.aircraftFlights.erase(objectId);
    releaseRuntimeInfantrySubcellReservation(state, objectId);
    state.behaviors.erase(objectId);
    if (cancelsMcvDeploy) invalidateRuntimeTickOccupancyCache(state);
    state.pendingEngineerCaptures.erase(objectId);
    state.pendingEngineerActions.erase(objectId);
    state.pendingOccupyTargets.erase(objectId);
    state.pendingTransportTargets.erase(objectId);
    state.pendingTimedBombIntents.erase(objectId);
    return true;
}

void cancelRuntimeTimedBombIntentForSource(
    RuntimeProductionHostState& state,
    int sourceObjectId,
    const std::string& reason) {
    const auto pending = state.pendingTimedBombIntents.find(sourceObjectId);
    if (pending == state.pendingTimedBombIntents.end()) {
        return;
    }
    WorldObjectInstance* source = findMutableObjectById(
        state,
        sourceObjectId
    );
    if (!eraseRuntimeBehavior(state, sourceObjectId)) return;
    if (source != nullptr && source->alive) {
        setRuntimeMissionIntent(
            state,
            *source,
            RuntimeMissionIntent::Idle,
            reason
        );
        clearRuntimeRenderPosition(*source);
    }
}

void cancelRuntimeTimedBombIntentsForTarget(
    RuntimeProductionHostState& state,
    int targetObjectId,
    int exceptSourceObjectId,
    const std::string& reason) {
    std::vector<int> sources;
    for (const auto& [sourceObjectId, intent] :
            state.pendingTimedBombIntents) {
        if (sourceObjectId != exceptSourceObjectId
            && intent.kind == RuntimeTimedBombIntentKind::C4
            && intent.targetObjectId == targetObjectId) {
            sources.push_back(sourceObjectId);
        }
    }
    std::sort(sources.begin(), sources.end());
    for (int sourceObjectId : sources) {
        cancelRuntimeTimedBombIntentForSource(
            state,
            sourceObjectId,
            reason
        );
    }
}

bool runtimeOwnerTransitionObjectIsRetained(
    const RuntimeGameSessionState& state,
    const WorldObjectInstance& object) {
    if (object.alive && object.health > 0) {
        return true;
    }
    if (object.alive || object.health <= 0) {
        return false;
    }
    if (object.garrisonHostObjectId >= 0) {
        return true;
    }
    if (toLowerAsciiLocal(trimAsciiLocal(object.mission))
        != "insidetransport") {
        return false;
    }
    return std::any_of(
        state.world.getObjects().begin(),
        state.world.getObjects().end(),
        [&object](const WorldObjectInstance& transport) {
            return transport.alive
                && std::find(
                    transport.transportPassengerIds.begin(),
                    transport.transportPassengerIds.end(),
                    object.instanceId
                ) != transport.transportPassengerIds.end();
        }
    );
}

