bool applyRuntimeOwnerTransitionRepairActions(
    RuntimeProductionHostState& scratch,
    const std::vector<RuntimeRepairDepotAction>& actions,
    std::set<int>& materializedActorIds,
    std::string& error) {
    for (const RuntimeRepairDepotAction& action : actions) {
        WorldObjectInstance* unit =
            findMutableRuntimeObjectByIdIncludingInactive(
                scratch,
                action.unitId
            );
        if (unit == nullptr || !unit->alive || unit->health <= 0) {
            error = "repair transition references an unavailable unit";
            return false;
        }
        if (action.kind
                == RuntimeRepairDepotActionKind::TransferDockedUnitOwner) {
            if (action.newOwner.empty()
                || unit->dockedToObjectId != action.hostId
                || unit->dockIndex != action.dockIndex
                || toLowerAsciiLocal(trimAsciiLocal(unit->owner))
                    != toLowerAsciiLocal(trimAsciiLocal(
                        action.expectedOwner
                    ))) {
                error = "repair transfer action failed detached preflight";
                return false;
            }
            unit->hasBeenCaptured = unit->hasBeenCaptured || unit->owner != action.newOwner;
            unit->owner = action.newOwner;
            eraseRuntimeBehavior(scratch, action.unitId);
            setRuntimeMissionIntent(
                scratch,
                *unit,
                RuntimeMissionIntent::Repairing,
                "ownerTransitionRepairTransfer"
            );
            clearRuntimeRenderPosition(*unit);
            materializedActorIds.insert(action.unitId);
            continue;
        }
        if (action.kind != RuntimeRepairDepotActionKind::Release) {
            error = "owner transition produced an unsafe repair action";
            return false;
        }

        const bool wasDocked = unit->dockedToObjectId == action.hostId
            && unit->dockIndex == action.dockIndex;
        if (wasDocked) {
            unit->dockedToObjectId = -1;
            unit->dockIndex = -1;
            clearRuntimeRenderPosition(*unit);
        }
        eraseRuntimeBehavior(scratch, action.unitId);
        if (action.hasTargetCell) {
            queueRuntimeRepairDepotExactMove(
                scratch,
                *unit,
                action.targetCell,
                -1,
                false,
                "ownerTransitionRepairRelease"
            );
        } else {
            setRuntimeMissionIntent(
                scratch,
                *unit,
                RuntimeMissionIntent::Idle,
                "ownerTransitionRepairRelease"
            );
        }
        materializedActorIds.insert(action.unitId);
    }
    return true;
}

